SELECT 'moj-all-verified-judgments-review-002-chunk-022' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d3343d2e-cda7-5614-b063-318126cf290e","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة زوجة بنفقتها ونفقة ابنتها املاضية واملستقبلية -تقدير النفقة املاضية واملستقبلية عن طريق قسم اخلبراء - النفقة بنية الرجوع -مطالبة باستخراج تبليغ والدة وشهادة مياد -مطالبة بإضافة مولود يف دفتر العائلة -حلف اليمن بنية الرجوع على املدعى عليه مبا انفقته على االبنة -حكم بتسليم نفقة ماضية ونفقة مستقبلية -حكم باستخراج تبليغ والدة وشهادة مياد -احلكم بإضافة مولود يف دفتر العائلة -صرف","document_number":"3440861","case_number":"33245651","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/18","year":"1434","subject":"نفقة -مطالبة زوجة بنفقتها ونفقة ابنتها املاضية واملستقبلية -تقدير النفقة املاضية واملستقبلية عن طريق قسم اخلبراء - النفقة بنية الرجوع -مطالبة باستخراج تبليغ والدة وشهادة مياد -مطالبة بإضافة مولود يف دفتر العائلة -حلف اليمن بنية الرجوع على املدعى عليه مبا انفقته على االبنة -حكم بتسليم نفقة ماضية ونفقة مستقبلية -حكم باستخراج تبليغ والدة وشهادة مياد -احلكم بإضافة مولود يف دفتر العائلة -صرف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/18 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3440861 :‬‬\n                   ‫َر ْق ُم الدعوى‪33245651 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34201329‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬مطالبــة زوجــة بنفقتهــا ونفقــة ابنتهــا املاضيــة واملســتقبلية‬\n‫‪ -‬تقديــر النفقــة املاضيــة واملســتقبلية عــن طريــق قســم اخلبــراء ‪-‬‬\n‫النفقــة بنيــة الرجــوع ‪ -‬مطالبــة باســتخراج تبليــغ والدة وشــهادة‬\n‫ميــاد ‪ -‬مطالبــة بإضافــة مولــود يف دفتــر العائلــة ‪ -‬حلــف اليمــن‬\n‫بنيــة الرجــوع علــى املدعــى عليــه مبــا انفقتــه علــى االبنــة ‪ -‬حكــم‬\n‫بتســليم نفقــة ماضيــة ونفقــة مســتقبلية ‪ -‬حكــم باســتخراج تبليــغ‬\n‫والدة وشــهادة ميــاد ‪ -‬احلكــم بإضافــة مولــود يف دفتــر العائلــة ‪ -‬صــرف‬\n‫النظــر عــن طلــب الزوجــة نفقتهــا املاضيــة لنشــوزها ‪ -‬تنــازل عــن نفقــة‬\n                                                                ‫محكــوم بهــا‪.‬‬\n\n\n\n\n‫ذكــر البهوتــى يف شــرح املنتهــى ‪ « 242/3‬ولــو امتنــع منهــا أي النفقــة‬\n‫زوج أو قريــب فأنفــق عليهمــا غيــره رجــع منفــق علــى زوج أو قريــب بنيــة‬\n‫رجــوع ألن االمتنــاع قــد يكــون لضعــف مــن وجبــت لــه وقــوة مــن وجبــت‬\n                  ‫عليــه فلــو لــم ميلــك املنفــق الرجــوع لضــاع الضعيــف»‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه زوجها ذهب بها إلــى بيت أهلها يف‬\n‫‪1431/1 1/5‬ه ـ وتركهــا عندهــم حتــى تاريــخ إقامــة الدعــوى ولــم ينفــق‬\n\n                                                                                 ‫‪38‬‬\n\f     ‫عليهــا خــال هــذه املــدة كمــا أنهــا رزقــت منــه ببنــت يف ‪1432/7/3‬ه ـ‬\n     ‫ولــم ينفــق عليهــا مــن والدتهــا إلــى وقــت إقامــة الدعــوى وإنهــا أنفقــت‬\n     ‫عليهــا شــهريا ألــف ريــال ناويــة الرجــوع علــى املدعــى عليــه كمــا أن‬\n     ‫املدعــى عليــه لــم يســتخرج تبليــغ والدة وال شــهادة ميــاد ولــم يضيــف‬\n     ‫ابنتــه يف كــرت العائلــة وطالبــت املدعيــة إلــزام املدعــى عليــه بتقديــر‬\n     ‫نفقــة شــهرية لهــا والبنتهــا وإلــزام املدعــى عليه بــأن يســلمها نفقتها للمدة‬\n     ‫املاضيــة واملســتقبلية وان يســلمها مــا أنفقتــه علــى ابنتهــا املــدة املاضيــة‬\n     ‫وان يســتخرج للبنــت تبليــغ والدة وشــهادة ميــاد وان يضيــف البنــت يف‬\n     ‫كــرت العائلــة‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر انــه‬\n     ‫لــم يســتخرج تبليــغ والدة ألنــه ال يعــرف أيــن ولــدت املدعيــة كمــا أن‬\n     ‫املدعيــة ال تســتحق النفقــة ألنهــا ناشــز‪ ،‬ثبــت لــدى ناظــر القضيــة بــأن‬\n     ‫املدعيــة ناشــز‪ ،‬مت تقديــر نفقــة للبنــت مــن قبــل قســم اخلبــراء ســتمائة‬\n     ‫ريــال شــهري ًا ‪ ،‬جــرى عــرض اليمــن علــى املدعيــة إنهــا كانــت تنفــق‬\n     ‫علــى البيــت بنيــة الرجــوع فحلفــت علــى ذلــك‪ ،‬قــرر ناظــر القضيــة‬\n     ‫لألســباب املرصــودة يف نــص القضيــة باحلكــم علــى املدعــى عليــه إن‬\n     ‫يســلم نفقــة شــهرية البنتــه مبلغــا قــدره ســتمائة ريــال مــن ‪1434/2/3‬ه ـ‬\n     ‫وتســليم النفقــة املاضيــة مبلغــا قــدره احــد عشــر ألفـ ًا وأربعمائــة ريــال مــن‬\n     ‫والدتهــا وحتــى ‪1434/2/2‬هــ‪ ،‬وإن يســتخرج تبلــغ والدة البنتــه وشــهادة‬\n     ‫ميــاد وان يضيفهــا إلــى دفتــر العائلــة‪ ،‬مت تصديــق احلكــم من محكمة‬\n     ‫االســتئناف بالريــاض‪ ،‬حضــرت املدعيــة وتنازلــت عــن مبلــغ قــدره عشــرة‬\n                           ‫اآلف ريــال مــن النفقــة احملكــوم بهــا ســابقا البنتهــا ‪.‬‬\n\n\n\n\n‫‪39‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم االثنــن املوافــق ‪1433/08/26‬ه ـ حضــرت‪).....( /‬‬\n‫الســجل املدنــي رقــم (‪ ).....‬واملعــرف بهــا مــن قبــل والدهــا‪ ).....(/‬حامــل‬\n‫الســجل املدنــي رقــم(‪ ،:).....‬ولــم يحضــر املدعــى عليــه (‪ ،).....‬والــذي‬\n‫جــرى تبليغــه مبوعــد هــذه اجللســة لشــخصه عــن طريــق مرجعــه مبوجــب‬\n‫خطــاب مديــر إدارة شــؤون املوظفــن مبدينــة ‪ ...‬برقــم‪ ... :‬يف ‪ ...‬املرفــق‬\n‫بــه منــوذج التبليــغ موقعــا مــن املدعــى عليــه؛ لــذا قــررت ســماع الدعــوى‬\n‫غيابيــا‪ ،‬وقــد ادعــت املدعيــة قائلــة يف دعواهــا‪ :‬إن املدعــى عليــه زوجــي‪،‬‬\n‫وقــد ذهــب بــي إلــى بيــت أهلــي بتاريــخ ‪1431/11/5‬ه ـ وتركنــي عندهم‬\n‫حتــى اآلن‪ ،‬ولــم ينفــق علــي خــال تلــك املــدة كمــا أننــي رزقت منــه ببنت‬\n‫يف ‪1432/7/3‬ه ـ ولــم ينفــق عليهــا مــن والدتهــا إلــى وقتنــا احلاضــر‪ ،‬وقــد‬\n‫أنفقــت عليهــا شــهريا مــا ال يقــل عــن ألــف ريــال ناويــة الرجــوع بهــا علــى‬\n‫املدعــى عليــه‪ ،‬كمــا أنــه لــم يســتخرج لهــا تبليــغ والدة وال شــهادة ميــاد‬\n‫ولــم يضفهــا يف دفتــر عائلتــه‪ ،‬وأطلــب تقديــر نفقــة شــهرية لــي والبنتــي‪،‬‬\n‫وإلــزام املدعــى عليــه بــأن يســلمني نفقتــي للمــدة املاضيــة واملســتقبلية‪،‬‬\n‫وأن يســلمني مــا أنفقتــه علــى ابنتــه للمــدة املاضيــة‪ ،‬وأن يســلمني نفقتهــا‬\n‫للمــدة املســتقبلية وأن يســتخرج لهــا تبليــغ والدة وشــهادة ميــاد‪ ،‬وأن‬\n‫يضيفهــا يف دفتــر عائلتــه‪ ،‬هــذه دعــواي‪ .‬فســألت املدعيــة البينــة علــى‬\n‫دعواهــا فقالــت‪ :‬نعــم‪ ،‬ووعــدت بإحضارهــا يف اجللســة القادمــة ‪ .‬ويف‬\n‫يــوم األحــد املوافق‪1433/11/21‬ه ـ حضــرت املدعيــة املعــرف بهــا مــن‬\n‫قبــل والدهــا ‪ ،‬كمــا حضــر املدعــى عليــه حامــل الســجل املدنــي رقــم‬\n\n                                                                                       ‫‪40‬‬\n\f     ‫ومتــت تــاوة الدعــوى عليــه وطلبــت منــه اإلجابــة عنهــا فقــال ‪ :‬مــا ذكرتــه‬\n     ‫املدعيــة مــن أننــي ذهبــت بهــا إلــى بيــت أهلهــا بتاريــخ ‪1431/11/5‬ه ـ‬\n     ‫وأنهــا عندهــم حتــى اآلن وأننــي لــم أنفــق عليهــا خــال تلــك املــدة وأننــي‬\n     ‫رزقــت منهــا ببنــت يف ‪1432/7/3‬ه ـ وأننــي لــم أنفــق عليهــا مــن والدتهــا‬\n     ‫إلــى وقتنــا احلاضــر وأننــي لــم اســتخرج لهــا تبليــغ والدة وال شــهادة ميــاد‬\n     ‫وأننــي لــم أضفهــا يف دفتــر عائلتــي فصحيــح ولــم اســتخرج تبليــغ الــوالدة‬\n     ‫ألنــي ال أعلــم يف أي مستشــفى ولــدت ومــا ذكرتــه املدعيــة مــن أننــي‬\n     ‫تركتهــا عنــد اهلهــا فغيــر صحيــح والصحيــح أنهــا هــي التــي رفضــت‬\n     ‫العــودة لــي فــا تســتحق النفقــة لكونهــا ناشــزا هكــذا أجــاب ‪،‬‬\n     ‫وبعــرض ذلــك علــى املدعيــة قالــت ‪ :‬إننــي رفضــت العــودة للمدعــى عليــه‬\n     ‫يف ذلــك الوقــت ألننــي كنــت حامــا وكنــت أتوحــم واآلن لــن أرجــع لــه‬\n     ‫لكونــه قــد أهاننــي هكــذا أجابــت ‪ ،‬فقــررت الكتابــة لقســم اخلبــراء‬\n     ‫لتحديــد النفقــة الشــهرية البنــة الطرفــن للمــدة املاضيــة واملســتقبلية‪.‬‬\n     ‫ويف يــوم االثنــن املوافق‪1434/02/18‬ه ـ حضــرت املدعيــة واملعــرف بهــا‬\n     ‫مــن قبــل أبيهــا واملدعــى عليــه ‪ ،‬فســألت املدعيــة يف أي مستشــفى ولــدت‬\n     ‫ابنتهــا‪ ،‬فقالــت‪ :‬يف مستشــفى (‪ ).....‬اجلامعــي ‪،‬هكــذا أجابــت ‪،‬وقــد‬\n     ‫وردنــي قــرار مكتــب الصلــح رقــم‪ 61:‬يف ‪1434/1/20‬ه ـ واملتضمــن‬\n     ‫تقديــر نفقــة الطفلــة الشــهرية بســتمائة ريال‪،‬فجــرى عــرض اليمــن‬\n     ‫علــى املدعيــة أنهــا أنفقــت علــى ابنتهــا مــن املدعــى عليــه مــاال يقــل علــى‬\n     ‫ســتمائة ريــال شــهريا مــن تاريــخ والدتهــا إلــى وقتنــا احلاضــر بنيــة الرجــوع‬\n     ‫علــى املدعــى عليه‪،‬فاســتعدت ببذلهــا ‪،‬ثــم حلفــت قائلــة (واهلل الــذي‬\n     ‫ال إلــه إال هــو إننــي قــد أنفقــت علــى ابنتــي مــن املدعــى عليــه مــن تاريــخ‬\n     ‫والدتهــا يف ‪1432/7/3‬ه ـ إلــى وقتنــا احلاضــر مــاال يقــل عن ســتمائة ريال‬\n\n\n‫‪41‬‬\n\f‫شــهريا ناويــة الرجــوع مبــا أنفقــت علــى املدعــى عليه)هكــذا حلفــت‪،‬‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعيــة تعتبــر ناشــزا‬\n‫خــال الفتــرة التــي تطالــب بالنفقــة لهــا حيث أقــرت بأنها رفضــت العودة‬\n‫إلــى املدعــى عليــه عندمــا كانــت حامــا وأنهــا اآلن لــن ترجــع إليــه وبنــاء‬\n‫علــى قــرار قســم الصلــح وميــن املدعيــة وبنــاء علــى مــا قــرره أهــل العلــم‬\n‫حيــث ذكــر البهوتــي يف شــرح املنتهــى (‪ )242/3‬مانصــه (ولــو امتنــع‬\n‫منهــا أي النفقــة زوج أو قريــب فأنفــق عليهمــا غيــره رجــع منفــق علــى‬\n‫زوجــة أو قريــب بنيــة رجــوع ألن االمتنــاع قــد يكــون لضعــف مــن وجبــت‬\n‫لــه وقــوة مــن وجبــت عليــه فلــو لــم ميلــك املنفــق الرجــوع لضــاع الضعيــف)‬\n‫لــذا فقــد حكمــت علــى املدعــى عليــه بــأن يســلم للمدعيــة أحــد عشــر‬\n‫ألفــا وأربعمائــة ريــال عــن مــا أنفقتــه علــى ابنتــه منهــا مــن تاريــخ والدتهــا‬\n‫إلــى تاريخ‪1434/2/2‬ه ـ وأن يســلم املدعــى عليــه للمدعيــة نفقــة شــهرية‬\n‫البنتــه منهــا قدرهــا ســتمائة ريــال ابتــداء مــن ‪1434/2/3‬ه ـ ‪،‬وأن‬\n‫يســتخرج البنتــه املذكــورة تبليــغ والدة وشــهادة ميــاد وأن يضيفهــا يف‬\n‫دفتــر عائلتــه ورددت دعــوى املدعيــة يف املطالبــة مبــا زاد علــى النفقــة‬\n‫احملكــوم بهــا البنتهــا ويف املطالبــة بنفقتهــا وأخليــت ســبيل املدعــى عليــه‬\n‫مــن ذلــك وبذلــك حكمــت‪ ،‬وبعــرض احلكــم علــى الطرفــن قنعــت بــه‬\n‫املدعيــة ولــم يقنــع بــه املدعــى عليــه وطلــب االســتئناف فأجبتــه لطلبــه‬\n‫وقــررت تســليمه صــورة مــن صــك احلكــم حــاال لتقــدمي معارضتــه عليــه‬\n‫خــال مــدة ال تتجــاوز ثالثــن يومــا فــإن تأخــر عــن ذلــك ســقط حقــه‬\n‫يف تقــدمي الالئحــة االعتراضيــة واكتســب احلكــم القطعيــة‪ .‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪ 1434/02/18‬ه ـ ‪.‬‬\n\n\n                                                                                           ‫‪42‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ففــي يوم األحد املوافق ‪1434/05/19‬هـ افتتحت‬\n     ‫اجللســة الســاعة ‪ 09:45‬وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n     ‫بالريــاض وقــد همــش علــى ظهــر الصــك مبــا نصــه (تظهيــرات الدائــرة‬\n     ‫الثانيــة لألحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف مبنطقــة‬\n     ‫الريــاض ‪ ،‬احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n     ‫‪ 3440861‬وتاريــخ ‪1434/02/18‬ه ـ الصــادر مــن فضيلــة الشــيخ (‪).....‬‬\n     ‫وأصدرنــا القــرار رقــم ‪ 34201329‬وتاريــخ ‪1434/04/29‬ه ـ املتضمــن‬\n     ‫املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬عضــو ختمــه وتوقيعــه عضــو‬\n     ‫ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه ‪ ) .‬وكان ختــام هــذه‬\n     ‫اجللســة الســاعة ‪ 10:00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا‬\n                 ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/05/19‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ،‬فلــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامــة‬\n     ‫بالريــاض خلف ـ ًا لفضيلــة الشــيخ النتقالــه مــن هــذه احملكمــة ويف يــوم‬\n     ‫االثنــن املوافــق ‪1434/12/02‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n     ‫والربــع ‪ ،‬وبنــاء علــى الصــك الصــادر منــا برقــم ‪ 34368950‬يف‬\n     ‫‪1434/11/25‬ه ـ املتضمــن تنــازل املدعيــة ‪ ).....(/‬عــن مبلــغ قــدره عشــرة‬\n     ‫آالف ريــال مــن النفقــة احملكــوم بهــا لهــا نفقــة ماضيــة البنتهــا ‪ ،‬ولكــي‬\n     ‫ال يخفــى جــرى حتريــره وأمــرت بالتهميــش بذلــك علــى الصــك وســجله ‪،‬‬\n     ‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                       ‫‪ .‬حــرر يف ‪1434/12/02‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n     ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n     ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n\n\n‫‪43‬‬\n\f‫بالريــاض املســاعد برقــم ‪ 33658319‬وتاريــخ ‪1434/4/9‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ (‪).....‬‬\n‫املســجل برقــم ‪ 3440861‬وتاريــخ ‪1434/2/18‬ه ـ اخلــاص بدعــوى (‪).....‬‬\n‫ضــد (‪ ،).....‬يف قضيــة نفقــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم‪،‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪44‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":38,"source_page_end":44,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"375fc55cdf668a960a4497a79571b6f579857973c2984d6db42870ce36a0e996","normalized_text_hash":"4eb09d9a577607dff01e0f158c36c705a1d812c834fd2e2677a70d657682b5ab","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p38-3440861"},{"id":"69813516-d56b-5529-b1ca-0203a5d8eeb6","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة أوالد -املطالبة بالنفقة املاضية -املطالبة بالنفقة املستقبلية -املطالبة بتسليم شهادة املياد ودفتر العائلة -غياب املدعى عليه يعتبر نكو ال عن اجلواب -القول قول الغارم بيمينه- حلف الزوجة اليمني -تقدير النفقة عن طريق قسم اخلبراء -احلكم على األب بدفع نفقة أوالده املاضية واملستقبلية -احلكم على األب بتسليم األم األوراق الثبوتية ألوالدها الذين يف حضانتها -شمول احلكم بالنفقة وإخراج شهادة املياد وإسقاط املدعية من سجل","document_number":"32191315","case_number":"317549","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/8/4","year":"1434","subject":"نفقة -نفقة أوالد -املطالبة بالنفقة املاضية -املطالبة بالنفقة املستقبلية -املطالبة بتسليم شهادة املياد ودفتر العائلة -غياب املدعى عليه يعتبر نكو ال عن اجلواب -القول قول الغارم بيمينه- حلف الزوجة اليمني -تقدير النفقة عن طريق قسم اخلبراء -احلكم على األب بدفع نفقة أوالده املاضية واملستقبلية -احلكم على األب بتسليم األم األوراق الثبوتية ألوالدها الذين يف حضانتها -شمول احلكم بالنفقة وإخراج شهادة املياد وإسقاط املدعية من سجل","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1432/8/4 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪32191315 :‬‬\n                          ‫َر ْق ُم الدعوى‪317549 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34313140‬تاريخه‪1434/9/6 :‬هـ‬\n\n\n\n     ‫نفقــة ‪ -‬نفقــة أوالد‪ -‬املطالبــة بالنفقــة املاضيــة ‪ -‬املطالبــة بالنفقــة‬\n     ‫املســتقبلية‪ -‬املطالبــة بتســليم شــهادة امليــاد ودفتــر العائلــة‪ -‬غيــاب‬\n     ‫املدعــى عليــه يعتبــر نكــو ًال عــن اجلــواب‪ -‬القــول قــول الغــارم بيمينــه‪-‬‬\n     ‫حلف الزوجة اليمني‪ -‬تقدير النفقة عن طريق قسم اخلبراء‪ -‬احلكم‬\n     ‫علــى األب بدفــع نفقــة أوالده املاضيــة واملســتقبلية‪ -‬احلكــم علــى األب‬\n     ‫بتســليم األم األوراق الثبوتيــة ألوالدهــا الذيــن يف حضانتهــا‪ -‬شــمول‬\n     ‫احلكــم بالنفقــة وإخــراج شــهادة امليــاد وإســقاط املدعيــة مــن ســجل‬\n                                         ‫أســرة املدعــى عليــه بالتنفيــذ املعجــل‪.‬‬\n\n\n\n\n     ‫‪ -1‬املــادة ‪ 2/203‬مــن نظــام املرافقــات الشــرعية ولوائحــه التنفيذيــة‬\n               ‫املتضمــن أن غيــاب املدعــى عليــه يعتبــر نكــو ًال عــن اجلــواب‪.‬‬\n                                             ‫‪ -2‬قاعدة القول قول الغارم بيمينه‪.‬‬\n                                      ‫‪ -3‬املادة ‪ 199‬من نظام املرافعات الشرعية‪.‬‬\n     ‫‪ -4‬قــال يف دليــل الطالــب ص ‪ 292‬طبعــة طيبــة (وحيــث امتنــع فيهــا‬\n     ‫زوج أو قريــب وأنفــق أجنبــي بنيــة الرجــوع رجــع) وانظــر شــرح منتهــى‬\n     ‫اإلرادات ‪ 680/5‬طبعــة الرســالة وكشــاف القنــاع ‪ 161/13‬طبعــة وزارة‬\n                                                                           ‫العــدل‪.‬‬\n\n\n‫‪45‬‬\n\f‫ادعــى املدعــي وكالــة بــأن موكلتــه منــذ شــهر ‪1430/11‬ه ـ وهــي تنفــق‬\n‫علــى أوالدهــا مــن املدعــى عليــه وهــم بنتان وابن ذكــر أعمارهم كونهم‬\n‫يعيشــون معهــا وال يزالــون‪ ،‬لــم يدفــع املدعــى عليــه مــن النفقــة ســوى‬\n‫ألــف وتســعمائة ريــال فيمــا أنفقــت موكلتــه خمســة وعشــرين ألــف ريــال‬\n‫وتنازلــت إلــى خمســة عشــر ألــف ريــال إلــى شــهر ‪1431/11‬هــ‪ ،‬طلــب‬\n‫املدعــي وكالــة إلــزام املدعــى عليــه بتعويــض موكلتــه عمــا أنفقتــه‬\n‫ســابق ًا وإلزامــه باالســتمرار يف النفقــة بألــف ريــال شــهري ًا وإلزامــه‬\n‫بتســليم شــهادة امليــاد ودفتــر العائلــة إلكمــال املعامــات الرســمية‪،‬‬\n‫ال عــن اجلــواب‬  ‫لــم يحضــر املدعــى عليــه رغــم تبليغــه لــذا عـ ّـد نــاك ً‬\n‫بنــاء علــى املــادة ‪ 2/203‬مــن نظــام املرافعــات الشــرعية‪ ،‬ورد جــواب‬\n‫قســم اخلبــراء املتضمــن تقديــر نفقــة األوالد بعــد أن وردت إفــادة مرجــع‬\n‫املدعــى عليــه مبقــدار راتبــه‪ ،‬حيــث إن املدعيــة غارمــه والقــول قــول‬\n‫الغــارم بيمينــه لــذا جــرى حتليــف املدعيــة أصالــة بعــد وعظهــا بخطــر‬\n‫اليمــن الكاذبــة علــى أن املدعــى عليــه لــم ينفــق علــى أوالده ســوى ألــف‬\n‫وســبعمائة ريــال وأنهــا أنفقــت أكثــر مــن خمســة عشــر ألــف ريــال وال‬\n‫يزالــون يف حضانتها‪،‬حلفــت املدعيــة‪ ،‬صــدر احلكــم حضوري ـ ًا بإلــزام‬\n‫املدعــى عليــه بدفــع ثالثــة وثالثــن ألــف ريــال نفقــة ألوالده مــن املدعيــة‬\n‫عــن املــدة املاضيــة وإلزامــه باإلنفــاق عليهــم ألفــي ريــال شــهري ًا وإلزامــه‬\n‫بتســليم األوراق الثبوتيــة ألوالده للمدعيــة ومنهــا شــهادات امليــاد للبنتــن‬\n‫وكــرت العائلــة مــا دامــوا يف حضانــة والدتهــم‪ ،‬قــدم املدعــى عليــه‬\n‫الئحتــه االعتراضيــة املتضمنــة وجــود اســتقطاعات مــن راتبــه‪ ،‬جــرى‬\n\n                                                                                        ‫‪46‬‬\n\f     ‫مناقشــة هــذا األمــر بحضــور الطرفــن وجــرى بعــث املعاملــة لقســم‬\n     ‫اخلبــراء لتقديــر النفقــة علــى ضــوء ذلــك‪ ،‬ورد اجلــواب مــن قســم اخلبــراء‬\n     ‫بــأن مــا جــاء يف الئحــة املدعــى عليــه ال يؤثــر ذلــك علــى تقديــر النفقــة‬\n     ‫الســابقة وتبقــى النفقــة كمــا هــي بالتقديــر الســابق‪ ،‬جــرى تســليم‬\n     ‫املدعيــة صــورة مــن كــرت العائلــة وأقــرت املدعيــة باســتالم صــورة‬\n     ‫مــن شــهادة ميــاد إحــدى البنتــن‪ ،‬رجــع القاضــي عــن احلكــم بإلــزام‬\n     ‫املدعــى عليــه بتســليم شــهادة ميــاد البنــت املذكــورة وكــرت العائلــة‬\n     ‫وأمــا بقيــة احلكــم فبحالــة و شــمول احلكــم بالنفقــة وإخــراج شــهادة‬\n     ‫ميــاد البنــت الثانيــة وإســقاط اســم املدعيــة مــن ســجل أســرة املدعــى‬\n     ‫عليــه بالتنفيــذ املعجــل بالكفالــة احلضوريــة الغراميــة بنــاء علــى املــادة‬\n     ‫‪ ،199‬مــن نظــام املرافعــات الشــرعية‪ ،‬لوحــظ علــى احلكــم ثــم صــدق‬\n                                               ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬مســاعد رئيــس احملكمــة العامــة‬\n     ‫مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة باخلــرج برقــم ‪ 317549‬وتاريــخ ‪1431/11/26‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 3129679‬وتاريــخ ‪1431/11/26‬ه ـ ففــي‬\n     ‫يــوم االربعــاء املوافــق ‪143/2/8‬ه ـ حضــر ‪ ...‬ســجله املدنــي رقــم ‪...‬‬\n     ‫بالوكالــة رقــم ‪ 510506017367‬وتاريــخ ‪1431/11/19‬ه ـ صــادرة‬\n     ‫مــن كتابــة عــدل اخلــرج عــن ‪ ...‬لــه فيهــا املطالبــة بحضانــة أوالدهــا منــه‬\n     ‫والنفقــة واملدافعــة واملرافعــة واملخاصمــة وإقامــة الدعــاوى وحضــور‬\n     ‫اجللســات وســماع الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار واحضــار‬\n\n‫‪47‬‬\n\f‫البينــات والشــهود والصلــح وطلــب اليمــن وردهــا وقبــول احلكــم ونفيــه‬\n‫واالعتــراض عليــه وطلــب متييــزه واالســتالم والتســليم ولــم يحضــر‬\n‫املدعــى عليــه ‪ ...‬ولــم يقــدم عــذرا لعــدم حضــوره مــع تبلغــه شــخصيا‬\n‫كمــا يفيــده محضــر التبليــغ املرفــق وادعــى املدعــي قائــا موكلتــي‬\n‫منــذ شــهر ‪1430/11‬ه ـ وهــي تنفــق علــى أوالدهــا مــن املدعــى عليــه‬\n‫وهــم بنــت عمرهــا ســبع ســنوات وبنــت أخــرى عمرهــا أربــع ســنوات‬\n‫وولــد اســمه ‪...‬عمــره ســنة وعشــرة أشــهر كونهــم يعيشــون معهــا يف‬\n‫بيــت أهلهــا يف اخلــرج وال يزالــون وقــد دفــع مــن النفقــة ألــف وتســعمائة‬\n‫ريــال فقــط بينمــا أنفقــت خمســة وعشــرين ألــف ريــال وتنازلــت إلــى‬\n‫خمســة عشــر الــف ريــال إلــى شــهر ‪1431/11‬ه ـ أطلــب إلزامــه تعويضهــا‬\n‫عمــا أنفقتــه ســابقا وإلزامــه باالســتمرار يف النفقــة بألــف ريــال شــهريا‬\n‫وإلزامــه بتســليم شــهادة امليــاد ودفتــر العائلــة إلكمــال املعامــات‬\n‫الرســمية هــذه دعــواي وبطلــب البينــة مــن املدعــي أبــرز صــورة ناقصــة‬\n‫للصــك الصــادر منــا برقــم ‪ 66/2/43‬وتاريــخ ‪1431/7/30‬ه ـ واملتضمــن‬\n‫دعــوى املدعيــة طلــب فســخ النــكاح مــن املدعــى عليــه وإقــراره الضمنــي‬\n‫بنكاحهــا ثــم احلكــم بفســخ النــكاح بينهمــا مقابــل عــوض وبســؤال‬\n‫املدعــي وكالــة عــن عمــل املدعــى عليــه أجــاب يعمــل يف محميــة الوعــول‬\n‫بحوطــة بنــي متيــم التابعــة للهيئــة الســعودية حلمايــة احليــاة الفطريــة وإمنائهــا‬\n‫ولديــه محــل يف اخلــرج اســمه محــل ‪ ...‬لــذا جــرى ســؤاله عــن نوعيــة‬\n‫نشــاطه فطلــب مهلــة ولالطــاع علــى ســجل الصــك والكتابــة ملرجــع‬\n‫املدعــى عليــه ملعرفــة مقــدار راتبــه جــرى رفــع اجللســة ويف جلســة أخــرى‬\n‫حضــر املدعــي بالوكالــة ‪ ...‬ولــم يحضــر املدعــى عليــه وقــد وردنــا مــن‬\n‫الهيئــة الســعودية للحيــاة الفطريــة اخلطــاب رقــم ‪1431/480‬ه ـ وتاريــخ‬\n\n\n                                                                                            ‫‪48‬‬\n\f     ‫‪1432/3/9‬ه ـ املتضمــن أن راتــب املدعــى عليــه األســاس خمســة آالف‬\n     ‫وســتمائة وخمســة وثالثــن ريــاال وبــدل غــاء املعيشــة ثمامنائــة وخمســة‬\n     ‫وأربعــن ريــاال وخمســة وعشــرين هللــة وعليــه حســميات لبنــك التســليف‬\n     ‫أربعمائــة ريــال وصــايف راتبــه خمســة آالف وخمســمائة وثالثــة وســبعني‬\n     ‫ريــاال وعشــر هلــات كمــا جــرى االطــاع علــى ســجل الصــك املرفــق‬\n     ‫صورتــه وبســؤال املدعــى وكالــة عــن نشــاط محــل املدعــى عليــه‬\n     ‫أجــاب نشــاطه بيــع طيــور وقــد أخبرنــي أنــه فتحــه للتســلية وليــس لــه‬\n     ‫دخــل يذكــر ولتقديــر النفقــة مــن أهــل اخلبــرة جــرى رفــع اجللســة ويف‬\n     ‫جلســة أخــرى حضــر املدعــى بالوكالــة وقــد وردنــا مــن قســم اخلبــراء‬\n     ‫باحملكمــة اخلطــاب رقــم ‪ 32/480319‬وتاريــخ ‪1432/5/6‬ه ـ مرفقاتــه‬\n     ‫احملضــر املعــد مــن أعضــاء القســم واملتضمــن‪ :‬وبعــد االطــاع علــى‬\n     ‫الدعــوى يــرى األعضــاء أن تكــون نفقــة األبنــاء وعددهــم ثالثــة مــن‬\n     ‫ســبعمائة ريــال شــهريا( ‪ 2100 = 700 × 3‬ريــال شــهريا ) وبتأمــل مــا‬\n     ‫تقــدم مــن الدعــوى والبينــة التــي قدمهــا املدعــي فقــد جــرى االطــاع‬\n     ‫علــى ورقــة التبليــغ املعــدة مــن محضــر احملكمــة املتضمنــة إبــاغ املدعــى‬\n     ‫عليــه شــخصيا حلضــور اجللســة يف ‪1432/2/8‬ه ـ وألن غيــاب املدعــى‬\n     ‫عليــه يعتبــر نكــوال عــن جــواب الدعــوى مثــل مــا جــاء يف املــادة ‪2/203‬‬\n     ‫مــن نظــام املرافعــات الشــرعية ولوائحــه وألن املدعيــة غارمــه والقــول‬\n     ‫قولهــا بيمينهــا لــذا جــرى افهــام وكيــل املدعيــة أن اليمــن متوجهــة‬\n     ‫علــى موكلتــه فأجــاب موكلتــي مســتعدة بذلــك لــذا جــرى رفــع اجللســة‬\n     ‫حلضورهــا ويف يــوم األحــد املوافــق ‪1432/7/17‬ه ـ فتحــت اجللســة‬\n     ‫وحضــرت املدعيــة واملعــرف بهــا مــن قبــل عمهــا ‪ ...‬بالســجل املدنــي رقــم‬\n     ‫‪...‬وبســؤال املدعيــة عــن أي شــهادات امليــاد التــي تريــد أجابــت شــهادة‬\n\n\n‫‪49‬‬\n\f‫ميــاد ‪ ...‬و‪ ......‬وبعــرض اليمــن علــى املدعيــة أجابــت أنــا مســتعدة بذلــك‬\n‫لــذا جــرى وعظهــا عــن خطــر اليمــن الكاذبــة ثــم جــرى إحالفهــا اليمــن‬\n                                                                           ‫التاليــة ‪:‬‬\n‫(واهلل العظيــم أننــي أنفقــت علــى أوالدي مــن املدعــى عليــه ‪ ...‬أكثــر مــن‬\n‫خمســة عشــر ألــف ريــال إلــى تاريــخ ‪1431/11‬ه ـ وأنــه لــم ينفــق عليهــم‬\n‫مــن شــهر ‪1430/11‬ه ـ إلــى اآلن إال ألــف وســبعمائة ريــال وال يزالــون يف‬\n‫حضانتــي وأنــا التــي أنفــق عليهــم) هكــذا أدت اليمــن وألن املدعيــة‬\n‫حلفــت اليمــن التــي طلبــت منهــا بعــد توجههــا إليهــا وملــا ســبق مــن تقديــر‬\n‫أهــل اخلبــرة لنفقــة أوالد املدعيــة واملدعــى عليــه وألن املدعيــة تطالــب‬\n‫بنفقــة ألفــي ريــال شــهريا فقــد حكمــت حضوريــا بإلــزام املدعــى عليــه‬\n‫بدفــع ثالثــة وثالثــن ألــف ريــال نفقــة ألوالده مــن املدعيــة ‪...‬و‪...‬و‪ ...‬عــن‬\n‫املــدة املاضيــة وإلزامــه باإلنفــاق عليهــم ألفــي ريــال شــهريا وإلزامــه‬\n‫بتســليم األوراق الثبوتيــة ألوالده للمدعيــة ومنهــا شــهادات امليــاد ل‪...‬‬\n‫و‪ ...‬وكــرت العائلــة مــا دامــوا يف حضانــة والدتهــم وبعــرض احلكــم علــى‬\n‫املدعيــة قنعــت بــه لــذا جــرى األمــر بإخــراج الصــك ومــن ثــم بعــث نســخة‬\n‫منــه للمدعــى عليــه لتقــدمي مــا لديــه مــن اعتــراض يف مــدة ثالثــن يومــا‬\n‫وإال ســقط حقــه يف االعتــراض واكتســب احلكــم الصفــة القطعيــة‬\n    ‫وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه حــرر يف ‪1432/7/17‬ه ـ ‪.‬‬\n‫ويف يــوم األربعــاء املوافــق ‪ 1432/11/21‬ه ـ فتحــت اجللســة بعــد أن مت‬\n‫االطــاع علــى الئحــة االعتــراض املقدمــة مــن املدعــى عليــه واملقيــدة‬\n‫باحملكمــة برقــم ‪ 32/1296263‬وتاريــخ‪ 1432/10/19‬ه ـ والتــي‬\n‫ذكــر فيهــا أن بنــك التســليف يحســم عليــه مبلــغ وقــدره عشــرون ألــف‬\n‫ريــال بواقــع أقســاط شــهرية كل قســط أربعمائــة ريــال وأن بنــك ‪.....‬‬\n\n\n                                                                                         ‫‪50‬‬\n\f     ‫يحســم مبلــغ وقــدره ســتة وثمانــون ألــف ريــال بواقــع ألــف وســبعمائة‬\n     ‫ريــال شــهريا وأن يف ذمتــه عشــرة آالف ريــال ملكتــب ‪ ...‬باخلــرج بواقــع‬\n     ‫قســط شــهري قــدره ســبعمائة ريــال وأرفــق مــع الالئحــة صــورة عقــد‬\n     ‫أجــار لــه مببلــغ عشــرة آالف ريــال يف الســنة تدفــع علــى قســطني كل‬\n     ‫ســتة أشــهر قســط وجــرى ســؤال املدعــى عليــه عــن ذلــك ومــا بقــي يف‬\n     ‫ذمتــه مــن هــذه األقســاط فأجــاب نعــم كل ذلــك صحيــح بــل قــد أخــذت‬\n     ‫قــرض إضــايف مــن بنــك ‪ .....‬وارتفــع القســط إلــى ألــف وتســعمائة وســبعة‬\n     ‫وأربعــن ريــاال وثالثــة وثالثــن هللــة وصــار املبلــغ الــذي يف ذمتــي مائــة‬\n     ‫وســتة عشــر ألــف وثمامنائــة وتســعة وثالثــن ريــاال وثمانــن هللــة وأمــا مــا‬\n     ‫بقــي مــن األقســاط فــا أدري بالضبــط هكــذا أجــاب وبعــرض ذلــك‬\n     ‫علــى املدعيــة أجابــت هــذه أشــياء ال نعلمهــا هكــذا أجابــت لــذا جــرى‬\n     ‫ســؤال املدعــى عليــه عــن رقــم حســابه يف بنــك ‪ .....‬فأجــاب حســابي يف‬\n     ‫‪ .....‬رقــم ‪ ...‬لــذا جــرى افهامــه باإلفــادة عمــا بقــي يف ذمتــه مــن األقســاط‬\n     ‫ورفعــت اجللســة مــع األمــر بالكتابــة لبنــك ‪ .....‬وبنــك التســليف لإلفــادة‬\n     ‫عمــا ذكــر املدعــي عليــه ويف جلســة اخــرى حضــرت املدعيــة وحضــر‬\n     ‫املعــرف بهــا احلاضــر ‪...‬بالســجل املدنــي رقــم ‪...‬وحضــر املدعــى عليــه وقــد‬\n     ‫جــرى ســؤال املدعــى عليــه عمــا بقــي يف ذمتــه لبنــك ‪ .....‬فأجــاب بقــي‬\n     ‫مائــه وعشــرين ألــف ريــال تقريبــا كمــا جــرى االطــاع علــى اخلطــاب‬\n     ‫الــوارد لنــا مــن البنــك الســعودي للتســليف واالدخــار فــرع اخلــرج رقــم‬\n     ‫‪ 869‬وتاريــخ ‪ 1432/12/26‬ه ـ املبنــي علــى خطابنــا رقــم ‪32/1554545‬‬\n     ‫وتاريــخ ‪ 1432/12/3‬ه ـ واملتضمــن أن املدعــى عليــه مقتــرض قــرض‬\n     ‫أســرة مببلــغ عشــرين ألــف ريــال تســدد علــى أقســاط شــهرية ومقــدار‬\n     ‫القســط أربعمائــة ريــال ســدد حتــى تاريخــه يف ‪ 1432/12/26‬ه ـ تســعة‬\n\n\n‫‪51‬‬\n\f‫عشــر ألفــا ومئتــي ريــال وبقــي ثمامنائــة ريــال وبطلــب البينــة مــن املدعــى‬\n‫عليــه علــى األقســاط التــي عليــه ملكتــب ‪ ...‬أجــاب أطلــب مهلــة ونظــرا‬\n‫لعــدم ورود إجابــة بنــك ‪ .....‬ولســماع بينــة املدعــى عليــه جــرى رفــع اجللســة‬\n‫ويف جلســة اخــرى حضــرت املدعيــة وابــرزت بطاقتهــا الشــخصية ســجلها‬\n‫املدنــي رقم‪...‬كمــا حضــر املدعــى عليــه وقــد وردنــا مــن مؤسســة النقــد‬\n‫العربــي الســعودي اخلطــاب رقــم‪754‬ن ظ ‪/‬أ ق وتاريخ‪1433/4/8‬ه ـ‬\n‫واملتضمــن افــادة مجموعــة ‪ .....‬بــان مبلــغ القــرض علــى املدعــى عليــه‬\n‫مائــة وســتة عشــر الفــا وثمامنائــة وتســعة وثالثــون ريــاال وثمانــون هللــه‬\n‫ومقــدار القســط الشــهري الــف وتســعمائة وســبعة واربعــون ريــاال‬\n‫وثالثــة وثالثــون هللــه واملبلــغ املتبقــي مائــة وتســعة االف وخمســة عشــر‬\n‫ريــاال وســبعة وثالثــون هللــه واالقســاط املتبقيــة ســتة وخمســون قســطا‬\n‫وبطلــب البينــة مــن املدعــى عليــه علــى االقســاط التــي عليــه ملكتــب‬\n‫التقســيط املريــح ابــرز ثالثــة ســندات قبــض علــى اوراق عاديــة ملؤسســة‬\n‫التقســيط املريــح للتجــارة والتقســيط مســلمه مــن املدعــى عليــه كل‬\n‫ســند بســبعمائة ريــال وقــال املدعــى عليــه ان هــذه اقســاط ســددتها‬\n‫وهــي جــزء مــن املبلــغ الــذي علــي وقــدره عشــرة االف ريــال وهــو ثمــن‬\n‫بطاقــات ‪ .....‬اشــتريتها مــن ‪...‬ثــم بعتهــا بتســعة االف أو تســعة االف‬\n‫وخمســمائة ألجــل اصــاح ســيارتي وكفيلــي ‪...‬وبســؤاله عــن تاريــخ‬\n‫العقــد ومــا بقــي مــن اقســاط اجــاب تاريــخ العقــد ال ادري والباقــي مــن‬\n‫االقســاط ال ادري لكنــي ســددت اكثــر ممــا ذكــر يف الســندات علمــا‬\n‫انــي رســمت يف عملــي يف محميــة الوعــول علــى املرتبــة اخلامســة ونقــص‬\n‫راتبــي الــى خمســة االف ومئتــن واربعــن ريــاال وبطلــب زيــادة بينــة علــى‬\n‫ذلــك طلــب مهلــه لــذا جــرى افهامــه انهــا اخــر مهلــه كمــا ابــرز ســندي‬\n\n\n                                                                                       ‫‪52‬‬\n\f     ‫قبــض علــى ورق إلدارة التربيــة والتعليــم مبنطقــة الريــاض مــدارس ‪...‬‬\n     ‫االهليــة احدهــا بتاريخ‪1432/11/20‬ه ـ ويتضمــن اســم الطالــب وهــو‬\n     ‫املدعــى عليــه ورقمــه وصفــه االولــى متوســط وصــايف املســتحق خمســة‬\n     ‫االف واملدفــوع خمســمائة ريــال ومختومــة بختــم الصنــدوق للمــدارس‬\n     ‫والثانيــة بتاريخ‪1433/2/10‬ه ـ بنفــس املعلومــات اال ان املدفــوع الفــي‬\n     ‫ريــال مــن خمســة االف ريــال والباقــي الفــن وخمســمائة ريــال وقــال‬\n     ‫املدعــى عليــه اننــي ادرس يف هــذه املــدارس ألجــل التعلــم واســتفيد يف‬\n     ‫الترقيــة يف وظيفتــي لــذا جــرى االمــر بالكتابــة ملرجــع املدعــى عليــه‬\n     ‫لإلفــادة عــن راتبــه اخيــرا كمــا جــرى ســؤال املدعــى عليــه عــن كــرت‬\n     ‫العائلــة وشــهادتي امليــاد لــ‪ ...‬و‪ ...‬فأجــاب كــرت العائلــة عندي ومســتعد‬\n     ‫بإعطائه للمدعية واما شــهادتي امليالد لـ‪ ...‬و‪ ......‬فليس عندي اال صورة‬\n     ‫لشــهادة ميــاد ‪...‬وامــا االصــل فعنــد املدعيــة اخذتهــا مــع اوراق اخــرى‬\n     ‫هكــذا اجــاب‪ .‬وبعــرض ذلــك علــى املدعيــة أجابــت ال صحــة ملــا ذكــر‬\n     ‫والــذي عنــدي اوراق ‪ ...‬فقــط لــذا جــرى ســؤال املدعــى عليــه البينــة علــى‬\n     ‫اخــذ املدعيــة لــأوراق فأجــاب صــك اخللــع وفيــه انهــا اخــذت منــي اوراق‬\n     ‫ومنهــا شــهادات امليــاد للبنــات ‪ ......‬و‪ ...‬وبســؤال املدعــى عليــه زيــادة‬\n     ‫بينــة اجــاب ليــس لــدي غيرهــا بينــة ولالطــاع علــى صــك اخللــع جــرى‬\n     ‫رفــع اجللســة ويف جلســة أخــرى حضــرت املدعيــة واملدعــى عليــه وقــد‬\n     ‫مت تأجيلهــا مــن قبــل املكتــب مــن يــوم الســبت املوافــق ‪1433/6/14‬ه ـ‬\n     ‫نظــرا لكونــي يف إجــازة اضطراريــة ويف هــذا اليــوم أحضــر املدعــى‬\n     ‫عليــه أصــل ســجل األســرة اخلــاص لــه وجــرى تصويــره وإعطــاء املدعيــة‬\n     ‫نســخة مصدقــة منــه كمــا جــرى االطــاع علــى صــورة الصــك رقــم‬\n     ‫‪ 66/2/34‬وتاريــخ ‪ 1431/7/30‬ه ـ الــذي أبــرزه املدعــى عليــه وقالــت‬\n\n\n‫‪53‬‬\n\f‫املدعيــة أصلــه عنــدي وهــو صــادر منــي وجــرى اإلطــاع عليــه ولــم جنــد‬\n‫فيــه مــا يــدل علــى أن املدعيــة أخــذت شــهادات ميــاد ‪...‬وقــال املدعــى‬\n‫عليــه أنــي ســلمت املدعيــة صــورة مــن شــهادة ميــاد ‪...‬وحصــل بهــا‬\n‫املقصــود وأجابتــه املدعيــة نعــم حصــل ذلــك لكــن كــرت العائلــة اليــزال‬\n‫اســمي مســجل معــه وقــد ذهبــت لألحــوال لتنزيلــه ودفعــت الرســم اخلاص‬\n‫لذلــك ولكــن ســجل األســرة اليــزال معــه هكــذا أجابــت ‪ .‬وقــد جــرى‬\n‫اإلطــاع علــى خطــاب مرجــع املدعــى عليــه رقــم ‪2995/2971/4/1‬‬\n‫وتاريــخ ‪ 1433/7/6‬ه ـ املبنــي علــى خطابنــا وفيــه ( أن راتبــه األســاس‬\n‫احلالــي ‪ 6720‬ريــال والصــايف بعــد حســم التأمينــات ‪ 6151.20‬ريــال وال‬\n‫توجــد عليــه حســميات لبنــك التســليف ) وبســؤال املدعــى عليــه البينــة‬\n‫علــى ماذكــره مــن قســط ملكتــب ‪ ...‬أجــاب هــذا انتهــى وأبــرز املدعــى‬\n‫عليــه أصــل عقــد بيــع علــى مكتــب ‪ ...‬لالســتثمار العقــاري والتقســيط‬\n‫يتضمــن شــراء املدعــى عليــه لفيــا دوريــن بحــي ‪ .....‬مببلــغ خمســمائة‬\n‫وســبعني ألــف ريــال ومذكــورة حدودهــا وأطوالهــا ومســاحتها ‪ .‬وقــال‬\n‫املدعــى عليــه أننــي اشــتريت هــذه الفيــا بعــد أن خــرج اســمي يف البنــك‬\n‫العقــاري بقــرض خمســمائة ألــف ريــال ‪ .‬وســبعني ألــف ســأدفعها مــن‬\n‫عنــدي وأبــرز عــدد مــن األوراق تفيــد مراجعتــه للبنــك ألجــل ذلــك جــرى‬\n‫رفــع اجللســة مــع األمــر بالكتابــة لقســم اخلبــراء لســؤالهم عــن تأثيــر ذلــك‬\n‫يف تقديــر النفقــة والكتابــة لألحــوال املدنيــة لتنزيــل اســم املدعيــة مــن‬\n‫ســجل األســرة ويف يــوم الثالثــاء املوافــق ‪1433/7/29‬ه ـ فتحــت اجللســة‬\n‫وحضــر املدعــى عليــه وقــد وردنــا مــن قســم اخلبــراء احملضــر برقــم‬\n‫‪ 33/1341109‬وتاريــخ ‪1433/7/22‬ه ـ املبنــي على خطابنا وفيه (وعليه‬\n‫وبعــد االطــاع علــى كامــل مرفقــات املعاملــة يــرى األعضــاء أن مــا جــد‬\n\n\n                                                                                       ‫‪54‬‬\n\f     ‫يف أحــوال املدعــى عليــه ال يؤثــر ذلــك علــى تقديــر النفقــة الســابق وتبقــى‬\n     ‫النفقــة كمــا هــي بالتقديــر الســابق ) أـ ه ـ أعضاء قســم اخلبــراء ‪...‬و‪...‬و‪...‬‬\n     ‫ورئيــس قســم اخلبــراء ‪...‬وبســؤال املدعــى عليــه عــن تنزيــل اســم املدعيــة‬\n     ‫مــن ســجل األســرة أجــاب لــم أراجعهــم بعــد نظــر ًا النشــغالي باالختبــارات‬\n     ‫ثــم الــدوام بعــد ذلــك وال أســتطيع اخلــروج مــن العمل وأن شــاء اهلل ســأقوم‬\n     ‫بذلــك خــال هــذا الشــهر هكــذا أجــاب لــذا جــرى تأمل ما ســبق ضبطه‬\n     ‫بعــد تقــدمي املدعــى عليــه الالئحــة االعتراضيــة وألنــه لــم يجــد مــا يؤثــر‬\n     ‫علــى تقديــر النفقــة كمــا قــرره قســم اخلبــراء وألن املدعيــة أكتفــت يف‬\n     ‫مطالبتهــا بشــهادة امليــاد ‪ ...‬وكذلــك بكــرت العائلــة بالصــورة التــي‬\n     ‫أخذتهــا ولــم يبقــى إال شــهادة ميــاد ‪ ...‬وتنزيــل اســم املدعيــة مــن ســجل‬\n     ‫األســرة اخلــاص باملدعــى عليــه فلمــا تقــدم فقــد رجعــت عــن احلكــم‬\n     ‫بإلــزام املدعــى عليــه بتســليم شــهادة ميــاد ‪...‬وكــرت العائلــة وامــا بقيــة‬\n     ‫احلكــم فبحــا لــه مــع شــمول احلكــم بالنفقــة واخــراج شــهادة امليــاد ل‪...‬‬\n     ‫واســقاط اســم املدعيــة مــن ســجل اســرة املدعــى عليــه التنفيــذ املعجــل‬\n     ‫بالكفالــة احلضوريــة الغراميــة بنــاء علــى املادة‪199‬مــن نظــام املرافعــات‬\n     ‫ولوائحــه الشــرعية وقــد امــرت بإحلــاق خالصــة مــا جــد بالصــك وســجله‬\n     ‫ومــن ثــم بعثــة حملكمــة االســتئناف إلكمــال مــا يلــزم وصلــى اهلل وســلم‬\n     ‫علــى نبينــا محمــد وآلــه وصحبــه أجمعــن وبطلــب التوقيــع مــن املدعــى‬\n                                                                 ‫عليــه خــرج ولــم يعــد‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي انــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة الــواردة الينــا برقــم ‪ 34190533‬وتاريــخ‬\n     ‫‪1434/2/28‬ه ـ مــن محكمــة االســتئناف بالريــاض واملرفــق بهــا القــرار‬\n     ‫رقــم‪ 3431170‬وتاريــخ ‪1434/2/5‬ه ـ والــذي جــاء فيــه بعــد املقدمــة‬\n\n\n‫‪55‬‬\n\f‫(‪ ..‬وباالطــاع علــى خطــاب رئيــس احملكمــة العامــة باخلــرج املكلــف‬\n‫املشــار اليــه اعــاه املتضمــن ان ناظــر القضيــة انتقــل الــى احملكمــة‬\n‫العامــة بالريــاض لــذا قــررت الدائــرة بعــث املعاملــة الــى فضيلــة ناظرهــا‬\n‫يف مقــر عملــه احلالــي احملكمــة العامــة بالريــاض إلكمــال الــازم حيــال‬\n‫مــا جــاء يف قــرار الدائــرة رقــم‪33422611‬يف ‪1433/10/10‬ه ـ وبعــد‬\n‫اإلحلــاق علــى الصــك بعــث املعاملــة الــى محكمــة اخلــرج إلحلــاق مــا جــد‬\n‫علــى الصــك علــى الضبــط وصورتــه وســجل الصــك ثــم إعــادة املعاملــة‬\n‫الــى محكمــة االســتئناف إلكمــال الزمهــا ‪)..‬أ ـ ه ـ فجــرى االطــاع‬\n‫علــى القــرار رقــم‪ 33422611‬يف‪1433/10/10‬ه ـ والــذي جــاء فيــه‬\n‫بعــد املقدمــة (وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة لوحــظ االتــي اوال ‪ /‬ان مــا حكــم بــه فضيلتــه مــن‬\n‫النفقــة املســتقبلية بألفــي ريــال شــهريا ألوالده كثيــر وال يتناســب مــع‬\n‫دخــل املدعــى عليــه فعلــى فضيلتــه اعــادة النظــر يف ذلــك وإكمــال مــا‬\n‫يلــزم نحــوه ثانيــا ‪ /‬ان فضيلتــه لــم يذكــر مســتنده يف احلكــم بالنفقــة‬\n‫املاضيــة ‪ )..‬أ ـ ه ـ لــذا جــرى قــراءة الصــك واالطــاع علــى صــورة ضبطــه‬\n‫وارواق املعاملــة وبتأمــل مــا ســبق مــن احلكــم واســبابه فانــي اجيــب علــى‬\n‫مالحظــات اصحــاب الفضيلــة مبــا يلــي ‪:‬اوال ‪ :‬امــا املالحظــة االولــى‬\n‫فالنفقــة الواجبــة علــى االب ألوالده مقــدرة باملعــروف ومت ذلــك عن طريق‬\n‫اهــل اخلبــرة مرتــن ولــم يالحــظ عليهــا شــيء مــع حاجــة االطفــال وقــدرة‬\n‫االب ثانيــا‪ :‬امــا املالحظــة الثانيــة فمســتندي يف احلكــم بالنفقــة املاضيــة‬\n‫هــو مــا دلــت عليــه النصــوص مــن وجــوب نفقــة الوالــد ألوالده ومــا ذكــره‬\n‫الفقهــاء مــن انــه اذا لــم ينفــق وانفــق غيــره بنيــة الرجــوع فــان لــه الرجــوع‬\n‫ينظــر شــرح املنتهى‪680/5‬طبعــة الرســالة وكشــاف القنــاع‪161/13‬‬\n\n\n                                                                                          ‫‪56‬‬\n\f     ‫طبعــة وزارة العدل‪292/‬وقــال يف دليــل الطالــب ص ‪ 292‬طبعــة طيبــه‬\n     ‫(وحيــث امتنــع منهــا زوج أو قريــب وانفــق اجنبــي بنيــة الرجــوع رجــع‪)..‬‬\n     ‫أ‪.‬ه ـ وغيرهــا مــن املراجــع واملدعيــة لــم تطالــب بكامــل النفقــة املاضيــة‬\n     ‫واملدعــي لــم يدعــي انــه انفــق فضــا عــن ان يثبــت ذلــك وعليــه فانــي علــى‬\n     ‫مــا حكمــت بــه واجريتــه مــع االمــر ببعــث املعاملة حملكمــة اخلرج إلحلاق‬\n     ‫مــا جــد يف الصــك علــى الضبــط وصورتــه وســجل الصــك ومــن ثــم بعــث‬\n     ‫املعاملــة حملكمــة االســتئناف إلكمــال الــازم حســب التوجيــه وبــاهلل‬\n     ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/7/17‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n     ‫لتمييــز قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n     ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫باخلــرج برقــم ‪ 34/1986697‬وتاريــخ ‪1434/8/16‬ه ـ املرفــق بهــا الصــك‬\n     ‫الصــادر مــن فضيلتــه مســاعد رئيــس احملكمة ســابق ًا الشــيخ‪ ...‬املســجل‬\n     ‫برقــم ‪ 32191315‬وتاريــخ ‪1432/8/4‬ه ـ اخلــاص بدعــوى ‪ ...‬بالوكالــة‬\n     ‫عــن ‪ ...‬ضــد ‪ ...‬يف قضيــة نفقــة ‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه‬\n     ‫مبــا هــو مــدون ومفصــل فيــه ‪ .‬وحيــث ســبقت دراســة الصــك وصــورة‬\n     ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا‬\n     ‫أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بتاريــخ ‪1434/7/17‬ه ـ بنــاء‬\n     ‫علــى قرارنــا رقــم ‪ 3431170‬وتاريــخ ‪1434/2/5‬ه ـ لــم يظهــر مــا يوجــب‬\n     ‫االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                               ‫وســلم ‪.‬‬\n\n\n\n\n‫‪57‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":45,"source_page_end":57,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9f0b94384c19f4951e6bde56452ad96011428a66fa668e29a549723206e1a709","normalized_text_hash":"96410895d928c72c45bd7acba2a38a7a2e2e5de25bd409a798298303a39cc214","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p45-32191315"},{"id":"d6f89835-d98b-52d6-a008-de997b714e7e","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة -نفقة حمل -نفقة طفل -املطالبة بالنفقة املاضية واملستقبلية -دفع الزوج بعدم استحقاق الزوجة للنفقة لنشوزها -حتديد النفقة عن طريق قسم اخلبراء -النفقة مقابل التمكن من االستمتاع -احلكم بنفقة الولد دون أمه .","document_number":"33182259","case_number":"3223182","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/11","year":"1434","subject":"نفقة -نفقة زوجة -نفقة حمل -نفقة طفل -املطالبة بالنفقة املاضية واملستقبلية -دفع الزوج بعدم استحقاق الزوجة للنفقة لنشوزها -حتديد النفقة عن طريق قسم اخلبراء -النفقة مقابل التمكن من االستمتاع -احلكم بنفقة الولد دون أمه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/4/11 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33182259 :‬‬\n                    ‫َر ْق ُم الدعوى‪3223182 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 3444281‬تاريخه‪1434/2/23 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة زوجــة ‪ -‬نفقــة حمــل ‪ -‬نفقــة طفــل ‪ -‬املطالبــة بالنفقــة‬\n‫املاضيــة واملســتقبلية ‪ -‬دفــع الــزوج بعــدم اســتحقاق الزوجــة للنفقــة‬\n‫لنشــوزها ‪ -‬حتديــد النفقــة عــن طريــق قســم اخلبــراء ‪ -‬النفقــة مقابــل‬\n             ‫التمكــن مــن االســتمتاع ‪ -‬احلكــم بنفقــة الولــد دون أمــه ‪.‬‬\n\n\n\n\n ‫‪ -1‬ما قرره أهل العلم ‪ :‬من أن النفقة مقابل التمكني من االستمتاع‪.‬‬\n              ‫‪ -2‬ما قرره أهل العلم ‪ :‬من لزوم نفقة األب على ولده ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة علــى املدعــى عليــه بأنــه حصــل بينهمــا خــاف وقــام‬\n‫بطردهــا مــن املنــزل وهــى حامــل‪ ،‬طلبــت املدعيــة نفقتهــا عــن املــدة‬\n‫املاضيــة ونفقــة احلمــل والــوالدة ونفقــة مســتقبلية لهــا ولولدهــا‪ ،‬أقــر‬\n‫املدعــى عليــه بالدعــوى ودفــع بــأن املدعيــة خرجــت بغيــر رضــاه وأنــه‬\n‫طلبهــا مــرار ًا للرجــوع إلــى بيــت الزوجيــة فرفضــت‪ ،‬ذكــر املدعــى عليــه‬\n‫أنــه دفــع نفقــة الــوالدة وكان يرســل بعــض األغراض لولــده بعد الوالدة‪،‬‬\n‫جــرى تقديــر نفقــة املدعيــة وولدهــا عــن املــدة املاضيــة وحتديــد نفقــة‬\n‫مســتقبلية مــن قبــل قســم اخلبــراء باحملكمــة‪ ،‬جــرى ســؤال املدعيــة عما‬\n‫ذكــره املدعــى عليــه مــن أنــه طلبهــا لبيــت الطاعــة فرفضــت فصادقــت‬\n                                                                                  ‫‪58‬‬\n\f     ‫املدعيــة علــى ذلــك وذكــرت بــأن ســبب رفضهــا الرجــوع ألن املدعــى‬\n     ‫عليــه طردهــا‪ ،‬ملــا قــرره أهــل العلــم مــن أن النفقــة مقابــل التمكــن مــن‬\n     ‫االســتمتاع ولــزوم نفقــة األب علــى ولــده لــذا صــدر احلكم بإلــزام املدعى‬\n     ‫عليــه بدفــع نفقــة ابنــه املاضيــة واملســتقبلية‪ ،‬صــرف النظــر عــن مطالبــة‬\n     ‫املدعيــة بنفقتهــا‪ ،‬اعتــرض الطرفــان علــى احلكــم‪ ،‬صــدق احلكــم مــن‬\n                                                          ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض برقــم‪ 3223182‬وتاريــخ ‪1432/01/27‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم‪ 3270292‬وتاريــخ ‪1432/1/27‬ه ـ ففــي يــوم الســبت‬\n     ‫املوافــق ‪1432/04/28‬ه ـ افتتحــت اجللســة الســاعة ‪ 8 : 00‬وفيهــا‬\n     ‫حضــرت ‪ ...‬بالســجل املدنــي رقــم ‪ ...‬واملعــرف بهــا مــن قبــل والدهــا ‪...‬‬\n     ‫بالســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى عليــه ‪ ...‬وال مــن ينــوب عنــه‬\n     ‫وباالطــاع علــى أوراق املعاملــة وجدنــا خطــاب محضــري اخلصــوم بهــذه‬\n     ‫احملكمة برقم ‪ 32/237028‬يف ‪1432/3/16‬هـ واملتضمن (مت التوجه‬\n     ‫للموقــع املذكــور وأفــادوا أنــه ال يوجــد لديهــم موظــف بهــذا االســم‪... ،‬‬\n     ‫التوقيــع) ا‪.‬ه ـ ويف جلســة أخــرى حضــرت املدعيــة وبرفقهــا معرفهــا يف‬\n     ‫اجللســة الســابقة ‪ ،‬وحضــر حلضورهمــا ‪ ...‬بالســجل املدنــي رقــم ‪، ...‬‬\n     ‫فا ّدعــت املــرأة قائلــة ‪ :‬إن املدعــى عليــه هــو زوجــي بالعقــد الصحيــح منــذ‬\n     ‫عــام ‪1428‬ه ـ وأجنبــت لــه علــى فــراش الزوجيــة ولــد ًا اســمه ‪ ...‬وعمــره‬\n     ‫ســنتان وثمانيــة أشــهر ‪ ،‬ويف ‪1429/7/16‬ه ـ حصــل خــاف بيننــا وقــام‬\n‫‪59‬‬\n\f‫بطــردي مــن املنــزل وأنــا حامــل ‪ ،‬ومنــذ ذلــك التاريــخ وحتــى اآلن وأنــا‬\n‫عنــد أهلــي ‪ ،‬ولــم ينفــق علــي خاللهــا وال علــى احلمــل وال علــى الولــد ‪،‬‬\n‫أطلــب إلزامــه بالنفقــة املاضيــة وتقديــر نفقتــي املســتقبلية هــذه دعــواي‬\n‫ا ‪ :‬مــا‬\n       ‫أطالبــه بذلــك وأســأله اجلــواب ‪ ،‬وبســؤال املدعــى عليــه أجــاب قائـ ً‬\n‫ذكرتــه املدعيــة مــن الــزواج واإلجنــاب فهــذا صحيــح‪ ،‬ومــا ذكرتــه مــن‬\n‫أننــي قمــت بطردهــا فهــذا غيــر صحيــح ‪ ،‬والصحيــح أنــه وقــع خــاف‬\n‫بينــي وبينهــا وقلــت لهــا وأن يف حالــة غضــب ‪ :‬ال أجــي إلــى البيــت وأنــت‬\n‫موجــودة ‪ ،‬ثــم اتصلــت بأهلهــا وشــرحت لهــم ما حصــل وطلبت منهم عدم‬\n‫احلضــور وأنهــا مشــكلة ممكــن تداركهــا ‪ ،‬ثــم ذهبــت للعمــل وعنــد‬\n‫رجوعــي تفاجــأت بأنهــا غيــر موجــودة وأن أهلهــا قــد أتــوا ألخذهــا‪ ،‬وقــد‬\n‫ذهبــت لبيــت أهلهــا أكثــر مــن عشــرين مــرة ألجــل إرجاعهــا إلــى بيتــي‬\n‫ولكــن دون جــدوى‪ ،‬و أنــا غيــر مســتعد بدفــع نفقتهــا املاضيــة ألنهــا‬\n‫خرجــت مــن بيتــي بإرادتهــا ولــم ترجــع لبيــت الزوجيــة هــذا جوابــي ‪،‬‬\n‫فســألت املدعــى عليــه هــل أنفقــت علــى املدعيــة أو علــى الولــد أو احلمــل ‪،‬‬\n‫فأجــاب ‪ :‬لــم أنفــق عليهــا وال علــى حملهــا ‪ ،‬ولكنــي أنفقــت علــى الوالدة‬\n‫‪ ،‬وكنــت أرســل احتياجــات ولــدي مــن حفائــظ ومالبــس ونحوهــا‬\n‫بشــكل مســتمر هكــذا ذكــر ‪ ،‬فســألت املــرأة عمــا ذكــره املدعــي‬\n‫مــن إحضــار مســتلزمات الولــد فأجابــت ‪ :‬أحضــر كســوة عيديــن‪،‬‬\n‫أمــا املســتلزمات األخــرى كاحلفائــظ واحلليــب فــكان يحضرهــا علــى‬\n‫فتــرات متفاوتــة فمــرة كل شــهرين ومــرة كل ثالثــة أشــهر عندمــا‬\n‫كان الطفــل صغيــر ًا ‪ ،‬فلمــا بلــغ الطفــل ســنتني لــم يحضــر لــه حفائــظ‬\n‫أو حليــب هكــذا ذكــرت ‪ ،‬وقــد جــرت الكتابــة إلــى قســم اخلبــراء‬\n‫بهــذه احملكمــة بخطابــي رقــم ‪ 32/1023491‬وتاريــخ ‪1432/8/10‬ه ـ‬\n\n\n                                                                                     ‫‪60‬‬\n\f     ‫بخصــوص حتديــد النفقــة‪ ،‬فوردنــي القــرار الصــادر مــن مكتــب الصلــح‬\n     ‫بهــذه احملكمــة رقــم ‪ 306‬وتاريــخ ‪1432/9/16‬ه ـ املتضمــن ‪ ..( :‬نفيــد‬\n     ‫فضيلتــه أنــه مت االجتمــاع بالطرفــن وقــد تعــذر الصلــح بينهمــا حيــث‬\n     ‫أن املدعيــة تطالــب املدعــى عليــه بالنفقــة عليهــا وعلــى ابنهــا وذلــك‬\n     ‫مــن تاريــخ خروجهــا مــن املنــزل بطلبــه يف ‪1429/7/17‬ه ـ وأنهــا بذلــك‬\n     ‫التاريــخ كانــت حامــل بابنهــا ‪ ...‬البالــغ مــن العمــر ســنتني وخمســة أشــهر‬\n     ‫أمــا املدعــى عليــه فأفــاد بأنــه ليــس لديــه مانــع مــن النفقــة وأنــه يف حالــة‬\n     ‫إلزامــه بالنفقــة فــإن قدرتــه الشــهرية هــي ســتمائة ريــال شــهري ًا للمدعيــة‬\n     ‫وســتمائة ريــال البنــه وجتــدون إقــرار كل منهمــا بطــي املعاملــة ‪ ،‬والــذي‬\n     ‫نــراه أن تكــون النفقــة املاضيــة للمدعيــة خمســمائة ريــال شــهري ًا‬\n     ‫والنفقــة املســتقبلية لهــا والبنهــا ســتمائة ريــال شــهري ًا ‪ )..‬ا‪.‬ه ـ ‪ ،‬وبعــرض‬\n     ‫مــا جــاء يف قــرار مكتــب الصلــح بهــذه احملكمــة علــى املدعيــة ‪ ،‬قــررت‬\n     ‫عــدم موافقتهــا علــى النفقــة املاضيــة وقدرهــا خمســمائة ريــال شــهري ًا ‪،‬‬\n     ‫وموافقتهــا علــى النفقــة املســتقبلية وقدرهــا ســتمائة ريــال شــهري ًا لهــا‬\n     ‫وســتمائة ريــال شــهري ًا البنهــا ‪ ،‬وبعــرض مــا جــاء يف قــرار مكتب الصلح‬\n     ‫ا ‪ :‬إننــي غيــر موافــق علــى دفــع النفقــة‬  ‫علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫املاضيــة ألنهــا خرجــت مــن بيــت الزوجيــة وال مانــع لــدي مــن دفــع النفقــة‬\n     ‫املســتقبلية البنهــا وقدرهــا ســتمائة ريــال شــهري ًا أمــا نفقتهــا املســتقبلية‬\n     ‫وقدرهــا ســتمائة ريــال شــهري ًا فــا مانــع لــدي مــن دفعهــا بشــرط أن‬\n     ‫ترجــع إلــى بيــت الطاعــة هكــذا ذكــر‪ ،‬وبعــرض الصلــح علــى الطرفــن‬\n     ‫لــم يصطلحــا علــى شــيء ‪ ،‬وقــد وردنــي مــن قســم اخلبــراء القــرار رقــم‬\n     ‫‪ 306‬يف ‪1432/09/16‬ه ـ احملــال لــي بشــرح رئيــس احملكمــة العامــة‬\n     ‫بالريــاض رقــم ‪ 32/1023491‬يف ‪1432/9/20‬ه ـ املتضمــن (عليــه نفيــد‬\n\n\n‫‪61‬‬\n\f‫فضيلتــه أنــه مت االجتمــاع بالطرفــن وقــد تعــذر الصلــح بينهمــا حيــث‬\n‫أن املدعيــة تطالــب املدعــى عليــه بالنفقــة عليهــا وعلــى ابنهــا وذلــك‬\n‫مــن تاريــخ خروجهــا مــن املنــزل بطلبــه يف ‪1429/7/17‬ه ـ وأنهــا بذلــك‬\n‫التاريــخ كانــت حامــل بابنهــا ‪ ...‬البالــغ مــن العمــر ســنتني وخمســة أشــهر‬\n‫أمــا املدعــى عليــه أفــاد بأنــه ليــس لديــه مانــع مــن النفقــة وأنــه يف حالــة‬\n‫إلزامــه بالنفقــة فــإن قدرتــه هــي ‪ 600‬ريــال شــهريا للمدعيــة و ‪600‬‬\n‫ريــال البنــه وجتــدون إقــرار كال منهمــا بطــي املعاملــة والــذي نــراه أن‬\n‫تكــون النفقــة املاضيــة للمدعيــة ‪ 500‬ريــال شــهريا والنفقــة املســتقبلية‬\n‫لهــا والبنهــا ‪ 600‬ريــال شــهريا هــذا مــا لدينــا ‪ ،‬أعضــاء مكتــب الصلــح‬\n‫‪ ...‬توقيعــه ‪ ... ،‬توقيعــه ‪ ،‬مديــر مكتــب الصلــح ‪ ...‬توقيعــه ) وبعــرض‬\n‫هــذا القــرار علــى املدعيــة قالــت‪ :‬إننــي موافقــة عليــه وأطلــب أن يضــاف‬\n‫حتديــد نفقــة االبــن املاضيــة أمــا املدعــى عليــه فقــرر عــدم موافقتــه علــى‬\n‫القــرار وأنــه ال مانــع لديــه مــن النفقــة املســتقبلية وقدرهــا ســبعمائة ريــال‬\n‫شــهريا فقــط هكــذا ذكــر ‪ ،‬وألن قــرار قســم اخلبــراء لــم يتضمــن نفقــة‬\n‫االبــن املاضيــة قــررت الكتابــة لهــم لتحديــد النفقــة لــذا رفعــت اجللســة‬\n‫حلــن ورود اإلجابــة ويف جلســة أخــرى حضــرت املدعيــة وبرفقهــا والدهــا‬\n‫واملدعــى عليــه وقــد وردنــي قــرار قســم اخلبــراء يف هــذه احملكمــة رقــم‬\n‫‪122‬يف ‪1433/2/14‬ه ـ املتضمــن ( نفيــد فضيلتــه أنــه مت االجتمــاع‬\n‫بالطرفــن وقــد تعــذر الصلــح بينهمــا بخصــوص تقديــر نفقــة االبــن‬\n‫الســابقة وبنــاء علــى ذلــك فإننــا نــرى أن تكــون نفقــة االبــن الســابقة‬\n‫‪600‬ريــال شــهري ًا أمــا نفقتــه املســتقبلية وكذلــك نفقــة املدعيــة الســابقة‬\n‫واملســتقبلية فقــد ســبق وأن مت تقديــر ذلــك مبوجــب قرارنــا املرفــق‬\n‫برقــم ‪ 32/306‬تاريــخ ‪1432/9/16‬ه ـ املتضمــن نفقــة االبــن املســتقبلية‬\n\n\n                                                                                         ‫‪62‬‬\n\f     ‫‪600‬ريــاال شــهري ًا ونفقــة املدعيــة املاضيــة ‪500‬ريــاال شــهري ًا واملســتقبلية‬\n     ‫‪600‬ريــاال شــهري ًا لــكل واحــد منهمــا تــودع يف حســاب املدعيــة هــذا مــا‬\n     ‫لدينــا واهلل يحفظكــم) ا‪.‬ه ـ ثــم ســألت املدعيــة هــل طلبهــا املدعــى عليــه‬\n     ‫بعــد خروجهــا مــن بيــت زوجها فقالت‪ :‬نعــم طلبني لبيت الطاعة ورفضت‬\n     ‫الرجــوع ألنــه طردنــي مــن البيــت هكــذا ذكــرت ثــم حصلــت مداولــة‬\n     ‫بــن الطرفــن مــن أجــل اإلصــاح بينهمــا ‪ ،‬ويف جلســة أخــرى حضــرت‬\n     ‫املدعيــة وبرفقهــا والدهــا واملدعــى عليــه وطلبــت املدعيــة إلــزام املدعــى‬\n     ‫عليــه بدفــع نفقــة االبــن املاضيــة منــذ والدتــه واملســتقبلية كنفقــة شــهرية‬\n     ‫وإلــزام املدعــى عليــه بدفــع نفقتهــا املاضيــة ثــم ســألت املدعيــة واملدعــى‬\n     ‫عليــه عــن تاريــخ والدة ولدهمــا فأجابــا هــو مولــود بتاريــخ ‪1430/4/2‬ه ـ‬\n     ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعيــة بــأن زوجهــا‬\n     ‫طلبهــا لبيــت الطاعــة‪ ،‬وأنهــا رفضــت ذلــك‪ ،‬ألنــه طردهــا ـ وملــا قــرره أهــل‬\n     ‫العلــم مــن أن النفقــة مقابــل التمكــن مــن االســتمتاع وللــزوم نفقــة األب‬\n     ‫علــى ابنــه ولقــرار قســم اخلبــراء املرصــود أعــاه بخصــوص نفقــة االبــن‬\n     ‫لــذا قــررت مايلــي‪ :‬أوال‪ /‬صرفــت النظــر عــن مطالبــة املدعيــة بنفقتهــا‬\n     ‫ثانيــا‪ /‬ألزمــت املدعــى عليــه بدفــع نفقــة ابنــه املســتقبلية وقدرهــا ســتمائة‬\n     ‫ريــال شــهريا اعتبــارا مــن شــهر ربيــع اآلخــر مــن هــذا العــام ‪1433‬ه ـ ودفع‬\n     ‫نفقــة االبــن املاضيــة وقدرهــا ســتمائة ريــال شــهريا اعتبــارا مــن تاريــخ‬\n     ‫والدتــه ‪1430/4/2‬ه ـ ومجموعهــا حتــى شــهر ربيــع األول لعــام ‪1433‬ه ـ‬\n     ‫واحــد وعشــرون ألــف ريــال ومبــا تقــدم حكمــت وبعرضــه عليهمــا قررت‬\n     ‫املدعيــة القناعــة فيمــا يتعلــق بنفقــة ابنهــا املاضيــة واملســتقبلية وقــررت‬\n     ‫عــدم القناعــة فيمــا يتعلــق بنفقتهــا وقــرر املدعــى عليــه عــدم القناعــة‬\n     ‫فيمــا يتعلــق بالنفقــة املاضيــة‪ ،‬وأغلقــت اجللســة الســاعة ‪ 08.45‬وبــاهلل‬\n\n\n‫‪63‬‬\n\f‫التوفيــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبه وســلم‪.‬‬\n                                                       ‫حــرر يف ‪1433/4/6‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت إلينــا املعاملــة مــن محكمــة‬\n‫االســتئناف برقــم ‪ 34326795‬يف ‪1434/03/02‬ه ـ محالــة إلينــا‬\n‫بالقيــد رقــم ‪ 34/590732‬وتاريــخ ‪1434/03/08‬ه ـ مــزودة بالقــرار‬\n‫رقــم ‪ 3444281‬يف ‪1434/02/23‬ه ـ بخصــوص دعــوى ‪ ...‬ضــد ‪...‬‬\n‫واملتضمــن ( حيــث ســبقت دراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة بنــاء علــى قــرار الدائــرة رقــم ‪33327814‬‬\n‫وتاريــخ ‪1433/07/05‬ه ـ وباالطــاع علــى مــا أجــاب بــه فضيلتــه لــم‬\n‫يظهــر باألكثريــة مــا يوجــب االعتــراض‪ ،‬قاضــي اســتئناف ‪ ...‬ختمــه‬\n‫وتوقيعــه‪ ،‬قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه ‪ ،‬رئيــس الدائــرة د‪ ... .‬لــه‬\n‫وجهــة نظــر مرفقــة ختمــه وتوقيعــه )ا‪.‬ه ـ ‪ ،‬لــذا أمــرت بالتهميــش علــى‬\n‫الضبــط والســجل بذلــك‪ ،‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/03/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫املختصــة بتمييــز قضايــا األحــوال الشــخصية واالنهــاءات مبحكمــة‬\n‫االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 33/1394051‬وتاريــخ ‪1434/1/27‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...‬املســجل‬\n‫برقــم ‪ ...‬وتاريــخ ‪1433/4/11‬ه ـ اخلــاص بدعــوى ‪ ...‬ضــد ‪ ...‬بشــأن طلــب‬\n‫املدعيــة إلــزام املدعــى عليــه بدفــع النفقــة املوضحــة بالصــك املتضمــن أن‬\n‫فضيلتــه قــرر مــا يلــي ‪ /‬أوال ‪ :‬صــرف النظــر عن مطالبــة املدعية بنفقتها‪.‬‬\n‫ثانيــا ‪ :‬الــزم املدعــى عليــه بدفــع نفقــة ابنــه ‪ ...‬إلــخ وبــه حكــم ‪ .‬حيــث‬\n\n\n                                                                                      ‫‪64‬‬\n\f     ‫ســبقت دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n     ‫املعاملــة بنــاء علــى قــرار الدائــرة رقــم ‪ 33327814‬وتاريــخ ‪1433/7/5‬ه ـ‬\n     ‫وباالطــاع علــى مــا أجــاب بــه فضيلتــه لــم يظهــر باألكثريــة مــا يوجــب‬\n     ‫االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                           ‫وســلم ‪.‬‬\n\n\n\n\n‫‪65‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":58,"source_page_end":65,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0320291b415877de95efe623b5658b0592cf599133f62c3074771fd2d71756a7","normalized_text_hash":"f8d6f06ed49fd92d1c226e6b0ec9a5e56a996ca731a80ac1108b8486ddb8797c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p58-33182259"},{"id":"78c4431a-269d-5c92-8706-d8281398858b","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة الزوجة بنفقتها املاضية واملستقبلية -مطالبة األم بنفقة ابنها املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء - -احلكم بتسليم النفقة املاضية واملستقبلية للزوجة","document_number":"34180121","case_number":"33248699","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/6","year":"1434","subject":"نفقة -مطالبة الزوجة بنفقتها املاضية واملستقبلية -مطالبة األم بنفقة ابنها املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء - -احلكم بتسليم النفقة املاضية واملستقبلية للزوجة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34180121 :‬‬\n                   ‫َر ْق ُم الدعوى‪33248699 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34258270‬تاريخه‪1434/7/3 :‬هـ‬\n\n\n‫نفقــة ‪ -‬مطالبــة الزوجــة بنفقتهــا املاضيــة واملســتقبلية ‪ -‬مطالبــة األم‬\n‫بنفقــة ابنهــا املاضيــة واملســتقبلية ‪ -‬تقديــر النفقــة عــن طريــق قســم‬\n‫اخلبــراء ‪ - -‬احلكــم بتســليم النفقــة املاضيــة واملســتقبلية للزوجــة‬\n                                                                    ‫وابنهــا‪.‬‬\n\n\n\n                                         ‫قوله تعالى {ل ُِي ْنفِ ْق ُذو َس َع ٍة مِ ْن َس َع ِتهِ}‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه زوجهــا دخــل بهــا وأجنبــت منــه ابن ًا‬\n‫واحــد ًا مولــود ًا يف ‪1431/7/16‬ه ـ وأنــه أخرجهــا مــن بيــت الزوجيــة إلــى‬\n‫ال ألنــه‬‫بيــت أهلهــا يف ‪1432/6/28‬ه ـ ألنهــا طلبــت منــه ســكن ًا مســتق ً‬\n‫ال حســب ما شــرط‬     ‫اســكنها يف بيــت أهلــه ولــم يجعــل لها ســكن ًا مســتق ً‬\n‫عليــه يف العقــد وطلبــت إلــزام املدعــى عليــه بنفقتهــا املاضيــة و القادمــة‬\n‫ونفقــة ابنهــا املاضيــة والقادمــة حيــث أنهــا تنفــق علــى ابنهــا بنيــة الرجــوع‬\n‫علــى املدعــى عليــه‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر‬\n‫أنهــا غــادرت إلــى بيــت أهلهــا بســبب رفــض اســتمرار الســكن مــع أهلــه‬\n‫وأنــه ال مانــع لديــه مــن تســليمها النفقــة لهــا والبنهــا بعــد تقديرهــا علمـ ًا‬\n‫أن ظروفــه املاديــة ال تســمح لــه بتأمــن ســكن مســتقل‪ ،‬مت تقديــر‬\n\n                                                                                                    ‫‪66‬‬\n\f     ‫النفقــة للمدعيــة وابنهــا مــن قبــل مكتــب الصلــح لــكل واحــد منهمــا‬\n     ‫مبلــغ أربعمائــة ريــال‪ ،‬قــرر ناظــر القضيــة لألســباب التــي ذكرهــا يف‬\n     ‫نــص القضيــة ولقولــه تعالــى {ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة مِ ــنْ َسـ َـع ِتهِ} إلــزام املدعــى‬\n     ‫عليــه بنفقــة االبــن ووالدتــه املاضيــة لــكل واحــد منهمــا مبلغ ـ ًا قــدره‬\n     ‫ثمانيــة آالف وأربعمائــة ريــال‪ ،‬وإلزامــه بنفقــة االبــن أربعمائــة ريــال‬\n     ‫شــهري ًا مــادام مــع والدتــه يف حضانتهــا ونفقــة شــهرية للمدعيــة أربعمائــة‬\n     ‫ال أو ينقطــع عقــد الزوجــة‬          ‫ال لهــا مســتقب ً‬         ‫ريــال حتــى يهيــئ بيت ـ ًا مســتق ً‬\n     ‫بطــاق و نحــوه‪ ،‬قــررت املدعيــة املعارضــة وقــرر املدعــى عليــه القناعــة‪،‬‬\n                    ‫صــدر قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض برقــم ‪ 33248699‬وتاريــخ ‪1433/04/10‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 33666540‬وتاريــخ ‪1433/04/10‬ه ـ ففــي يــوم‬\n     ‫الثالثــاء املوافق‪1433/06/24‬ه ـ افتتحــت اجللســة وفيهــا حضــرت‬\n     ‫ســعودية مبوجــب ســجل مدنــي رقــم (‪ ).....‬املعــرف بهــا مــن قبــل والدهــا‬\n     ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬وادعــت علــى احلاضــر معهــا‬\n     ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬قائلــة يف دعواهــا ‪ :‬إن املدعــى‬\n     ‫عليــه هــذا احلاضــر معــي زوجــي مبوجــب عقــد النــكاح لــدى مــأذون‬\n     ‫االنكحــة برقــم ‪........‬وتاريــخ ‪ 1430/6/6‬علــى مهــر وقــدره خمســون‬\n     ‫الــف ريــال مقبوضــة ودخــل بــي الدخــول الشــرعي وأجنبــت منــه (‪).....‬‬\n     ‫املولــود يف ‪1431/7/16‬ه ـ وأخرجنــي مــن بيتــي الــى بيــت أهلــي يف‬\n\n‫‪67‬‬\n\f‫‪1432/6/28‬ه ـ حيــث قــال لــي روحــي ألهلــك إلننــي طلبــت منــه ســكنا‬\n‫مســتقال لــي ألنــه أســكنني يف بيــت أهلــه املســتأجر فاتصلــت علــى‬\n‫اهلــي وأخذونــي ثــم بعــد اســبوعني احضــر عفشــي الــى بيــت اهلــي والــى‬\n‫ال حســب شــرط العقــد لــذا اطلــب الزامــه‬     ‫االن لــم يجعــل لــي بيتـ ًا مســتق ً‬\n‫بنفقتــي املاضيــة والقادمــة ونفقــة ابنــي ‪........‬املاضيــة والقادمــة بعــد‬\n‫تقديرهــا وقــد كنــت انفــق عليــه بنيــة الرجــوع يف النفقــة ولــم يســلم لــي‬\n‫مــن نفقــة ســوى ســتمائة ريــال فقــط هــذه دعــواى وبعرضها علــى املدعى‬\n‫عليــه اجــاب قائــا ‪ :‬مــا ذكرتــه املدعيــة مــن زواجــي بهــا والدخــول واملهر‬\n‫واجنابهــا منــي ‪........‬وســلمت لهــا مــن النفقــة ســتمائة ريــال فقــط فهــذا‬\n‫كلــه صحيــح ومــا ذكرتــه اننــي طلبــت منهــا الذهــاب الــى اهلهــا فغيــر‬\n‫صحيــح بــل خرجــت مــن نفســها النهــا ترفــض اســتمرار الســكن مــع‬\n‫اهلــي وانــا الاســتطيع ان اضــع لهــا ســكنا مســتقال لعــدم مقدرتــي‬\n‫املاديــة وال مانــع لــدي مــن تقديــر نفقتهــا ونفقــة ابنــي املاضيــة والقادمــة‬\n‫وتســليمها لهــا متــى مــا كانــت تناســب قدرتــي املاديــة هكــذا أجــاب‬\n‫لــذا أمــرت بالكتابــة لقســم اخلبــراء لتقديــر النفقــة املدعــى بهــا‪ .‬ويف يــوم‬\n‫الســبت املوافق‪1434/04/06‬هـ افتتحت اجللســة وفيها حضرت املدعية‬\n‫املعــرف بهــا مــن قبــل أخيهــا ‪ .....‬ســعودي مبوجــب ســجل مدنــي رقــم (‪).....‬‬\n‫وحضــر املدعــى عليــه ووردنــا خطــاب مديــر مكتــب الصلــح برقــم ‪........‬‬\n‫وتاريــخ ‪1434/3/25‬ه ـ املتضمــن أنــه مت االجتمــاع بالطرفــن وقــد تعــذر‬\n‫الصلــح بينهمــا بخصــوص النفقــة حيــث ذكــرت املدعيــة أنهــا تطالــب‬\n‫بنفقتهــا ونفقــة ابنهــا املاضيــة واملســتقبلية وأنــه لــم ينفــق عليهــم مــن مــا‬\n‫يقــارب ســنة وثمانيــة أشــهر وأن النفقــة تكلفهــا ‪ 800‬ريــال وابنهــا ‪800‬‬\n‫ريــال أمــا بالنســبة للمدعــى عليــه فقــد ذكــر بأنــه ليــس لديــه مانــع مــن‬\n\n\n                                                                                          ‫‪68‬‬\n\f     ‫النفقــة للمدعيــة وابنهــا بواقــع ‪ 600‬ريــال شــهريا وذلــك حســب ظروفــه‬\n     ‫يف الوقــت احلاضــر وأن مرتبــه ‪ 3500‬ريــال ويوجــد عليــه قســط شــهري‬\n     ‫‪ 1771‬ريــال وجتــدون إقــرار كال منهمــا بطــي املعاملــة وبنــاء علــى ذلــك‬\n     ‫واحلــال كمــا ذكــر وبعــد االطــاع علــى مقــدار مرتــب املدعــى عليــه‬\n     ‫حيــث اتضــح أنــه يتقاضــى مرتــب ‪ 3500‬ريــال وذلــك حســب اخلطــاب‬\n     ‫املرفــق رقــم بــدون وتاريــخ ‪1434/2/3‬ه ـ الصــادر مــن إدارة املجاهديــن‬\n     ‫وكذلــك كشــف احلســاب املرفــق واألقســاط املســتحقة عليــه وبعــد‬\n     ‫التأمــل يف الوضــع املــادي للمدعــى عليــه فإننــا نــرى أن تكــون النفقــة‬\n     ‫الســابقة واملســتقبلية للمدعيــة وابنهــا ‪ 400‬ريــال شــهريا لــكل واحــد‬\n     ‫منهمــا هــذا مــا لدينــا‪ .‬أ‪.‬ه ـ وبعــرض ذلــك علــى املدعيــة أجابــت قائلــة‪:‬‬\n     ‫أعــارض مــا جــاء يف قــرار مكتــب الصلــح هكــذا أجابــت‪ .‬وبعرضــه‬\n     ‫علــى املدعــى عليــه أجــاب قائــا‪ :‬أوافــق علــى مــا جــاء يف قــرار مكتــب‬\n     ‫الصلــح هكــذا أجــاب‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n     ‫وقــرار مكتــب الصلــح ولقولــه تعالــى‪( :‬لينفــق ذو ســعة مــن ســعته)‬\n     ‫لــذا ألزمــت املدعــى عليــه أن يدفــع للمدعيــة مــا يلــي‪ :‬أوال‪ :‬نفقــة ابنهــا‬\n     ‫املاضيــة اعتبــارا مــن تاريــخ ‪1432/6/28‬ه ـ حتــى تاريــخ ‪1434/3/28‬ه ـ‬\n     ‫وقدرهــا ثمانيــة األلــف وأربعمائــة ريــال‪ .‬ثاني ـاً‪ :‬نفقتهــا املاضيــة اعتبــارا‬\n     ‫مــن تاريــخ ‪1432/6/28‬ه ـ حتــى تاريــخ ‪1434/3/28‬ه ـ وقدرهــا‬\n     ‫ثمانيــة األلــف وأربعمائــة ريــال‪ .‬ثالثــا‪ :‬نفقــة شــهرية البنهــا اعتبــارا مــن‬\n     ‫‪1434/4/28‬ه ـ وقدرهــا أربعمائــة ريــال مــا دام االبــن معهــا يف بيــت‬\n     ‫والدهــا‪ .‬رابعــا‪ :‬نفقــة شــهرية لهــا اعتبــارا مــن ‪1434/4/28‬ه ـ وقدرهــا‬\n     ‫أربعمائــة ريــال حتــى يهيــئ لهــا املدعــى عليــه ســكنا مســتقال أو ينقطــع‬\n     ‫عقــد الزوجيــة بطــاق ونحــوه‪ .‬وبــه حكمــت وبإعــان احلكــم قــررت‬\n\n\n‫‪69‬‬\n\f‫املدعيــة املعارضــة فســلمتها صــورة احلكــم لتقــدمي اعتراضهــا عليــه‬\n‫خــال ثالثــن يومــا فــإن مضــت املــدة ولــم تقــدم الئحــة اعتراضهــا‬\n‫ســقط حقهــا يف االعتــراض واكتســب احلكــم القطعيــة وأمــا املدعــى‬\n‫عليــه فقــرر الق ـن ــاعـ ــة باحلـك ـ ــم وبــاهلل التوفيــق وصلــى اهلل علـ ــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وسل ــم‪ .‬حـ ــرر يف ‪1434/04/06‬ه ـ ويف يــوم‬\n‫األربع ــاء ‪1434/09/ 16‬ه ـ حســب تقــومي أم القــرى و ‪1434/09/15‬ه ـ‬\n‫حســب الرؤيــة افتتحــت اجللســة الســاعة ‪10.15‬بنــاء علــى ورود املعاملــة‬\n‫أثنــاء إجازتنــا االعتياديــة بشــرح رئيــس احملكمــة علــى القيــد رقــم‬\n‫‪ 341463073‬وتاريــخ ‪1434/07/22‬ه ـ وبرفقــه خطاب رئيس محكمة‬\n‫االســتئناف بالريــاض برقــم ‪ 341463073‬وتاريــخ ‪1434/07/17‬ه ـ‬\n‫وبرفقــه قــرار دائــرة األحــوال الشــخصية الثانيــة برقــم ‪34258270‬‬\n‫وتاريــخ ‪1434/07/03‬ه ـ املتضمــن املصادقــة علــى احلكــم‪ .‬ورفعــت‬\n‫اجللســة يف متــام الســاعة ‪ 10.25‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫الريــاض برقــم‪ 33666540‬وتاريــخ ‪1434/6/12‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ .....‬املســجل برقــم‬\n‫‪ 34180121‬وتاريخ ‪1434/4/6‬هـ اخلاص بدعوى‪ .....‬ضد‪ .....‬يف قضية‬\n‫نفقــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫تقــرر الدائــرة املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى‬\n                                    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                                                             ‫‪70‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":66,"source_page_end":70,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8a6f333e83a6b3492e4885888297d1bc48675d88f8aa7539aaba8542dad6e72f","normalized_text_hash":"b1f86cabca87b7c256e3e76cfae899cf2edf04b7894f6c9c7bab3d492348d42e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p66-34180121"},{"id":"995eb543-d317-51e1-84a3-8bbfeab94e59","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة -طلب الزوجة إعداد مسكن لها -طلب الزوجة نفقتها املاضية -طلب الزوجة إعادة الذهب الذي أخذه الزوج- طلب الزوجة فسخ عقد النكاح يف حال امتناع الزوج عن النفقة- إقامة دعوى النفقة يف بلد الزوجة -إعام املدعى عليه عن طريق اإلعان يف اجلريدة -شهادة الشهود العدول -فسخ عقد النكاح لتضرر الزوجة من التغيب وعدم النفقة -األخذ بشهادة الشهود قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)","document_number":"33268658","case_number":"32242789","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/26","year":"1434","subject":"نفقة -نفقة زوجة -طلب الزوجة إعداد مسكن لها -طلب الزوجة نفقتها املاضية -طلب الزوجة إعادة الذهب الذي أخذه الزوج- طلب الزوجة فسخ عقد النكاح يف حال امتناع الزوج عن النفقة- إقامة دعوى النفقة يف بلد الزوجة -إعام املدعى عليه عن طريق اإلعان يف اجلريدة -شهادة الشهود العدول -فسخ عقد النكاح لتضرر الزوجة من التغيب وعدم النفقة -األخذ بشهادة الشهود قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/5/26 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33268658 :‬‬\n                        ‫َر ْق ُم الدعوى‪32242789 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34193848‬تاريخه‪1434/4/21 :‬هـ‬\n\n\n\n     ‫نفقــة ‪ -‬نفقــة زوجــة‪ -‬طلــب الزوجــة إعــداد مســكن لهــا‪ -‬طلــب الزوجــة‬\n     ‫نفقتهــا املاضيــة‪ -‬طلــب الزوجــة إعــادة الذهــب الــذي أخــذه الــزوج‪-‬‬\n     ‫طلــب الزوجــة فســخ عقــد النــكاح يف حــال امتنــاع الــزوج عــن النفقــة‪-‬‬\n     ‫إقامــة دعــوى النفقــة يف بلــد الزوجــة‪ -‬إعــام املدعــى عليــه عــن طريــق‬\n     ‫اإلعــان يف اجلريــدة‪ -‬شــهادة الشــهود العــدول ‪ -‬فســخ عقــد النــكاح‬\n     ‫لتضــرر الزوجــة مــن التغيــب وعــدم النفقــة‪ -‬األخــذ بشــهادة الشــهود‬\n\n\n\n\n                                     ‫قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)‬\n\n\n\n\n     ‫حضــرت املدعيــة ولــم يحضــر املدعــى عليــه‪ -‬ادعــت املدعيــة بــأن املدعــى‬\n     ‫عليــه تزوجهــا بواليــة والدهــا بتاريــخ ‪1429/6/1‬ه ـ علــى مهــر مســمى‬\n     ‫مســلم ودخــل بهــا الدخــول الشــرعي وبقيــت معــه مــا يقــارب العــام يف‬\n     ‫شــقق مفروشــة ولــدى أســرته ثــم بعــد ذلــك قــام بوضعهــا لــدى أســرتها‬\n     ‫وامتنــع مــن اإلنفــاق عليهــا وإعــداد مســكن لهــا‪ ،‬طلبــت املدعيــة احلكم‬\n     ‫علــى املدعــى عليــه بإعــداد مســكن لهــا ودفــع نفقتهــا املاضيــة وإعــادة‬\n     ‫الذهــب الــذي أخــذه منهــا فــإن امتنــع مــن ذلــك فإنهــا تطلــب فســخ عقــد‬\n     ‫النــكاح منــه‪ -‬جــرت الكتابــة حملكمــة خميــس مشــيط محــل إقامــة‬\n‫‪71‬‬\n\f‫املدعــى عليــه يف ســماع اإلجابــة‪ ،‬ورد اجلــواب بعــدم العثــور علــى املدعــى‬\n‫عليــه‪ -‬جــرى اإلعــان يف اجلريــدة لتبليــغ املدعــى عليــه‪ ،‬يف جلســة أخــرى‬\n‫حضــرت املدعيــة وقــررت أنهــا تطلــب فســخ نكاحهــا مــن املدعــى عليــه‬\n‫لتضررهــا بتغيبــه وعــدم النفقــة‪ ،‬أحضــرت شــاهدين وشــهدا بصحــة مــا‬\n‫ذكرتــه املدعيــة وأن املدعــى عليــه غائــب عــن املدعيــة مــن مــدة تزيــد‬\n‫علــى الســنتني وال ينفــق عليهــا‪ ،‬جــرى تعديــل الشــاهدين‪ ،‬ملــا جــاء يف‬\n‫دعــوى املدعيــة والبينــة املعدلــة وقولــه صلــى اهلل عليــة وســلم (ال ضــرر‬\n‫وال ضــرار) لــذا فقــد فســخ فضيلــة القاضــي نــكاح املدعيــة مــن زوجهــا‬\n‫املدعــى عليــه الغائــب بحضــور وشــهادة الشــاهدين املعرفــن بهــا وبذلــك‬\n‫حكــم‪ ،‬جــرى إفهــام املدعيــة بــأن عليهــا العــدة الشــرعية ثالثــة قــروء‬\n‫مــن تاريــخ صــدور احلكــم وأال تتــزوج إال بعــد اكتســاب احلكــم‬\n‫القطعيــة‪ ،‬لوحــظ علــى احلكــم مــن محكمــة االســتئناف بأنــه لــم يتــم‬\n‫إبــاغ املدعــى عليــه بالدعــوى عــن طريــق اجلهــات الرســمية وأن ينــص يف‬\n‫احلكــم أن الغائــب علــى حجتــه فيمــا يخــص املــال فقــط‪ ،‬جــرى الكتابة‬\n‫لوكيــل إمــارة منطقــة الريــاض للبحــث عــن املدعــى عليــه يف الســجون‬\n‫واملستشــفيات وإفــادة اجلــوازات هــل هــو داخــل أم خــارج اململكــة‪ ،‬ورد‬\n‫اجلــواب مبــا يفيــد بــأن املدعــى عليــه متغيــب ولــم يعثــر عليــه‪ ،‬جــرى‬\n‫التنويــه بــأن املدعــى عليــه الغائــب علــى حجتــه متــى حضــر فيمــا يخــص‬\n                   ‫املــال فقــط‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                   ‫‪72‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض برقــم ‪ 32242789‬وتاريــخ ‪ 1432/06/22‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 32741131‬وتاريــخ ‪ 1432/06/19‬ه ـ ففــي يــوم‬\n     ‫األربعــاء املوافــق‪ 1432/12/27‬ه ـ حضرت ‪ ...‬ســعودية اجلنســية مبوجب‬\n     ‫الســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى عليــه وال مــن يقــوم مقامــه‬\n     ‫بوكالــة شــرعية وادعــت علــى الغائــب عــن مجلــس احلكــم ‪ ...‬قائلــة ان‬\n     ‫املدعــى عليــه هــو زوجــي تزوجنــي بعقــد صحيــح بواليــة والــدي بتاريــخ‬\n     ‫‪1429/6/1‬ه ـ علــى مهــر وقــدره خمســة عشــر الــف ريــال مقبوضــة‬\n     ‫ودخــل بــي الدخــول الشــرعي وبقيــت معــه مــا يقــارب العــام يف شــقق‬\n     ‫مفروشــة ولــدى اســرته ثــم بعــد ذلــك قــام بوضعــي لــدى اســرتي وامتنــع‬\n     ‫مــن االنفــاق علــي واعــداد مســكن لــي وهــو حاليــا يقيــم يف محافظــة‬\n     ‫خميــس مشــيط واطلــب احلكــم علــى املدعــى عليــه بإعــداد مســكن‬\n     ‫لــي ودفــع نفقتــي املاضيــة واعــادة الذهــب الــذي اخــذه منــي وان امتنــع‬\n     ‫مــن ذلــك فإننــي اطلــب فســخ نكاحــي منــه هــذه دعــواي ونظــرا لكــون‬\n     ‫املدعــى عليــه يقيــم يف محافظــة خميــس مشــيط فقــد قــررت الكتابــة‬\n     ‫للمحكمــة العامــة بخميــس مشــيط الســتخالف رئيســها او مــن ينيبــه‬\n     ‫مــن قضــاة احملكمــة يف احضــار املدعــى عليــه وســماع اجابتــه علــى‬\n     ‫دعــوى املدعيــة ورفعــت اجللســة حتــى ورود اجلــواب ويف جلســة أخــرى‬\n     ‫لــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة بالريــاض ففــي يــوم اإلثنــن‬\n     ‫املوافق‪1433/05/24‬ه ـ حضــرت املدعيــة واملعــرف بهــا مــن قبــل كل‬\n\n‫‪73‬‬\n\f‫مــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬و ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى عليــه‬\n‫وبتــاوة مــا مت ضبطــه عليهــم صادقــت عليــه كمــا وردنــا خطــاب فضيلــة‬\n‫رئيــس احملكمــة العامــة يف محافظــة خميــس مشــيط رقــم ‪331462‬‬\n‫وتاريــخ ‪1433/3/15‬ه ـ املرفــق بــه خطــاب فضيلــة القاضــي باحملكمــة‬\n‫‪ ...‬املتضمــن أنــه حــددت جلســة للمدعــى عليــه ومت طلبــه ووردت اإلفــادة‬\n‫مــن احملضريــن بعــدم العثــور عليــه واالســتدالل علــى عنوانــه وقــد جــرى‬\n‫اإلعــان عــن طلــب حضــور املدعــى عليــه يف صحيفــة االقتصاديــة‬\n‫بعددهــا رقــم ‪ 6720‬وتاريــخ ‪1433/3/12‬ه ـ وحتديــد هــذا اليــوم موعــدا‬\n‫لنظــر دعــوى املدعيــة ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه‬\n‫وقــررت املدعيــة قائلــة إننــي قــد تضــررت مــن غيــاب زوجــي املدعــى عليــه‬\n‫وعــدم انفاقــه علــي وال أعــرف لــه مــكان إقامــة لــذا فإننــي أطلــب فســخ‬\n‫نكاحــي منــه هــذه دعــواي وبطلــب البينــة منهــا استشــهدت مبــن عــرف‬\n‫بهــا وبســؤالهما شــهدا كل واحــد منهمــا مبفــرده قائــا إن املدعيــة جــارة‬\n‫لــي يف الســكن وأشــهد أن زوجهــا املدعــى عليــه ‪ ...‬غائــب عنهــا منــذ‬\n‫مــدة تزيــد عــن ســنتني وأنــا أعــرف املدعيــة معرفــة تامــة وال ينفــق عليهــا‬\n‫وال يحضــر إليهــا إطالقــا وقــد تضــررت مــن غيابــه فــا يوجــد مــن ينفــق‬\n‫عليهــا وال مــن يقــوم بشــؤونها هكــذا شــهدا وبطلــب معدلــن للشــاهدين‬\n‫أحضــرت كال مــن ‪ ...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ ...‬و‪...‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وشــهدا مبعرفتهمــا‬\n‫للشــاهدين وبثقتهمــا وعدالتهمــا وأنهمــا مقبــوال الشــهادة فبنــاء علــى مــا‬\n‫تقــدم مــن دعــوى املدعيــة وشــهادة الشــاهدين املعدلــن التعديــل الشــرعي‬\n‫واللــذان شــهدا بغيبــة املدعــى عليــه وعــدم إنفاقــه علــى املدعيــة وأنهــا‬\n\n\n                                                                                      ‫‪74‬‬\n\f     ‫تضــررت مــن ذلــك وألنــه ســبق وأن أعلــن يف الصحيفــة املذكــورة عــن‬\n     ‫طلــب املدعــى عليــه ولــم يحضــر ولــم تردنــا أي إفــادة عنــه ولقولــه صلــى‬\n     ‫اهلل عليــه وســلم (ال ضــرر وال ضــرار) وألن املدعيــة قــد تضــررت مــن‬\n     ‫غيــاب املدعــى عليــه وعــدم نفقتــه عليهــا مــدة طويلــة لــذا فســخت نــكاح‬\n     ‫املدعيــة ‪ ...‬مــن زوجهــا املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪...‬‬\n     ‫بحضــور وشــهادة الشــاهدين املعرفــن بهــا وبذلــك حكمــت وأفهمتهــا‬\n     ‫بــأن عليهــا العــدة الشــرعية ثالثــة قــروء مــن تاريــخ اليــوم وأال تتــزوج إال‬\n     ‫بعــد اكتســاب احلكــم الصفــة القطعيــة وأمــرت بتنظيــم الصــك الــازم‬\n     ‫وبعثــه مــع كامــل أوراق املعاملــة إلــى محكمــة االســتئناف وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                         ‫حــرر يف ‪ 1433/05/24‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/4/1‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة الثانيــة والنصــف ظهــرا وقــد وردنــا خطــاب فضيلــة‬\n     ‫رئيــس احملكمــة املســاعد رقــم ‪ 33/1394920‬وتاريــخ ‪1433/7/23‬ه ـ‬\n     ‫شــرح ًا علــى خطــاب فضيلــة رئيــس محكمــة االســتئناف املســاعد رقــم‬\n     ‫‪ 331065922‬وتاريــخ ‪1433/7/15‬ه ـ املرفــق بــه قــرار دائــرة األحــوال‬\n     ‫الشــخصية األولــى رقــم ‪ 33320840‬وتاريــخ ‪1433/6/30‬ه ـ املتضمــن‬\n     ‫(وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لوحــظ مــا يلــي‪:‬‬\n     ‫أوالً‪ /‬لــم يتــم إبــاغ املدعــى عليــه بالدعــوى عــن طريــق اجلهــات الرســمية‬\n     ‫حســبما نصــت عليــه التعليمــات والبــد مــن ذلــك‪ .‬ثاني ـ ًا ‪ /‬علــى فضيلتــه‬\n     ‫أن ينــص أن الغائــب علــى حجتــه فيمــا يخــص املــال فقــط ‪ .‬واهلل املوفــق)‬\n     ‫وعليــه أجيــب أصحــاب الفضيلــة بأنــه قــد جــرى مخاطبــة وكيــل أمــارة‬\n     ‫منطقــة الريــاض باخلطــاب رقــم ‪ 33/1461867‬يف ‪1433/8/4‬ه ـ‬\n\n\n‫‪75‬‬\n\f‫للبحــث عــن املدعــى عليــه يف الســجون واملستشــفيات وإفــادة اجلــوازات‬\n‫وهــل هــو داخــل أم خــارج اململكــة فوردنــا خطــاب مديــر مركــز شــرطة‬\n‫الفيصليــة واخلالديــة رقــم ‪ 12/6/1545/2‬يف ‪1434/3/7‬ه ـ املتضمــن‬\n‫أنــه مت مكاتبــة ســجون منطقــة الريــاض فــورد جوابهــم أنــه ليس مســجل‬\n‫باحلاســب اآللــي لديهــم وكذلــك مخاطبــة جــوازات منطقــة الريــاض ولــم‬\n‫تــرد اإلفــادة مــن قبلهــم أ‪.‬ه ـ وكمــا يتضــح ألصحــاب الفضيلــة أن املدعى‬\n‫عليــه متغيــب ولــم يعثــر عليــه ‪ .‬وأمــا مــا يتعلــق باملالحظــة الثانيــة فــإن‬\n‫املدعــى عليــه الغائــب علــى حجتــه متــى مــا حضــر فيمــا يخــص املــال‬\n‫فقــط وأمــرت باحلــاق ذلــك بالصــك وســجله وإعادتــه مــع كامــل أوراق‬\n‫املعاملــة إلــى محكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة بالريــاض‬\n‫ويف يــوم األربعــاء املوافــق ‪1434/5/1‬ه ـ افتتحــت اجللســة بنــاء علــى مــا‬\n‫وردنــا مــن فضيلــة الرئيــس برقــم ‪ 34/941091‬يف ‪1434/4/29‬ه ـ‬\n‫شــرحا علــى خطــاب رئيــس محكمــة االســتئناف برقــم ‪34941091‬‬\n‫يف ‪1434/4/29‬ه ـ وبرفقــه قــرار الدائــرة احلقوقيــة اخلامســة رقــم‬\n‫‪ 34193848‬يف ‪1434/4/21‬ه ـ واملتضمــن مــا نصــه ( وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه علــى الصــك وصــورة الضبــط‬\n‫بتاريــخ ‪1434/4/1‬ه ـ بنــاء علــى قرارنــا رقــم ‪ 33320840‬وتاريــخ‬\n‫‪1433/6/30‬هـ لم يظهر ما يوجب االعتراض ) ا‪.‬هـ قاضي االستئناف‬\n‫‪ ...‬ختمــه وتوقيعــه وقاضــي االســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫د‪ ... .‬ختمــه وتوقيعــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                               ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/1‬ه ـ‬\n\n\n                                                                                       ‫‪76‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n     ‫لتمييــز قضايــا األحــوال الشــخصية واالنهــاءات مبحكمــة االســتئناف‬\n     ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫بالريــاض املســاعد برقــم ‪ 331394920‬وتاريــخ ‪1434/4/8‬ه ـ املرفــق‬\n     ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...‬املســجل‬\n     ‫برقــم ‪ 33268658‬وتاريــخ ‪1433/5/26‬ه ـ اخلــاص بدعــوى ‪ ......‬ضــد‬\n     ‫‪ ...‬بشــأن طلــب املدعيــة فســخ نكاحهــا مــن املدعــى عليــه ‪ ،‬وقــد‬\n     ‫تضمــن الصــك أن فضيلتــه فســخ نــكاح املدعيــة مــن املدعــى عليــه وبــه‬\n     ‫حكــم ‪ ...‬إلــخ ‪ .‬وحيــث ســبقت دراســة الصــك وصــورة ضبطــه وأوراق‬\n     ‫املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه علــى‬\n     ‫الصــك وصــورة الضبــط بتاريــخ ‪1434/4/1‬ه ـ بنــاء علــى قرارنــا رقــم‬\n     ‫‪ 33320840‬وتاريــخ ‪1433/6/30‬ه ـ لــم يظهــر مــا يوجــب االعتــراض مــع‬\n     ‫تنبيــه فضيلتــه إلــى التهميــش علــى عقــد النــكاح مبــا تقــرر لديــه ‪ .‬واهلل‬\n                  ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪77‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":71,"source_page_end":77,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ab5aa293a82c9a440182a86060e7b58eed80f53c63eeec29ae735c10ae437745","normalized_text_hash":"7c53c02a50d090639694bc68983e135882c7b76166388cde8c48427fad36fc1b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p71-33268658"},{"id":"38187a51-3b32-514b-90d8-896216524c92","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة الزوجة املاضية و املستقبلية -سماع دعوى الزوجة يف بلدها -استخالف المحكمة التي يقيم فيها الزوج لسماع جوابه -ما ورد من إقرار بحكم سابق له حجيته القاطعة -رفض الزوج النفقة بحجة نشوز الزوجة -تقدير النفقة من قبل قسم اخلبراء -رفض الزوجة الرجوع لعدم توفير الزوج للبيت الشرعي ال يسقط حقها يف النفقة -نفقة الزوجة ال تسقط بالتقادم -املطالبة بنفقة","document_number":"33345548","case_number":"3315262","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/16","year":"1434","subject":"نفقة -نفقة الزوجة املاضية و املستقبلية -سماع دعوى الزوجة يف بلدها -استخالف المحكمة التي يقيم فيها الزوج لسماع جوابه -ما ورد من إقرار بحكم سابق له حجيته القاطعة -رفض الزوج النفقة بحجة نشوز الزوجة -تقدير النفقة من قبل قسم اخلبراء -رفض الزوجة الرجوع لعدم توفير الزوج للبيت الشرعي ال يسقط حقها يف النفقة -نفقة الزوجة ال تسقط بالتقادم -املطالبة بنفقة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/7/16 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33345548 :‬‬\n                    ‫َر ْق ُم الدعوى‪3315262 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34166991‬تاريخه‪1434/3/21 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة الزوجــة املاضيــة و املســتقبلية ‪ -‬ســماع دعــوى الزوجــة‬\n‫يف بلدهــا ‪ -‬اســتخالف احملكمــة التــي يقيــم فيهــا الــزوج لســماع جوابــه‬\n‫‪ -‬مــا ورد مــن إقــرار بحكــم ســابق لــه حجيتــه القاطعــة ‪ -‬رفــض الــزوج‬\n‫النفقــة بحجــة نشــوز الزوجــة ‪ -‬تقديــر النفقــة مــن قبــل قســم اخلبــراء‬\n‫‪ -‬رفــض الزوجــة الرجــوع لعــدم توفيــر الــزوج للبيت الشــرعي ال يســقط‬\n‫حقهــا يف النفقــة ‪ -‬نفقــة الزوجــة ال تســقط بالتقــادم ‪ -‬املطالبــة بنفقــة‬\n                                                                      ‫العــدة ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعالــى ‪ ( :‬الرجــال قوامــون علــى النســاء مبــا فضــل اهلل بعضهم‬\n                                    ‫علــى بعــض ومبــا انفقــوا مــن أموالهم )‪.‬‬\n‫‪ -2‬قولــه تعالــي ‪ ( :‬لينفــق ذو ســعة مــن ســعته ومــن قــدر عليــه رزقــه‬\n                                                   ‫فلينفــق ممــا آتــاه اهلل )‪.‬‬\n‫‪ -3‬مــا أخرجــه مســلم يف صحيحــه مــن قولــه النبــي صلــى اهلل عليــه‬\n‫وســلم المــرأة أبــي ســفيان رضــي اهلل عنــه ‪ ( :‬خــذي مــن مالــه باملعــروف‬\n                                                      ‫مــا يكفيــك وولــدك)‪.‬‬\n‫‪ -4‬إجمــاع العلمــاء علــى أن الــزوج يجــب عليــه أن ينفــق علــى زوجتــه‬\n                                                               ‫باملعــروف ‪.‬‬\n‫‪ -5‬مــا ترجــح مــن أقــوال العلمــاء أن نفقــة الزوجــة ال تســقط مبضــي‬\n\n                                                                                   ‫‪78‬‬\n\f     ‫الزمــان بــل تعــد دينـ ًا علــى الــزوج ألنــه مــال يجــب علــى ســبيل البــدل يف‬\n              ‫عقــد معاوضــة جــزاء االحتبــاس فــا تســقط مبضــي الزمــان ‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيــة علــى املدعــى عليــه بإنهــا مكثــت عنــده بعــد الــزواج‬\n     ‫شــهرين ونصــف تقريبــا وبعــد إن طالبتــه بســكن شــرعي ومواصلــة‬\n     ‫الدراســة كمــا هــو مشــروط يف عقــد النــكاح قــام بالذهــاب بهــا‬\n     ‫إلــى بيــت أهلهــا بتاريــخ ‪1431/10/15‬ه ـ بحجــة أنــه مســافر ولــم يقــم‬\n     ‫بإرجاعهــا وال النفقــة عليهــا‪ ،‬ذكــرت املدعيــة بــأن املدعــى عليــه أقــام‬\n     ‫عليهــا دعــوى باالنقيــاد لبيــت الزوجيــة وصــدر احلكــم املكتســب‬\n     ‫للقطعيــة بعــدم اســتحقاقه لالنقيــاد لعــدم وفائــه بشــرط املســكن‬\n     ‫املســتقل‪ ،‬طلبــت املدعيــة إلــزام املدعــى عليــه بدفــع النفقــة املاضيــة‬\n     ‫والنفقــة املســتقبلية‪ ،‬أقــر املدعــى عليــه بالــزواج واملهــر والدخــول وذكــر‬\n     ‫إنهــا بقيــت عنــد أهلهــا ملــدة أربعــة أشــهر وذكــر بأنــه حــاول إرجــاع‬\n     ‫زوجتــه فرفضــت‪ ،‬رفــض املدعــى عليــه دفــع النفقــة املاضيــة واملســتقبلية‬\n     ‫لرفــض املدعيــة الرجــوع‪ ،‬ذكــرت املدعيــة بــأن ســبب رفضهــا الرجــوع‬\n     ‫هــو عــدم توفيــر املدعــى عليــه للبيــت الشــرعي‪ ،‬جــرى الرجــوع إلــى‬\n     ‫صــورة احلكــم املذكــور وقــد تضمــن إن وقــت خــروج املدعيــة هــو كمــا‬\n     ‫جــاء يف دعواهــا كمــا تضمــن احلكــم صــرف النظــر عــن طلــب الــزوج‬\n     ‫إلــزام زوجتــه بالرجــوع لعــدم وفائــه بشــرط املســكن‪ ،‬حلفــت املدعيــة‬\n     ‫إن املدعــى عليــه لــم ينفــق عليهــا خــال املــدة املاضيــة مــدة بقائهــا عنــد‬\n     ‫أهلهــا‪ ،‬جــرى تقديــر النفقــة مــن قبــل قســم اخلبــراء باحملكمــة‪ ،‬قــررت‬\n     ‫املدعيــة ان املدعــى عليــه طلقهــا الحق ـاً‪ ،‬حصــرت املدعيــة دعواهــا يف‬\n‫‪79‬‬\n\f‫املطالبــة بنفقتهــا مــدة بقائهــا عنــد أهلهــا حلــن انتهــاء عدتهــا‪ ،‬حيــث إن‬\n‫النفقــة واجبــة علــى الــزوج باإلجمــاع وحيــث إن نفقــة الزوجــة ال تســقط‬\n‫بالتقــادم لــذا صــدر احلكــم بإلــزام املدعــى عليــه بدفــع نفقــة املدعيــة عــن‬\n          ‫املــدة املدعــى بهــا‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 3315262‬وتاريــخ ‪ 1433/01/05‬ه ـ املقيــدة‬\n‫باحملكمة برقم ‪ 3337873‬وتاريخ ‪ 1433/01/05‬هـ ففي يوم االثنني‬\n‫املوافق‪ 1433/01/24‬هـ أفتتحت اجللسة الساعة ‪ 12 : 19‬وفيها حضر‬\n‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬واملعــرف بهــا مــن‬\n‫قبــل والدهــا‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــت‬\n‫قائلــة أدعــي علــى زوجــي ‪ ...‬حيــث تزوجنــي بواليــة والــدي بصــداق قــدره‬\n‫أربعــون ألــف ريــال مســتلم ودخــل بــي بتاريــخ ‪1431/7/29‬ه ـ وبقيــت‬\n‫عنــده مــدة شــهرين ونصــف تقريبــا وبعــد أن طالبتــه بســكن شــرعي‬\n‫ومواصلــة الدراســة كمــا هــو مشــروط يف عقــد النــكاح قــام بالذهــاب‬\n‫بــي إلــى بيــت أهلــي يف تاريــخ ‪1431/10/15‬ه ـ بحجــة أنــه مســافر ولــم‬\n‫يقــم بإرجاعــي حتــى اآلن وال النفقــة علــي وقــد أقــام ضــدي دعــوى انقيــاد‬\n‫وصــدر احلكــم رقــم ‪ 32356169‬يف ‪1432/12/19‬ه ـ املكتســب‬\n‫للقطعيــة بعــدم اســتحقاقه لالنقيــاد لعــدم وفائــه بشــرط املســكن‬\n‫املســتقل أطلــب إلزامــه بالنفقــة املاضيــة واملســتقبلية هكــذا ادعــت‬\n‫وبســؤالها عــن مــكان إقامــة املدعــى عليــه أجابــت بقولهــا إن املدعــى‬\n\n                                                                                       ‫‪80‬‬\n\f     ‫عليــه يســكن يف املنطقــة الشــرقية باجلبيــل ويعمــل يف القــوات البحريــة‬\n     ‫ورقــم جوالــه ‪ ...‬هكــذا أجابــت لذلــك جــرى إفهــام املدعيــة باملــادة‬\n     ‫رقــم ‪/10/34‬ه ـ مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وبناء‬\n     ‫علــى هــذه املــادة فقــد اســتخلفت رئيــس محكمــة اجلبيــل أو مــن ينيبــه‬\n     ‫مــن القضــاة يف ســماع جــواب املدعــى عليــه وإبالغــه باحلضــور يف املوعــد‬\n     ‫القــادم للجلســة يف يــوم األحــد املوافــق ‪1433/5/2‬ه ـ الســاعة العاشــرة‬\n     ‫والنصــف وبــاهلل التوفيــق ثــم يف يــوم ا ألحــد ‪1433/5/2‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 11.10‬وقــد حضــرت املدعيــة ووالدهــا مــن بدايــة املوعد‬\n     ‫احملــدد وحتــى اآلن لــم يحضــر املدعــى عليــه وقــد وردنــا مــن محكمــة‬\n     ‫اجلبيــل بخطــاب فضيلــة رئيســها رقــم ‪ 33339961‬يف ‪1433/3/16‬هـ ـ‬\n     ‫صــوره مصدقــه مبــا مت ضبطــه لــدى فضيلــة املــازم القضائــي باملكتــب‬\n     ‫القضائــي الثانــي لديهــم الشــيخ ‪ ...‬بعــدد ‪ 33339961‬وفيــه إثبــات‬\n     ‫حضــور املدعــى عليــه أصالــه ‪ ...‬الســعودي اجلنســية بالســجل املدنــي‬\n     ‫رقــم ‪ ...‬ثــم بعــد إفهامــه بالدعــوى جوابــه عنهــا ونصــه ( أجــاب قائــا‬\n     ‫مــا ذكرتــه املدعيــة مــن دعواهــا مــن الــزواج واملهــر والدخــول فكلــه‬\n     ‫صحيــح ومــا ذكرتــه مــن بقائهــا عنــدي بعــد دخولــي بهــا مــدة شــهرين‬\n     ‫ونصــف فغيــر صحيــح والصحيــح أنهــا بقيــت عنــدي مــدة أربعــة اشــهر‬\n     ‫وقــد ذهبــت الــى بيــت أهلهــا بشــهر ذي القعــدة مــن عــام ‪1431‬ه ـ وليــس‬\n     ‫كمــا ذكــرت املدعيــة مــن أنــي ذهبــت بهــا إلــى بيــت أهلهــا بتاريــخ‬\n     ‫‪1431/10/15‬هـ ـ ومــا ذكرتــه مــن أننــي لــم أقــم بإرجاعهــا فغيــر‬\n     ‫صحيــح بــل قمــت بعــدة محــاوالت إلرجاعهــا ولكــن والدهــا ذكــر لــي‬\n     ‫مــرة أنهــا رفضــت الرجــوع إلــي ومــرة أخــرى بقولــه ال مانــع لديــه مــن‬\n     ‫إرجاعهــا ولكــن بشــرط أن ادفــع لهــا مصــروف نفقتهــا املــدة املاضيــة‬\n\n\n‫‪81‬‬\n\f‫ومــا ذكرتــه املدعيــة مــن عــدم النفقــة عليهــا مــن حــن ذهبــت إلــى بيــت‬\n‫أهلهــا حتــى اليــوم فصحيــح فهــي تركــت بيتــي ورفضــت الرجــوع إلــي‬\n‫وأمــا عــن طلــب املدعــى عليهــا بــان ادفــع لهــا نفقتهــا املاضيــة واملســتقبلية‬\n‫فلــن ادفــع لهــا فوالدهــا قــد منعهــا عنــي وكونهــا رفضــت الرجــوع‬\n‫إلــي) ثــم رصــد إبالغــه مبوعــد هــذه اجللســة ولعــدم حضــوره أو تقدميــه‬\n‫لعــذر لغيابــه لــذا قررنــا اســتكمال نظــر القضيــة غيابي ـ ًا ضــد املدعــى‬\n‫عليــه وعليــه أمــرت ببعــث املعاملــة لقســم اخلبــراء لتقديــر نفقــة املدعيــة‬\n‫الشــهرية ولــو بــدون حضــور املدعــى عليــه وبطلــب الصــك الصــادر‬\n‫ســابق ًا بخصــوص االنقيــاد ابرزتــه لنــا وعليــه رفعــت اجللســة الــى الســاعة‬\n‫احلاديــة عشــرة والنصــف مــن يــوم الثالثــاء املوافــق ‪1433/7/15‬ه ـ‬\n‫كمــا امــرت بالكتابــة حملكمــة اجلبيــل إلبــاغ املدعــى عليــه مبوعــد‬\n‫اجللســة القادمــة ابــراء للذمــة وبــاهلل التوفيــق ثــم يف جلســة أخــرى لــدي‬\n‫أنــا ‪ ...‬املــازم القضائــي لــدى فضيلــة الشــيخ ‪ ...‬القاضــي يف احملكمــة‬\n‫العامــة بالريــاض واملكلــف مــن فضيلتــه بنظــر هــذه الدعــوى ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1433/07/15‬ه ـ افتتحــت اجللســة الســاعة وفيهــا‬\n‫حضــرت املدعيــة ووالدهــا ولــم يحضــر املدعــى عليــه وقــد وردنــا مــن‬\n‫مكتــب الصلــح قرارهــم وفيــه تقديرهــم النفقــة بثمامنائــة ريــال شــهريا‬\n‫موقعــا عليــه مــن قبــل مديــر مكتــب الصلــح ‪ ...‬وعضــوي املكتــب ‪ ...‬و‪...‬‬\n‫فســألت املدعيــة هــل أنــت مســتعدة باحللــف علــى أنــك لــم تســتلمي مــن‬\n‫املدعــى عليــه أي نفقــة مــن تاريــخ إخراجــك مــن املنــزل فقالــت نعــم ثــم‬\n‫أذنــت لهــا فتلفظــت قائلــة واهلل العظيــم إن املدعــى عليــه لــم ينفــق علــي‬\n‫ولــم أســتلم منــه شــيئا مــن تاريــخ إخراجــي مــن املنــزل ‪1431/10/15‬ه ـ‬\n‫واهلل العظيــم هكــذا حلفــت ورفعــت اجللســة ثــم يف يــوم األربعــاء املوافــق‬\n\n\n                                                                                         ‫‪82‬‬\n\f     ‫‪ 1433/07/16‬هـ افتتحت اجللســة الســاعة احلادية عشــرة وفيها حضرت‬\n     ‫املدعيــة ووالدهــا ولــم يحضــر املدعــى عليــه وقــررت املدعيــة بقولهــا إن‬\n     ‫املدعــى عليــه طلقنــي يف تاريــخ ‪1433/05/23‬ه ـ لــذا فإننــي أطلــب إلــزام‬\n     ‫املدعــى عليــه بنفقتــي املاضيــة واملســتقبلية إلــى انتهــاء عدتــي والتــي‬\n     ‫تنتهــي يف آخــر شــهر شــعبان واحتياطــا أجعلهــا يف ‪1433/08/23‬ه ـ‬\n     ‫وأطلــب النفقــة املســتقبلية إلــى ‪1433/08/15‬ه ـ وأن تكون يف حســابي‬\n     ‫يف بنــك ‪ ...‬ورقمــه ‪ ...‬ثــم أبــرزت الصــك الصــادر مــن احملكمــة اجلزئيــة‬\n     ‫للضمــان واألنكحــة بالريــاض رقم ‪ 2/99/19‬وتاريــخ ‪1433/05/23‬هـ‬\n     ‫وباالطــاع عليــه وجــد كمــا تقــول املدعيــة وبعــرض جــواب املدعــى عليــه‬\n     ‫الــوارد يف االســتخالف علــى املدعيــة قالــت غيــر صحيــح أنــه أخرجني يف‬\n     ‫شــهر ذي القعــدة بــل الصحيــح أنــه يف شــهر شــوال مــن عــام ‪1431‬ه ـ ومــا‬\n     ‫ذكــره مــن أننــي رفضــت االنقيــاد لــه فصحيــح ألنــه لــم يوفــر الشــروط‬\n     ‫التــي اشــترطتها يف عقــد النــكاح هكــذا قــررت فســألتها البينــة علــى‬\n     ‫وقــت إخراجهــا مــن املنــزل وعلــى أن املدعــى عليــه لــم يلتــزم بالشــروط‬\n     ‫فأبــرزت الصــك الصــادر مــن هــذا املكتــب برقــم ‪ 32356169‬وتاريــخ‬\n     ‫‪1433/12/19‬ه ـ وقالــت فيــه هــذا اإلقــرار مــن املدعــى عليــه يف اجللســة‬\n     ‫التــي بتاريــخ ‪1432/06/05‬ه ـ ونصــه ‪ ( :‬وذهبــت بهــا إلــى أهلهــا يف‬\n     ‫شــهر شــوال املاضــي ) كمــا أن فيــه احلكــم بصــرف النظــر عــن دعــوى‬\n     ‫املدعــى عليــه لعــدم التزامــه بشــروط عقــد النــكاح هكــذا قــررت‬\n     ‫وباالطــاع علــى الصــك وجــد كمــا تقــول املدعيــة فبنــاء علــى مــا تقــدم‬\n     ‫مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه الــوارد يف الصــك الصــادر‬\n     ‫مــن هــذا املكتــب رقــم ‪ 32356169‬وتاريــخ ‪1433/12/19‬ه ـ بأنــه‬\n     ‫ذهــب باملدعيــة إلــى أهلهــا بســبب مشــاكل بينهمــا يف شــهر شــوال مــن‬\n\n\n‫‪83‬‬\n\f‫عــام ‪1431‬ه ـ وإلقــراره الــوارد يف جــواب االســتخالف املرســل حملكمــة‬\n‫اجلبيــل بأنــه لــم يدفــع للمدعيــة شــيئا إلــى تاريــخ إقــراره ‪1433/03/13‬هـ‬\n‫وحللــف املدعيــة علــى أنهــا لــم تســتلم مــن املدعــى عليــه شــيئا مــن تاريــخ‬\n‫إخراجهــا إلــى اليــوم وبنــاء علــى الصــك الســابق احملكــوم فيــه بصــرف‬\n‫النظــر عــن دعــوى املدعــى عليــه وهــي دعــوى طلــب انقيــاد زوجتــه املدعية‬\n‫لعــدم التزامــه بشــروط عقــد النــكاح وملــا أشــار بــه مكتــب الصلــح يف‬\n‫هــذا احملكمــة مــن تقديــر نفقــة املدعيــة بثمامنائــة ريــال شــهريا ولقولــه‬\n‫تعالــى ‪ ( :‬الرجــال قوامــون علــى النســاء مبــا فضــل اهلل بعضهــم علــى‬\n‫بعــض ومبــا أنفقــوا مــن أموالهــم ) وقولــه ‪ ( :‬لينفــق ذو ســعة مــن ســعته‬\n‫ومــن قــدر عليــه رزقــه فلينفــق ممــا آتــاه اهلل ) وملــا أخرجــه مســلم مــن‬\n‫قــول الرســول صلــى اهلل عليــه وســلم المــرأة أبــي ســفيان رضــي اهلل عنــه‬\n‫‪ (( :‬خــذي مــن مالــه باملعــروف مــا يكفيــك ويكفــى بنيــك )) وإلجمــاع‬\n‫العلمــاء علــى أن الــزوج يجــب عليــه أن ينفــق علــى زوجتــه باملعــروف وملــا‬\n‫ترجــح مــن أقــوال العلمــاء أن نفقــة الزوجــة ال تســقط مبضــي الزمــان‬\n‫بــل تعــد دينــا علــى الــزوج ألنــه مــال يجــب علــى ســبيل البــدل يف عقــد‬\n‫معاوضــة جــزاء االحتبــاس فــا تســقط مبضــي الزمــان فبنــاء علــى‬\n‫جميــع مــا تقــدم فقــد حكمــت علــى املدعــى عليــه ‪ ...‬يف حــال غيابــه‬\n‫حكمــا حضوريــا بنــاء علــى املادتــن ‪ 1/55‬و ‪ 4/56‬مــن نظــام املرافعــات‬\n‫الشــرعية لتبلــغ لشــخصه بدفــع النفقــة املاضيــة للمدعيــة ‪ ...‬مــن تاريــخ‬\n‫إخراجهــا مــن املنــزل منتصــف شــهر شــوال عــام ‪1431‬ه ـ إلــى تاريــخ‬\n‫اليــوم وقدرهــا ســتة عشــر ألفــا وثمامنائــة ريــال كمــا حكمــت بإلزامــه‬\n‫بدفــع نفقتهــا املســتقبلية إلــى تاريــخ ‪1433/08/15‬ه ـ وقدرهــا ثمامنائــة‬\n‫ريــال وأن يــودع املبلــغ يف حســاب املدعيــة يف بنــك ‪ ...‬رقــم ‪ ...‬وبعــرض‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫احلكــم علــى املدعيــة قنعــت بــه وأمــرت بإنفــاذ املادتــن ‪ 4/176‬و ‪178‬‬\n     ‫مــن نظــام املرافعــات الشــرعية بخصــوص تبليــغ املدعــى عليــه باحلكــم‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                         ‫حــرر يف ‪ 1433/07/16‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد أطلعــت علــى الالئحــة االعتراضيــة‬\n     ‫املقدمــة مــن املدعــى عليــه أصالــة املقيــدة برقــم ‪ 33/1410568‬يف‬\n     ‫‪1433/07/27‬ه ـ ولــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪1433/10/18‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬املــازم القضائــي املكلــف بعمــل‬\n     ‫املكتــب القضائــي احلــادي والثالثــن باحملكمــة العامــة بالريــاض بنــاء‬\n     ‫علــى تكليــف فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد رقــم‬\n     ‫‪ 332183178‬يف ‪1433/12/19‬ه ـ ثــم لقــد عــادت املعاملــة مــن محكمة‬\n     ‫االســتئناف وبرفقهــا قرارهــم رقم ‪ 33476307‬وتاريــخ ‪1433/12/22‬هـ‬\n     ‫وفيــه مــا نصــه ( وبدارســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫واوراق املعاملــة لوحــظ اآلتــي ‪ :‬أو ًال ‪ /‬أن فضيلتــه لــم يــدون يف الصــك‬\n     ‫وصــورة ضبطــه رقــم وتاريــخ قــرار مكتــب الصلــح حيــث ورد يف الصــك‬\n     ‫وصــورة ضبطــه قولــه ( وقــد وردنــا مــن مكتــب الصلــح قرارهــم وفيــه ‪...‬‬\n     ‫الــخ ) ثانيـ ًا ‪ /‬يوجــد ســقط يف الصــك يف نهايــة الصفحــة األولــى وبدايــة‬\n     ‫الصفحــة الثانيــة ممــا ســبب انقطــاع يف الــكالم وال بــد مــن إحلاقــه فعلــى‬\n     ‫فضيلتــه مالحظــة مــا ذكــر وإكمــال مــا يلــزم ) عليــه أجيــب أصحــاب‬\n     ‫الفضيلــة أنــه بخصــوص قــرار مكتــب الصلــح فإنــه ليــس مرقم ـ ًا وال‬\n     ‫مؤرخـ ًا أمــا الســقط الــذي يف الصــك فقــد أمــرت بإعــادة طباعــة الصــك‬\n\n\n‫‪85‬‬\n\f‫ثــم رفــع املعاملــة حملكمــة االســتئناف هــذا مــا يلــزم اإلجابــة عنــه وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                     ‫حــرر يف ‪ 1434/02/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد وردنــا خطــاب رئيــس محكمــة االســتئناف‬\n‫بالريــاض املســاعد رقــم ‪ 34541196‬يف ‪1434/4/1‬ه ـ مرفــق بــه قــرار‬\n‫دائــرة األحــوال الشــخصية ا ألولــى مبحكمــة االســتئناف بالريــاض‬\n‫رقــم ‪ 34166991‬يف ‪1434/3/21‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n‫بعــد اإلجــراء األخيــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/04/17‬ه ـ وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪ 1434/04/16‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي لــدى فضيلــة‬\n‫الشــيخ‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم‬\n‫‪ 3315262‬وتاريــخ ‪ 1433/01/05‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 3337873‬وتاريــخ ‪ 1433/01/05‬ه ـ واملكلــف مــن قبلــه بنظــر هــذه‬\n‫الدعــوى ففــي يــوم اخلميــس املوافــق‪ 1434/09/03‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬حــال‬\n‫كونــه وكيــا عــن ابنتــه ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ...‬مبوجــب الوكالــة رقــم ‪ 34607431‬وتاريــخ ‪1434/5/13‬ه ـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض والتــي تخولــه حــق‬\n‫املرافعــة واملدافعــة واإلقــرار واإلنــكار واســتالم املبالــغ بشــيك أو نقــد‬\n‫وقــرر قائــا لقــد اســتلمت كامــل املبلــغ احملكــوم بــه يف هــذه القضيــة‬\n\n\n                                                                                        ‫‪86‬‬\n\f     ‫بالصــك رقــم ‪ 33345548‬يف ‪1433/7/16‬ه ـ ومقــداره ســتة عشــر ألفـ ًا‬\n     ‫وثمامنائــة ريــال ‪ 16800‬ريــال مبوجــب الشــيك رقــم ‪ 381891‬وتاريــخ‬\n     ‫‪1434/8/28‬ه ـ املســحوب علــى مصــرف ‪ ...‬وبهــذا تكــون هــذه القضيــة‬\n     ‫منتهيــة ولإلثبــات جــرى حتريــره وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/09/03‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتمييــز‬\n     ‫قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف بالرياض‬\n     ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n     ‫املســاعد برقــم ‪ 34/56620‬وتاريــخ ‪1434/2/27‬ه ـ املرفــق بهــا الصــك‬\n     ‫الصــادر مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ‪ ........‬املســجل‬\n     ‫برقــم ‪ ...‬وتاريــخ ‪1433/7/16‬ه ـ اخلــاص بدعــوى ‪ ...‬ضــد ‪ ...‬بشــأن نفقــة‪،‬‬\n     ‫وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n     ‫وحيــث ســبقت دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n     ‫علــى الصــك وصــورة ضبطــه بتاريــخ ‪1434/2/17‬ه ـ بنــاء علــى قــرار‬\n     ‫الدائــرة رقــم ‪ 33476307‬وتاريــخ ‪1433/12/22‬ه ـ لــم يظهــر مــا يوجــب‬\n     ‫االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                                ‫وســلم ‪.‬‬\n\n\n\n\n‫‪87‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":78,"source_page_end":87,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3fb9b13c4b98f41362056b370abbb47273f98931158b9d44e7b3efd116900ccd","normalized_text_hash":"3723bfc8356152bf2a31a1c93ba428970536448622f201a138e07dd2ba7eeaba","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p78-33345548"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d3343d2e-cda7-5614-b063-318126cf290e","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة زوجة بنفقتها ونفقة ابنتها املاضية واملستقبلية -تقدير النفقة املاضية واملستقبلية عن طريق قسم اخلبراء - النفقة بنية الرجوع -مطالبة باستخراج تبليغ والدة وشهادة مياد -مطالبة بإضافة مولود يف دفتر العائلة -حلف اليمن بنية الرجوع على املدعى عليه مبا انفقته على االبنة -حكم بتسليم نفقة ماضية ونفقة مستقبلية -حكم باستخراج تبليغ والدة وشهادة مياد -احلكم بإضافة مولود يف دفتر العائلة -صرف","document_number":"3440861","case_number":"33245651","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/18","year":"1434","subject":"نفقة -مطالبة زوجة بنفقتها ونفقة ابنتها املاضية واملستقبلية -تقدير النفقة املاضية واملستقبلية عن طريق قسم اخلبراء - النفقة بنية الرجوع -مطالبة باستخراج تبليغ والدة وشهادة مياد -مطالبة بإضافة مولود يف دفتر العائلة -حلف اليمن بنية الرجوع على املدعى عليه مبا انفقته على االبنة -حكم بتسليم نفقة ماضية ونفقة مستقبلية -حكم باستخراج تبليغ والدة وشهادة مياد -احلكم بإضافة مولود يف دفتر العائلة -صرف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/18 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3440861 :‬‬\n                   ‫َر ْق ُم الدعوى‪33245651 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34201329‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬مطالبــة زوجــة بنفقتهــا ونفقــة ابنتهــا املاضيــة واملســتقبلية‬\n‫‪ -‬تقديــر النفقــة املاضيــة واملســتقبلية عــن طريــق قســم اخلبــراء ‪-‬‬\n‫النفقــة بنيــة الرجــوع ‪ -‬مطالبــة باســتخراج تبليــغ والدة وشــهادة‬\n‫ميــاد ‪ -‬مطالبــة بإضافــة مولــود يف دفتــر العائلــة ‪ -‬حلــف اليمــن‬\n‫بنيــة الرجــوع علــى املدعــى عليــه مبــا انفقتــه علــى االبنــة ‪ -‬حكــم‬\n‫بتســليم نفقــة ماضيــة ونفقــة مســتقبلية ‪ -‬حكــم باســتخراج تبليــغ‬\n‫والدة وشــهادة ميــاد ‪ -‬احلكــم بإضافــة مولــود يف دفتــر العائلــة ‪ -‬صــرف‬\n‫النظــر عــن طلــب الزوجــة نفقتهــا املاضيــة لنشــوزها ‪ -‬تنــازل عــن نفقــة‬\n                                                                ‫محكــوم بهــا‪.‬‬\n\n\n\n\n‫ذكــر البهوتــى يف شــرح املنتهــى ‪ « 242/3‬ولــو امتنــع منهــا أي النفقــة‬\n‫زوج أو قريــب فأنفــق عليهمــا غيــره رجــع منفــق علــى زوج أو قريــب بنيــة‬\n‫رجــوع ألن االمتنــاع قــد يكــون لضعــف مــن وجبــت لــه وقــوة مــن وجبــت‬\n                  ‫عليــه فلــو لــم ميلــك املنفــق الرجــوع لضــاع الضعيــف»‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه زوجها ذهب بها إلــى بيت أهلها يف‬\n‫‪1431/1 1/5‬ه ـ وتركهــا عندهــم حتــى تاريــخ إقامــة الدعــوى ولــم ينفــق‬\n\n                                                                                 ‫‪38‬‬\n\f     ‫عليهــا خــال هــذه املــدة كمــا أنهــا رزقــت منــه ببنــت يف ‪1432/7/3‬ه ـ‬\n     ‫ولــم ينفــق عليهــا مــن والدتهــا إلــى وقــت إقامــة الدعــوى وإنهــا أنفقــت‬\n     ‫عليهــا شــهريا ألــف ريــال ناويــة الرجــوع علــى املدعــى عليــه كمــا أن‬\n     ‫املدعــى عليــه لــم يســتخرج تبليــغ والدة وال شــهادة ميــاد ولــم يضيــف‬\n     ‫ابنتــه يف كــرت العائلــة وطالبــت املدعيــة إلــزام املدعــى عليــه بتقديــر‬\n     ‫نفقــة شــهرية لهــا والبنتهــا وإلــزام املدعــى عليه بــأن يســلمها نفقتها للمدة‬\n     ‫املاضيــة واملســتقبلية وان يســلمها مــا أنفقتــه علــى ابنتهــا املــدة املاضيــة‬\n     ‫وان يســتخرج للبنــت تبليــغ والدة وشــهادة ميــاد وان يضيــف البنــت يف‬\n     ‫كــرت العائلــة‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر انــه‬\n     ‫لــم يســتخرج تبليــغ والدة ألنــه ال يعــرف أيــن ولــدت املدعيــة كمــا أن‬\n     ‫املدعيــة ال تســتحق النفقــة ألنهــا ناشــز‪ ،‬ثبــت لــدى ناظــر القضيــة بــأن‬\n     ‫املدعيــة ناشــز‪ ،‬مت تقديــر نفقــة للبنــت مــن قبــل قســم اخلبــراء ســتمائة‬\n     ‫ريــال شــهري ًا ‪ ،‬جــرى عــرض اليمــن علــى املدعيــة إنهــا كانــت تنفــق‬\n     ‫علــى البيــت بنيــة الرجــوع فحلفــت علــى ذلــك‪ ،‬قــرر ناظــر القضيــة‬\n     ‫لألســباب املرصــودة يف نــص القضيــة باحلكــم علــى املدعــى عليــه إن‬\n     ‫يســلم نفقــة شــهرية البنتــه مبلغــا قــدره ســتمائة ريــال مــن ‪1434/2/3‬ه ـ‬\n     ‫وتســليم النفقــة املاضيــة مبلغــا قــدره احــد عشــر ألفـ ًا وأربعمائــة ريــال مــن‬\n     ‫والدتهــا وحتــى ‪1434/2/2‬هــ‪ ،‬وإن يســتخرج تبلــغ والدة البنتــه وشــهادة‬\n     ‫ميــاد وان يضيفهــا إلــى دفتــر العائلــة‪ ،‬مت تصديــق احلكــم من محكمة‬\n     ‫االســتئناف بالريــاض‪ ،‬حضــرت املدعيــة وتنازلــت عــن مبلــغ قــدره عشــرة‬\n                           ‫اآلف ريــال مــن النفقــة احملكــوم بهــا ســابقا البنتهــا ‪.‬‬\n\n\n\n\n‫‪39‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم االثنــن املوافــق ‪1433/08/26‬ه ـ حضــرت‪).....( /‬‬\n‫الســجل املدنــي رقــم (‪ ).....‬واملعــرف بهــا مــن قبــل والدهــا‪ ).....(/‬حامــل‬\n‫الســجل املدنــي رقــم(‪ ،:).....‬ولــم يحضــر املدعــى عليــه (‪ ،).....‬والــذي‬\n‫جــرى تبليغــه مبوعــد هــذه اجللســة لشــخصه عــن طريــق مرجعــه مبوجــب‬\n‫خطــاب مديــر إدارة شــؤون املوظفــن مبدينــة ‪ ...‬برقــم‪ ... :‬يف ‪ ...‬املرفــق‬\n‫بــه منــوذج التبليــغ موقعــا مــن املدعــى عليــه؛ لــذا قــررت ســماع الدعــوى‬\n‫غيابيــا‪ ،‬وقــد ادعــت املدعيــة قائلــة يف دعواهــا‪ :‬إن املدعــى عليــه زوجــي‪،‬‬\n‫وقــد ذهــب بــي إلــى بيــت أهلــي بتاريــخ ‪1431/11/5‬ه ـ وتركنــي عندهم‬\n‫حتــى اآلن‪ ،‬ولــم ينفــق علــي خــال تلــك املــدة كمــا أننــي رزقت منــه ببنت‬\n‫يف ‪1432/7/3‬ه ـ ولــم ينفــق عليهــا مــن والدتهــا إلــى وقتنــا احلاضــر‪ ،‬وقــد‬\n‫أنفقــت عليهــا شــهريا مــا ال يقــل عــن ألــف ريــال ناويــة الرجــوع بهــا علــى‬\n‫املدعــى عليــه‪ ،‬كمــا أنــه لــم يســتخرج لهــا تبليــغ والدة وال شــهادة ميــاد‬\n‫ولــم يضفهــا يف دفتــر عائلتــه‪ ،‬وأطلــب تقديــر نفقــة شــهرية لــي والبنتــي‪،‬‬\n‫وإلــزام املدعــى عليــه بــأن يســلمني نفقتــي للمــدة املاضيــة واملســتقبلية‪،‬‬\n‫وأن يســلمني مــا أنفقتــه علــى ابنتــه للمــدة املاضيــة‪ ،‬وأن يســلمني نفقتهــا‬\n‫للمــدة املســتقبلية وأن يســتخرج لهــا تبليــغ والدة وشــهادة ميــاد‪ ،‬وأن‬\n‫يضيفهــا يف دفتــر عائلتــه‪ ،‬هــذه دعــواي‪ .‬فســألت املدعيــة البينــة علــى‬\n‫دعواهــا فقالــت‪ :‬نعــم‪ ،‬ووعــدت بإحضارهــا يف اجللســة القادمــة ‪ .‬ويف‬\n‫يــوم األحــد املوافق‪1433/11/21‬ه ـ حضــرت املدعيــة املعــرف بهــا مــن‬\n‫قبــل والدهــا ‪ ،‬كمــا حضــر املدعــى عليــه حامــل الســجل املدنــي رقــم‬\n\n                                                                                       ‫‪40‬‬\n\f     ‫ومتــت تــاوة الدعــوى عليــه وطلبــت منــه اإلجابــة عنهــا فقــال ‪ :‬مــا ذكرتــه‬\n     ‫املدعيــة مــن أننــي ذهبــت بهــا إلــى بيــت أهلهــا بتاريــخ ‪1431/11/5‬ه ـ‬\n     ‫وأنهــا عندهــم حتــى اآلن وأننــي لــم أنفــق عليهــا خــال تلــك املــدة وأننــي‬\n     ‫رزقــت منهــا ببنــت يف ‪1432/7/3‬ه ـ وأننــي لــم أنفــق عليهــا مــن والدتهــا‬\n     ‫إلــى وقتنــا احلاضــر وأننــي لــم اســتخرج لهــا تبليــغ والدة وال شــهادة ميــاد‬\n     ‫وأننــي لــم أضفهــا يف دفتــر عائلتــي فصحيــح ولــم اســتخرج تبليــغ الــوالدة‬\n     ‫ألنــي ال أعلــم يف أي مستشــفى ولــدت ومــا ذكرتــه املدعيــة مــن أننــي‬\n     ‫تركتهــا عنــد اهلهــا فغيــر صحيــح والصحيــح أنهــا هــي التــي رفضــت‬\n     ‫العــودة لــي فــا تســتحق النفقــة لكونهــا ناشــزا هكــذا أجــاب ‪،‬‬\n     ‫وبعــرض ذلــك علــى املدعيــة قالــت ‪ :‬إننــي رفضــت العــودة للمدعــى عليــه‬\n     ‫يف ذلــك الوقــت ألننــي كنــت حامــا وكنــت أتوحــم واآلن لــن أرجــع لــه‬\n     ‫لكونــه قــد أهاننــي هكــذا أجابــت ‪ ،‬فقــررت الكتابــة لقســم اخلبــراء‬\n     ‫لتحديــد النفقــة الشــهرية البنــة الطرفــن للمــدة املاضيــة واملســتقبلية‪.‬‬\n     ‫ويف يــوم االثنــن املوافق‪1434/02/18‬ه ـ حضــرت املدعيــة واملعــرف بهــا‬\n     ‫مــن قبــل أبيهــا واملدعــى عليــه ‪ ،‬فســألت املدعيــة يف أي مستشــفى ولــدت‬\n     ‫ابنتهــا‪ ،‬فقالــت‪ :‬يف مستشــفى (‪ ).....‬اجلامعــي ‪،‬هكــذا أجابــت ‪،‬وقــد‬\n     ‫وردنــي قــرار مكتــب الصلــح رقــم‪ 61:‬يف ‪1434/1/20‬ه ـ واملتضمــن‬\n     ‫تقديــر نفقــة الطفلــة الشــهرية بســتمائة ريال‪،‬فجــرى عــرض اليمــن‬\n     ‫علــى املدعيــة أنهــا أنفقــت علــى ابنتهــا مــن املدعــى عليــه مــاال يقــل علــى‬\n     ‫ســتمائة ريــال شــهريا مــن تاريــخ والدتهــا إلــى وقتنــا احلاضــر بنيــة الرجــوع‬\n     ‫علــى املدعــى عليه‪،‬فاســتعدت ببذلهــا ‪،‬ثــم حلفــت قائلــة (واهلل الــذي‬\n     ‫ال إلــه إال هــو إننــي قــد أنفقــت علــى ابنتــي مــن املدعــى عليــه مــن تاريــخ‬\n     ‫والدتهــا يف ‪1432/7/3‬ه ـ إلــى وقتنــا احلاضــر مــاال يقــل عن ســتمائة ريال‬\n\n\n‫‪41‬‬\n\f‫شــهريا ناويــة الرجــوع مبــا أنفقــت علــى املدعــى عليه)هكــذا حلفــت‪،‬‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعيــة تعتبــر ناشــزا‬\n‫خــال الفتــرة التــي تطالــب بالنفقــة لهــا حيث أقــرت بأنها رفضــت العودة‬\n‫إلــى املدعــى عليــه عندمــا كانــت حامــا وأنهــا اآلن لــن ترجــع إليــه وبنــاء‬\n‫علــى قــرار قســم الصلــح وميــن املدعيــة وبنــاء علــى مــا قــرره أهــل العلــم‬\n‫حيــث ذكــر البهوتــي يف شــرح املنتهــى (‪ )242/3‬مانصــه (ولــو امتنــع‬\n‫منهــا أي النفقــة زوج أو قريــب فأنفــق عليهمــا غيــره رجــع منفــق علــى‬\n‫زوجــة أو قريــب بنيــة رجــوع ألن االمتنــاع قــد يكــون لضعــف مــن وجبــت‬\n‫لــه وقــوة مــن وجبــت عليــه فلــو لــم ميلــك املنفــق الرجــوع لضــاع الضعيــف)‬\n‫لــذا فقــد حكمــت علــى املدعــى عليــه بــأن يســلم للمدعيــة أحــد عشــر‬\n‫ألفــا وأربعمائــة ريــال عــن مــا أنفقتــه علــى ابنتــه منهــا مــن تاريــخ والدتهــا‬\n‫إلــى تاريخ‪1434/2/2‬ه ـ وأن يســلم املدعــى عليــه للمدعيــة نفقــة شــهرية‬\n‫البنتــه منهــا قدرهــا ســتمائة ريــال ابتــداء مــن ‪1434/2/3‬ه ـ ‪،‬وأن‬\n‫يســتخرج البنتــه املذكــورة تبليــغ والدة وشــهادة ميــاد وأن يضيفهــا يف‬\n‫دفتــر عائلتــه ورددت دعــوى املدعيــة يف املطالبــة مبــا زاد علــى النفقــة‬\n‫احملكــوم بهــا البنتهــا ويف املطالبــة بنفقتهــا وأخليــت ســبيل املدعــى عليــه‬\n‫مــن ذلــك وبذلــك حكمــت‪ ،‬وبعــرض احلكــم علــى الطرفــن قنعــت بــه‬\n‫املدعيــة ولــم يقنــع بــه املدعــى عليــه وطلــب االســتئناف فأجبتــه لطلبــه‬\n‫وقــررت تســليمه صــورة مــن صــك احلكــم حــاال لتقــدمي معارضتــه عليــه‬\n‫خــال مــدة ال تتجــاوز ثالثــن يومــا فــإن تأخــر عــن ذلــك ســقط حقــه‬\n‫يف تقــدمي الالئحــة االعتراضيــة واكتســب احلكــم القطعيــة‪ .‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪ 1434/02/18‬ه ـ ‪.‬‬\n\n\n                                                                                           ‫‪42‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ففــي يوم األحد املوافق ‪1434/05/19‬هـ افتتحت‬\n     ‫اجللســة الســاعة ‪ 09:45‬وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n     ‫بالريــاض وقــد همــش علــى ظهــر الصــك مبــا نصــه (تظهيــرات الدائــرة‬\n     ‫الثانيــة لألحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف مبنطقــة‬\n     ‫الريــاض ‪ ،‬احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n     ‫‪ 3440861‬وتاريــخ ‪1434/02/18‬ه ـ الصــادر مــن فضيلــة الشــيخ (‪).....‬‬\n     ‫وأصدرنــا القــرار رقــم ‪ 34201329‬وتاريــخ ‪1434/04/29‬ه ـ املتضمــن‬\n     ‫املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬عضــو ختمــه وتوقيعــه عضــو‬\n     ‫ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه ‪ ) .‬وكان ختــام هــذه‬\n     ‫اجللســة الســاعة ‪ 10:00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا‬\n                 ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/05/19‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ،‬فلــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامــة‬\n     ‫بالريــاض خلف ـ ًا لفضيلــة الشــيخ النتقالــه مــن هــذه احملكمــة ويف يــوم‬\n     ‫االثنــن املوافــق ‪1434/12/02‬ه ـ افتتحــت اجللســة الســاعة الثامنــة‬\n     ‫والربــع ‪ ،‬وبنــاء علــى الصــك الصــادر منــا برقــم ‪ 34368950‬يف‬\n     ‫‪1434/11/25‬ه ـ املتضمــن تنــازل املدعيــة ‪ ).....(/‬عــن مبلــغ قــدره عشــرة‬\n     ‫آالف ريــال مــن النفقــة احملكــوم بهــا لهــا نفقــة ماضيــة البنتهــا ‪ ،‬ولكــي‬\n     ‫ال يخفــى جــرى حتريــره وأمــرت بالتهميــش بذلــك علــى الصــك وســجله ‪،‬‬\n     ‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                       ‫‪ .‬حــرر يف ‪1434/12/02‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n     ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n     ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n\n\n‫‪43‬‬\n\f‫بالريــاض املســاعد برقــم ‪ 33658319‬وتاريــخ ‪1434/4/9‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ (‪).....‬‬\n‫املســجل برقــم ‪ 3440861‬وتاريــخ ‪1434/2/18‬ه ـ اخلــاص بدعــوى (‪).....‬‬\n‫ضــد (‪ ،).....‬يف قضيــة نفقــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم‪،‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪44‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":38,"source_page_end":44,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"375fc55cdf668a960a4497a79571b6f579857973c2984d6db42870ce36a0e996","normalized_text_hash":"4eb09d9a577607dff01e0f158c36c705a1d812c834fd2e2677a70d657682b5ab","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p38-3440861"},{"id":"69813516-d56b-5529-b1ca-0203a5d8eeb6","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة أوالد -املطالبة بالنفقة املاضية -املطالبة بالنفقة املستقبلية -املطالبة بتسليم شهادة املياد ودفتر العائلة -غياب املدعى عليه يعتبر نكو ال عن اجلواب -القول قول الغارم بيمينه- حلف الزوجة اليمني -تقدير النفقة عن طريق قسم اخلبراء -احلكم على األب بدفع نفقة أوالده املاضية واملستقبلية -احلكم على األب بتسليم األم األوراق الثبوتية ألوالدها الذين يف حضانتها -شمول احلكم بالنفقة وإخراج شهادة املياد وإسقاط املدعية من سجل","document_number":"32191315","case_number":"317549","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/8/4","year":"1434","subject":"نفقة -نفقة أوالد -املطالبة بالنفقة املاضية -املطالبة بالنفقة املستقبلية -املطالبة بتسليم شهادة املياد ودفتر العائلة -غياب املدعى عليه يعتبر نكو ال عن اجلواب -القول قول الغارم بيمينه- حلف الزوجة اليمني -تقدير النفقة عن طريق قسم اخلبراء -احلكم على األب بدفع نفقة أوالده املاضية واملستقبلية -احلكم على األب بتسليم األم األوراق الثبوتية ألوالدها الذين يف حضانتها -شمول احلكم بالنفقة وإخراج شهادة املياد وإسقاط املدعية من سجل","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1432/8/4 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪32191315 :‬‬\n                          ‫َر ْق ُم الدعوى‪317549 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34313140‬تاريخه‪1434/9/6 :‬هـ‬\n\n\n\n     ‫نفقــة ‪ -‬نفقــة أوالد‪ -‬املطالبــة بالنفقــة املاضيــة ‪ -‬املطالبــة بالنفقــة‬\n     ‫املســتقبلية‪ -‬املطالبــة بتســليم شــهادة امليــاد ودفتــر العائلــة‪ -‬غيــاب‬\n     ‫املدعــى عليــه يعتبــر نكــو ًال عــن اجلــواب‪ -‬القــول قــول الغــارم بيمينــه‪-‬‬\n     ‫حلف الزوجة اليمني‪ -‬تقدير النفقة عن طريق قسم اخلبراء‪ -‬احلكم‬\n     ‫علــى األب بدفــع نفقــة أوالده املاضيــة واملســتقبلية‪ -‬احلكــم علــى األب‬\n     ‫بتســليم األم األوراق الثبوتيــة ألوالدهــا الذيــن يف حضانتهــا‪ -‬شــمول‬\n     ‫احلكــم بالنفقــة وإخــراج شــهادة امليــاد وإســقاط املدعيــة مــن ســجل‬\n                                         ‫أســرة املدعــى عليــه بالتنفيــذ املعجــل‪.‬‬\n\n\n\n\n     ‫‪ -1‬املــادة ‪ 2/203‬مــن نظــام املرافقــات الشــرعية ولوائحــه التنفيذيــة‬\n               ‫املتضمــن أن غيــاب املدعــى عليــه يعتبــر نكــو ًال عــن اجلــواب‪.‬‬\n                                             ‫‪ -2‬قاعدة القول قول الغارم بيمينه‪.‬‬\n                                      ‫‪ -3‬املادة ‪ 199‬من نظام املرافعات الشرعية‪.‬‬\n     ‫‪ -4‬قــال يف دليــل الطالــب ص ‪ 292‬طبعــة طيبــة (وحيــث امتنــع فيهــا‬\n     ‫زوج أو قريــب وأنفــق أجنبــي بنيــة الرجــوع رجــع) وانظــر شــرح منتهــى‬\n     ‫اإلرادات ‪ 680/5‬طبعــة الرســالة وكشــاف القنــاع ‪ 161/13‬طبعــة وزارة‬\n                                                                           ‫العــدل‪.‬‬\n\n\n‫‪45‬‬\n\f‫ادعــى املدعــي وكالــة بــأن موكلتــه منــذ شــهر ‪1430/11‬ه ـ وهــي تنفــق‬\n‫علــى أوالدهــا مــن املدعــى عليــه وهــم بنتان وابن ذكــر أعمارهم كونهم‬\n‫يعيشــون معهــا وال يزالــون‪ ،‬لــم يدفــع املدعــى عليــه مــن النفقــة ســوى‬\n‫ألــف وتســعمائة ريــال فيمــا أنفقــت موكلتــه خمســة وعشــرين ألــف ريــال‬\n‫وتنازلــت إلــى خمســة عشــر ألــف ريــال إلــى شــهر ‪1431/11‬هــ‪ ،‬طلــب‬\n‫املدعــي وكالــة إلــزام املدعــى عليــه بتعويــض موكلتــه عمــا أنفقتــه‬\n‫ســابق ًا وإلزامــه باالســتمرار يف النفقــة بألــف ريــال شــهري ًا وإلزامــه‬\n‫بتســليم شــهادة امليــاد ودفتــر العائلــة إلكمــال املعامــات الرســمية‪،‬‬\n‫ال عــن اجلــواب‬  ‫لــم يحضــر املدعــى عليــه رغــم تبليغــه لــذا عـ ّـد نــاك ً‬\n‫بنــاء علــى املــادة ‪ 2/203‬مــن نظــام املرافعــات الشــرعية‪ ،‬ورد جــواب‬\n‫قســم اخلبــراء املتضمــن تقديــر نفقــة األوالد بعــد أن وردت إفــادة مرجــع‬\n‫املدعــى عليــه مبقــدار راتبــه‪ ،‬حيــث إن املدعيــة غارمــه والقــول قــول‬\n‫الغــارم بيمينــه لــذا جــرى حتليــف املدعيــة أصالــة بعــد وعظهــا بخطــر‬\n‫اليمــن الكاذبــة علــى أن املدعــى عليــه لــم ينفــق علــى أوالده ســوى ألــف‬\n‫وســبعمائة ريــال وأنهــا أنفقــت أكثــر مــن خمســة عشــر ألــف ريــال وال‬\n‫يزالــون يف حضانتها‪،‬حلفــت املدعيــة‪ ،‬صــدر احلكــم حضوري ـ ًا بإلــزام‬\n‫املدعــى عليــه بدفــع ثالثــة وثالثــن ألــف ريــال نفقــة ألوالده مــن املدعيــة‬\n‫عــن املــدة املاضيــة وإلزامــه باإلنفــاق عليهــم ألفــي ريــال شــهري ًا وإلزامــه‬\n‫بتســليم األوراق الثبوتيــة ألوالده للمدعيــة ومنهــا شــهادات امليــاد للبنتــن‬\n‫وكــرت العائلــة مــا دامــوا يف حضانــة والدتهــم‪ ،‬قــدم املدعــى عليــه‬\n‫الئحتــه االعتراضيــة املتضمنــة وجــود اســتقطاعات مــن راتبــه‪ ،‬جــرى‬\n\n                                                                                        ‫‪46‬‬\n\f     ‫مناقشــة هــذا األمــر بحضــور الطرفــن وجــرى بعــث املعاملــة لقســم‬\n     ‫اخلبــراء لتقديــر النفقــة علــى ضــوء ذلــك‪ ،‬ورد اجلــواب مــن قســم اخلبــراء‬\n     ‫بــأن مــا جــاء يف الئحــة املدعــى عليــه ال يؤثــر ذلــك علــى تقديــر النفقــة‬\n     ‫الســابقة وتبقــى النفقــة كمــا هــي بالتقديــر الســابق‪ ،‬جــرى تســليم‬\n     ‫املدعيــة صــورة مــن كــرت العائلــة وأقــرت املدعيــة باســتالم صــورة‬\n     ‫مــن شــهادة ميــاد إحــدى البنتــن‪ ،‬رجــع القاضــي عــن احلكــم بإلــزام‬\n     ‫املدعــى عليــه بتســليم شــهادة ميــاد البنــت املذكــورة وكــرت العائلــة‬\n     ‫وأمــا بقيــة احلكــم فبحالــة و شــمول احلكــم بالنفقــة وإخــراج شــهادة‬\n     ‫ميــاد البنــت الثانيــة وإســقاط اســم املدعيــة مــن ســجل أســرة املدعــى‬\n     ‫عليــه بالتنفيــذ املعجــل بالكفالــة احلضوريــة الغراميــة بنــاء علــى املــادة‬\n     ‫‪ ،199‬مــن نظــام املرافعــات الشــرعية‪ ،‬لوحــظ علــى احلكــم ثــم صــدق‬\n                                               ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬مســاعد رئيــس احملكمــة العامــة‬\n     ‫مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة باخلــرج برقــم ‪ 317549‬وتاريــخ ‪1431/11/26‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 3129679‬وتاريــخ ‪1431/11/26‬ه ـ ففــي‬\n     ‫يــوم االربعــاء املوافــق ‪143/2/8‬ه ـ حضــر ‪ ...‬ســجله املدنــي رقــم ‪...‬‬\n     ‫بالوكالــة رقــم ‪ 510506017367‬وتاريــخ ‪1431/11/19‬ه ـ صــادرة‬\n     ‫مــن كتابــة عــدل اخلــرج عــن ‪ ...‬لــه فيهــا املطالبــة بحضانــة أوالدهــا منــه‬\n     ‫والنفقــة واملدافعــة واملرافعــة واملخاصمــة وإقامــة الدعــاوى وحضــور‬\n     ‫اجللســات وســماع الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار واحضــار‬\n\n‫‪47‬‬\n\f‫البينــات والشــهود والصلــح وطلــب اليمــن وردهــا وقبــول احلكــم ونفيــه‬\n‫واالعتــراض عليــه وطلــب متييــزه واالســتالم والتســليم ولــم يحضــر‬\n‫املدعــى عليــه ‪ ...‬ولــم يقــدم عــذرا لعــدم حضــوره مــع تبلغــه شــخصيا‬\n‫كمــا يفيــده محضــر التبليــغ املرفــق وادعــى املدعــي قائــا موكلتــي‬\n‫منــذ شــهر ‪1430/11‬ه ـ وهــي تنفــق علــى أوالدهــا مــن املدعــى عليــه‬\n‫وهــم بنــت عمرهــا ســبع ســنوات وبنــت أخــرى عمرهــا أربــع ســنوات‬\n‫وولــد اســمه ‪...‬عمــره ســنة وعشــرة أشــهر كونهــم يعيشــون معهــا يف‬\n‫بيــت أهلهــا يف اخلــرج وال يزالــون وقــد دفــع مــن النفقــة ألــف وتســعمائة‬\n‫ريــال فقــط بينمــا أنفقــت خمســة وعشــرين ألــف ريــال وتنازلــت إلــى‬\n‫خمســة عشــر الــف ريــال إلــى شــهر ‪1431/11‬ه ـ أطلــب إلزامــه تعويضهــا‬\n‫عمــا أنفقتــه ســابقا وإلزامــه باالســتمرار يف النفقــة بألــف ريــال شــهريا‬\n‫وإلزامــه بتســليم شــهادة امليــاد ودفتــر العائلــة إلكمــال املعامــات‬\n‫الرســمية هــذه دعــواي وبطلــب البينــة مــن املدعــي أبــرز صــورة ناقصــة‬\n‫للصــك الصــادر منــا برقــم ‪ 66/2/43‬وتاريــخ ‪1431/7/30‬ه ـ واملتضمــن‬\n‫دعــوى املدعيــة طلــب فســخ النــكاح مــن املدعــى عليــه وإقــراره الضمنــي‬\n‫بنكاحهــا ثــم احلكــم بفســخ النــكاح بينهمــا مقابــل عــوض وبســؤال‬\n‫املدعــي وكالــة عــن عمــل املدعــى عليــه أجــاب يعمــل يف محميــة الوعــول‬\n‫بحوطــة بنــي متيــم التابعــة للهيئــة الســعودية حلمايــة احليــاة الفطريــة وإمنائهــا‬\n‫ولديــه محــل يف اخلــرج اســمه محــل ‪ ...‬لــذا جــرى ســؤاله عــن نوعيــة‬\n‫نشــاطه فطلــب مهلــة ولالطــاع علــى ســجل الصــك والكتابــة ملرجــع‬\n‫املدعــى عليــه ملعرفــة مقــدار راتبــه جــرى رفــع اجللســة ويف جلســة أخــرى‬\n‫حضــر املدعــي بالوكالــة ‪ ...‬ولــم يحضــر املدعــى عليــه وقــد وردنــا مــن‬\n‫الهيئــة الســعودية للحيــاة الفطريــة اخلطــاب رقــم ‪1431/480‬ه ـ وتاريــخ‬\n\n\n                                                                                            ‫‪48‬‬\n\f     ‫‪1432/3/9‬ه ـ املتضمــن أن راتــب املدعــى عليــه األســاس خمســة آالف‬\n     ‫وســتمائة وخمســة وثالثــن ريــاال وبــدل غــاء املعيشــة ثمامنائــة وخمســة‬\n     ‫وأربعــن ريــاال وخمســة وعشــرين هللــة وعليــه حســميات لبنــك التســليف‬\n     ‫أربعمائــة ريــال وصــايف راتبــه خمســة آالف وخمســمائة وثالثــة وســبعني‬\n     ‫ريــاال وعشــر هلــات كمــا جــرى االطــاع علــى ســجل الصــك املرفــق‬\n     ‫صورتــه وبســؤال املدعــى وكالــة عــن نشــاط محــل املدعــى عليــه‬\n     ‫أجــاب نشــاطه بيــع طيــور وقــد أخبرنــي أنــه فتحــه للتســلية وليــس لــه‬\n     ‫دخــل يذكــر ولتقديــر النفقــة مــن أهــل اخلبــرة جــرى رفــع اجللســة ويف‬\n     ‫جلســة أخــرى حضــر املدعــى بالوكالــة وقــد وردنــا مــن قســم اخلبــراء‬\n     ‫باحملكمــة اخلطــاب رقــم ‪ 32/480319‬وتاريــخ ‪1432/5/6‬ه ـ مرفقاتــه‬\n     ‫احملضــر املعــد مــن أعضــاء القســم واملتضمــن‪ :‬وبعــد االطــاع علــى‬\n     ‫الدعــوى يــرى األعضــاء أن تكــون نفقــة األبنــاء وعددهــم ثالثــة مــن‬\n     ‫ســبعمائة ريــال شــهريا( ‪ 2100 = 700 × 3‬ريــال شــهريا ) وبتأمــل مــا‬\n     ‫تقــدم مــن الدعــوى والبينــة التــي قدمهــا املدعــي فقــد جــرى االطــاع‬\n     ‫علــى ورقــة التبليــغ املعــدة مــن محضــر احملكمــة املتضمنــة إبــاغ املدعــى‬\n     ‫عليــه شــخصيا حلضــور اجللســة يف ‪1432/2/8‬ه ـ وألن غيــاب املدعــى‬\n     ‫عليــه يعتبــر نكــوال عــن جــواب الدعــوى مثــل مــا جــاء يف املــادة ‪2/203‬‬\n     ‫مــن نظــام املرافعــات الشــرعية ولوائحــه وألن املدعيــة غارمــه والقــول‬\n     ‫قولهــا بيمينهــا لــذا جــرى افهــام وكيــل املدعيــة أن اليمــن متوجهــة‬\n     ‫علــى موكلتــه فأجــاب موكلتــي مســتعدة بذلــك لــذا جــرى رفــع اجللســة‬\n     ‫حلضورهــا ويف يــوم األحــد املوافــق ‪1432/7/17‬ه ـ فتحــت اجللســة‬\n     ‫وحضــرت املدعيــة واملعــرف بهــا مــن قبــل عمهــا ‪ ...‬بالســجل املدنــي رقــم‬\n     ‫‪...‬وبســؤال املدعيــة عــن أي شــهادات امليــاد التــي تريــد أجابــت شــهادة‬\n\n\n‫‪49‬‬\n\f‫ميــاد ‪ ...‬و‪ ......‬وبعــرض اليمــن علــى املدعيــة أجابــت أنــا مســتعدة بذلــك‬\n‫لــذا جــرى وعظهــا عــن خطــر اليمــن الكاذبــة ثــم جــرى إحالفهــا اليمــن‬\n                                                                           ‫التاليــة ‪:‬‬\n‫(واهلل العظيــم أننــي أنفقــت علــى أوالدي مــن املدعــى عليــه ‪ ...‬أكثــر مــن‬\n‫خمســة عشــر ألــف ريــال إلــى تاريــخ ‪1431/11‬ه ـ وأنــه لــم ينفــق عليهــم‬\n‫مــن شــهر ‪1430/11‬ه ـ إلــى اآلن إال ألــف وســبعمائة ريــال وال يزالــون يف‬\n‫حضانتــي وأنــا التــي أنفــق عليهــم) هكــذا أدت اليمــن وألن املدعيــة‬\n‫حلفــت اليمــن التــي طلبــت منهــا بعــد توجههــا إليهــا وملــا ســبق مــن تقديــر‬\n‫أهــل اخلبــرة لنفقــة أوالد املدعيــة واملدعــى عليــه وألن املدعيــة تطالــب‬\n‫بنفقــة ألفــي ريــال شــهريا فقــد حكمــت حضوريــا بإلــزام املدعــى عليــه‬\n‫بدفــع ثالثــة وثالثــن ألــف ريــال نفقــة ألوالده مــن املدعيــة ‪...‬و‪...‬و‪ ...‬عــن‬\n‫املــدة املاضيــة وإلزامــه باإلنفــاق عليهــم ألفــي ريــال شــهريا وإلزامــه‬\n‫بتســليم األوراق الثبوتيــة ألوالده للمدعيــة ومنهــا شــهادات امليــاد ل‪...‬‬\n‫و‪ ...‬وكــرت العائلــة مــا دامــوا يف حضانــة والدتهــم وبعــرض احلكــم علــى‬\n‫املدعيــة قنعــت بــه لــذا جــرى األمــر بإخــراج الصــك ومــن ثــم بعــث نســخة‬\n‫منــه للمدعــى عليــه لتقــدمي مــا لديــه مــن اعتــراض يف مــدة ثالثــن يومــا‬\n‫وإال ســقط حقــه يف االعتــراض واكتســب احلكــم الصفــة القطعيــة‬\n    ‫وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه حــرر يف ‪1432/7/17‬ه ـ ‪.‬‬\n‫ويف يــوم األربعــاء املوافــق ‪ 1432/11/21‬ه ـ فتحــت اجللســة بعــد أن مت‬\n‫االطــاع علــى الئحــة االعتــراض املقدمــة مــن املدعــى عليــه واملقيــدة‬\n‫باحملكمــة برقــم ‪ 32/1296263‬وتاريــخ‪ 1432/10/19‬ه ـ والتــي‬\n‫ذكــر فيهــا أن بنــك التســليف يحســم عليــه مبلــغ وقــدره عشــرون ألــف‬\n‫ريــال بواقــع أقســاط شــهرية كل قســط أربعمائــة ريــال وأن بنــك ‪.....‬‬\n\n\n                                                                                         ‫‪50‬‬\n\f     ‫يحســم مبلــغ وقــدره ســتة وثمانــون ألــف ريــال بواقــع ألــف وســبعمائة‬\n     ‫ريــال شــهريا وأن يف ذمتــه عشــرة آالف ريــال ملكتــب ‪ ...‬باخلــرج بواقــع‬\n     ‫قســط شــهري قــدره ســبعمائة ريــال وأرفــق مــع الالئحــة صــورة عقــد‬\n     ‫أجــار لــه مببلــغ عشــرة آالف ريــال يف الســنة تدفــع علــى قســطني كل‬\n     ‫ســتة أشــهر قســط وجــرى ســؤال املدعــى عليــه عــن ذلــك ومــا بقــي يف‬\n     ‫ذمتــه مــن هــذه األقســاط فأجــاب نعــم كل ذلــك صحيــح بــل قــد أخــذت‬\n     ‫قــرض إضــايف مــن بنــك ‪ .....‬وارتفــع القســط إلــى ألــف وتســعمائة وســبعة‬\n     ‫وأربعــن ريــاال وثالثــة وثالثــن هللــة وصــار املبلــغ الــذي يف ذمتــي مائــة‬\n     ‫وســتة عشــر ألــف وثمامنائــة وتســعة وثالثــن ريــاال وثمانــن هللــة وأمــا مــا‬\n     ‫بقــي مــن األقســاط فــا أدري بالضبــط هكــذا أجــاب وبعــرض ذلــك‬\n     ‫علــى املدعيــة أجابــت هــذه أشــياء ال نعلمهــا هكــذا أجابــت لــذا جــرى‬\n     ‫ســؤال املدعــى عليــه عــن رقــم حســابه يف بنــك ‪ .....‬فأجــاب حســابي يف‬\n     ‫‪ .....‬رقــم ‪ ...‬لــذا جــرى افهامــه باإلفــادة عمــا بقــي يف ذمتــه مــن األقســاط‬\n     ‫ورفعــت اجللســة مــع األمــر بالكتابــة لبنــك ‪ .....‬وبنــك التســليف لإلفــادة‬\n     ‫عمــا ذكــر املدعــي عليــه ويف جلســة اخــرى حضــرت املدعيــة وحضــر‬\n     ‫املعــرف بهــا احلاضــر ‪...‬بالســجل املدنــي رقــم ‪...‬وحضــر املدعــى عليــه وقــد‬\n     ‫جــرى ســؤال املدعــى عليــه عمــا بقــي يف ذمتــه لبنــك ‪ .....‬فأجــاب بقــي‬\n     ‫مائــه وعشــرين ألــف ريــال تقريبــا كمــا جــرى االطــاع علــى اخلطــاب‬\n     ‫الــوارد لنــا مــن البنــك الســعودي للتســليف واالدخــار فــرع اخلــرج رقــم‬\n     ‫‪ 869‬وتاريــخ ‪ 1432/12/26‬ه ـ املبنــي علــى خطابنــا رقــم ‪32/1554545‬‬\n     ‫وتاريــخ ‪ 1432/12/3‬ه ـ واملتضمــن أن املدعــى عليــه مقتــرض قــرض‬\n     ‫أســرة مببلــغ عشــرين ألــف ريــال تســدد علــى أقســاط شــهرية ومقــدار‬\n     ‫القســط أربعمائــة ريــال ســدد حتــى تاريخــه يف ‪ 1432/12/26‬ه ـ تســعة‬\n\n\n‫‪51‬‬\n\f‫عشــر ألفــا ومئتــي ريــال وبقــي ثمامنائــة ريــال وبطلــب البينــة مــن املدعــى‬\n‫عليــه علــى األقســاط التــي عليــه ملكتــب ‪ ...‬أجــاب أطلــب مهلــة ونظــرا‬\n‫لعــدم ورود إجابــة بنــك ‪ .....‬ولســماع بينــة املدعــى عليــه جــرى رفــع اجللســة‬\n‫ويف جلســة اخــرى حضــرت املدعيــة وابــرزت بطاقتهــا الشــخصية ســجلها‬\n‫املدنــي رقم‪...‬كمــا حضــر املدعــى عليــه وقــد وردنــا مــن مؤسســة النقــد‬\n‫العربــي الســعودي اخلطــاب رقــم‪754‬ن ظ ‪/‬أ ق وتاريخ‪1433/4/8‬ه ـ‬\n‫واملتضمــن افــادة مجموعــة ‪ .....‬بــان مبلــغ القــرض علــى املدعــى عليــه‬\n‫مائــة وســتة عشــر الفــا وثمامنائــة وتســعة وثالثــون ريــاال وثمانــون هللــه‬\n‫ومقــدار القســط الشــهري الــف وتســعمائة وســبعة واربعــون ريــاال‬\n‫وثالثــة وثالثــون هللــه واملبلــغ املتبقــي مائــة وتســعة االف وخمســة عشــر‬\n‫ريــاال وســبعة وثالثــون هللــه واالقســاط املتبقيــة ســتة وخمســون قســطا‬\n‫وبطلــب البينــة مــن املدعــى عليــه علــى االقســاط التــي عليــه ملكتــب‬\n‫التقســيط املريــح ابــرز ثالثــة ســندات قبــض علــى اوراق عاديــة ملؤسســة‬\n‫التقســيط املريــح للتجــارة والتقســيط مســلمه مــن املدعــى عليــه كل‬\n‫ســند بســبعمائة ريــال وقــال املدعــى عليــه ان هــذه اقســاط ســددتها‬\n‫وهــي جــزء مــن املبلــغ الــذي علــي وقــدره عشــرة االف ريــال وهــو ثمــن‬\n‫بطاقــات ‪ .....‬اشــتريتها مــن ‪...‬ثــم بعتهــا بتســعة االف أو تســعة االف‬\n‫وخمســمائة ألجــل اصــاح ســيارتي وكفيلــي ‪...‬وبســؤاله عــن تاريــخ‬\n‫العقــد ومــا بقــي مــن اقســاط اجــاب تاريــخ العقــد ال ادري والباقــي مــن‬\n‫االقســاط ال ادري لكنــي ســددت اكثــر ممــا ذكــر يف الســندات علمــا‬\n‫انــي رســمت يف عملــي يف محميــة الوعــول علــى املرتبــة اخلامســة ونقــص‬\n‫راتبــي الــى خمســة االف ومئتــن واربعــن ريــاال وبطلــب زيــادة بينــة علــى‬\n‫ذلــك طلــب مهلــه لــذا جــرى افهامــه انهــا اخــر مهلــه كمــا ابــرز ســندي‬\n\n\n                                                                                       ‫‪52‬‬\n\f     ‫قبــض علــى ورق إلدارة التربيــة والتعليــم مبنطقــة الريــاض مــدارس ‪...‬‬\n     ‫االهليــة احدهــا بتاريخ‪1432/11/20‬ه ـ ويتضمــن اســم الطالــب وهــو‬\n     ‫املدعــى عليــه ورقمــه وصفــه االولــى متوســط وصــايف املســتحق خمســة‬\n     ‫االف واملدفــوع خمســمائة ريــال ومختومــة بختــم الصنــدوق للمــدارس‬\n     ‫والثانيــة بتاريخ‪1433/2/10‬ه ـ بنفــس املعلومــات اال ان املدفــوع الفــي‬\n     ‫ريــال مــن خمســة االف ريــال والباقــي الفــن وخمســمائة ريــال وقــال‬\n     ‫املدعــى عليــه اننــي ادرس يف هــذه املــدارس ألجــل التعلــم واســتفيد يف‬\n     ‫الترقيــة يف وظيفتــي لــذا جــرى االمــر بالكتابــة ملرجــع املدعــى عليــه‬\n     ‫لإلفــادة عــن راتبــه اخيــرا كمــا جــرى ســؤال املدعــى عليــه عــن كــرت‬\n     ‫العائلــة وشــهادتي امليــاد لــ‪ ...‬و‪ ...‬فأجــاب كــرت العائلــة عندي ومســتعد‬\n     ‫بإعطائه للمدعية واما شــهادتي امليالد لـ‪ ...‬و‪ ......‬فليس عندي اال صورة‬\n     ‫لشــهادة ميــاد ‪...‬وامــا االصــل فعنــد املدعيــة اخذتهــا مــع اوراق اخــرى‬\n     ‫هكــذا اجــاب‪ .‬وبعــرض ذلــك علــى املدعيــة أجابــت ال صحــة ملــا ذكــر‬\n     ‫والــذي عنــدي اوراق ‪ ...‬فقــط لــذا جــرى ســؤال املدعــى عليــه البينــة علــى‬\n     ‫اخــذ املدعيــة لــأوراق فأجــاب صــك اخللــع وفيــه انهــا اخــذت منــي اوراق‬\n     ‫ومنهــا شــهادات امليــاد للبنــات ‪ ......‬و‪ ...‬وبســؤال املدعــى عليــه زيــادة‬\n     ‫بينــة اجــاب ليــس لــدي غيرهــا بينــة ولالطــاع علــى صــك اخللــع جــرى‬\n     ‫رفــع اجللســة ويف جلســة أخــرى حضــرت املدعيــة واملدعــى عليــه وقــد‬\n     ‫مت تأجيلهــا مــن قبــل املكتــب مــن يــوم الســبت املوافــق ‪1433/6/14‬ه ـ‬\n     ‫نظــرا لكونــي يف إجــازة اضطراريــة ويف هــذا اليــوم أحضــر املدعــى‬\n     ‫عليــه أصــل ســجل األســرة اخلــاص لــه وجــرى تصويــره وإعطــاء املدعيــة‬\n     ‫نســخة مصدقــة منــه كمــا جــرى االطــاع علــى صــورة الصــك رقــم‬\n     ‫‪ 66/2/34‬وتاريــخ ‪ 1431/7/30‬ه ـ الــذي أبــرزه املدعــى عليــه وقالــت‬\n\n\n‫‪53‬‬\n\f‫املدعيــة أصلــه عنــدي وهــو صــادر منــي وجــرى اإلطــاع عليــه ولــم جنــد‬\n‫فيــه مــا يــدل علــى أن املدعيــة أخــذت شــهادات ميــاد ‪...‬وقــال املدعــى‬\n‫عليــه أنــي ســلمت املدعيــة صــورة مــن شــهادة ميــاد ‪...‬وحصــل بهــا‬\n‫املقصــود وأجابتــه املدعيــة نعــم حصــل ذلــك لكــن كــرت العائلــة اليــزال‬\n‫اســمي مســجل معــه وقــد ذهبــت لألحــوال لتنزيلــه ودفعــت الرســم اخلاص‬\n‫لذلــك ولكــن ســجل األســرة اليــزال معــه هكــذا أجابــت ‪ .‬وقــد جــرى‬\n‫اإلطــاع علــى خطــاب مرجــع املدعــى عليــه رقــم ‪2995/2971/4/1‬‬\n‫وتاريــخ ‪ 1433/7/6‬ه ـ املبنــي علــى خطابنــا وفيــه ( أن راتبــه األســاس‬\n‫احلالــي ‪ 6720‬ريــال والصــايف بعــد حســم التأمينــات ‪ 6151.20‬ريــال وال‬\n‫توجــد عليــه حســميات لبنــك التســليف ) وبســؤال املدعــى عليــه البينــة‬\n‫علــى ماذكــره مــن قســط ملكتــب ‪ ...‬أجــاب هــذا انتهــى وأبــرز املدعــى‬\n‫عليــه أصــل عقــد بيــع علــى مكتــب ‪ ...‬لالســتثمار العقــاري والتقســيط‬\n‫يتضمــن شــراء املدعــى عليــه لفيــا دوريــن بحــي ‪ .....‬مببلــغ خمســمائة‬\n‫وســبعني ألــف ريــال ومذكــورة حدودهــا وأطوالهــا ومســاحتها ‪ .‬وقــال‬\n‫املدعــى عليــه أننــي اشــتريت هــذه الفيــا بعــد أن خــرج اســمي يف البنــك‬\n‫العقــاري بقــرض خمســمائة ألــف ريــال ‪ .‬وســبعني ألــف ســأدفعها مــن‬\n‫عنــدي وأبــرز عــدد مــن األوراق تفيــد مراجعتــه للبنــك ألجــل ذلــك جــرى‬\n‫رفــع اجللســة مــع األمــر بالكتابــة لقســم اخلبــراء لســؤالهم عــن تأثيــر ذلــك‬\n‫يف تقديــر النفقــة والكتابــة لألحــوال املدنيــة لتنزيــل اســم املدعيــة مــن‬\n‫ســجل األســرة ويف يــوم الثالثــاء املوافــق ‪1433/7/29‬ه ـ فتحــت اجللســة‬\n‫وحضــر املدعــى عليــه وقــد وردنــا مــن قســم اخلبــراء احملضــر برقــم‬\n‫‪ 33/1341109‬وتاريــخ ‪1433/7/22‬ه ـ املبنــي على خطابنا وفيه (وعليه‬\n‫وبعــد االطــاع علــى كامــل مرفقــات املعاملــة يــرى األعضــاء أن مــا جــد‬\n\n\n                                                                                       ‫‪54‬‬\n\f     ‫يف أحــوال املدعــى عليــه ال يؤثــر ذلــك علــى تقديــر النفقــة الســابق وتبقــى‬\n     ‫النفقــة كمــا هــي بالتقديــر الســابق ) أـ ه ـ أعضاء قســم اخلبــراء ‪...‬و‪...‬و‪...‬‬\n     ‫ورئيــس قســم اخلبــراء ‪...‬وبســؤال املدعــى عليــه عــن تنزيــل اســم املدعيــة‬\n     ‫مــن ســجل األســرة أجــاب لــم أراجعهــم بعــد نظــر ًا النشــغالي باالختبــارات‬\n     ‫ثــم الــدوام بعــد ذلــك وال أســتطيع اخلــروج مــن العمل وأن شــاء اهلل ســأقوم‬\n     ‫بذلــك خــال هــذا الشــهر هكــذا أجــاب لــذا جــرى تأمل ما ســبق ضبطه‬\n     ‫بعــد تقــدمي املدعــى عليــه الالئحــة االعتراضيــة وألنــه لــم يجــد مــا يؤثــر‬\n     ‫علــى تقديــر النفقــة كمــا قــرره قســم اخلبــراء وألن املدعيــة أكتفــت يف‬\n     ‫مطالبتهــا بشــهادة امليــاد ‪ ...‬وكذلــك بكــرت العائلــة بالصــورة التــي‬\n     ‫أخذتهــا ولــم يبقــى إال شــهادة ميــاد ‪ ...‬وتنزيــل اســم املدعيــة مــن ســجل‬\n     ‫األســرة اخلــاص باملدعــى عليــه فلمــا تقــدم فقــد رجعــت عــن احلكــم‬\n     ‫بإلــزام املدعــى عليــه بتســليم شــهادة ميــاد ‪...‬وكــرت العائلــة وامــا بقيــة‬\n     ‫احلكــم فبحــا لــه مــع شــمول احلكــم بالنفقــة واخــراج شــهادة امليــاد ل‪...‬‬\n     ‫واســقاط اســم املدعيــة مــن ســجل اســرة املدعــى عليــه التنفيــذ املعجــل‬\n     ‫بالكفالــة احلضوريــة الغراميــة بنــاء علــى املادة‪199‬مــن نظــام املرافعــات‬\n     ‫ولوائحــه الشــرعية وقــد امــرت بإحلــاق خالصــة مــا جــد بالصــك وســجله‬\n     ‫ومــن ثــم بعثــة حملكمــة االســتئناف إلكمــال مــا يلــزم وصلــى اهلل وســلم‬\n     ‫علــى نبينــا محمــد وآلــه وصحبــه أجمعــن وبطلــب التوقيــع مــن املدعــى‬\n                                                                 ‫عليــه خــرج ولــم يعــد‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي انــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة الــواردة الينــا برقــم ‪ 34190533‬وتاريــخ‬\n     ‫‪1434/2/28‬ه ـ مــن محكمــة االســتئناف بالريــاض واملرفــق بهــا القــرار‬\n     ‫رقــم‪ 3431170‬وتاريــخ ‪1434/2/5‬ه ـ والــذي جــاء فيــه بعــد املقدمــة‬\n\n\n‫‪55‬‬\n\f‫(‪ ..‬وباالطــاع علــى خطــاب رئيــس احملكمــة العامــة باخلــرج املكلــف‬\n‫املشــار اليــه اعــاه املتضمــن ان ناظــر القضيــة انتقــل الــى احملكمــة‬\n‫العامــة بالريــاض لــذا قــررت الدائــرة بعــث املعاملــة الــى فضيلــة ناظرهــا‬\n‫يف مقــر عملــه احلالــي احملكمــة العامــة بالريــاض إلكمــال الــازم حيــال‬\n‫مــا جــاء يف قــرار الدائــرة رقــم‪33422611‬يف ‪1433/10/10‬ه ـ وبعــد‬\n‫اإلحلــاق علــى الصــك بعــث املعاملــة الــى محكمــة اخلــرج إلحلــاق مــا جــد‬\n‫علــى الصــك علــى الضبــط وصورتــه وســجل الصــك ثــم إعــادة املعاملــة‬\n‫الــى محكمــة االســتئناف إلكمــال الزمهــا ‪)..‬أ ـ ه ـ فجــرى االطــاع‬\n‫علــى القــرار رقــم‪ 33422611‬يف‪1433/10/10‬ه ـ والــذي جــاء فيــه‬\n‫بعــد املقدمــة (وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة لوحــظ االتــي اوال ‪ /‬ان مــا حكــم بــه فضيلتــه مــن‬\n‫النفقــة املســتقبلية بألفــي ريــال شــهريا ألوالده كثيــر وال يتناســب مــع‬\n‫دخــل املدعــى عليــه فعلــى فضيلتــه اعــادة النظــر يف ذلــك وإكمــال مــا‬\n‫يلــزم نحــوه ثانيــا ‪ /‬ان فضيلتــه لــم يذكــر مســتنده يف احلكــم بالنفقــة‬\n‫املاضيــة ‪ )..‬أ ـ ه ـ لــذا جــرى قــراءة الصــك واالطــاع علــى صــورة ضبطــه‬\n‫وارواق املعاملــة وبتأمــل مــا ســبق مــن احلكــم واســبابه فانــي اجيــب علــى‬\n‫مالحظــات اصحــاب الفضيلــة مبــا يلــي ‪:‬اوال ‪ :‬امــا املالحظــة االولــى‬\n‫فالنفقــة الواجبــة علــى االب ألوالده مقــدرة باملعــروف ومت ذلــك عن طريق‬\n‫اهــل اخلبــرة مرتــن ولــم يالحــظ عليهــا شــيء مــع حاجــة االطفــال وقــدرة‬\n‫االب ثانيــا‪ :‬امــا املالحظــة الثانيــة فمســتندي يف احلكــم بالنفقــة املاضيــة‬\n‫هــو مــا دلــت عليــه النصــوص مــن وجــوب نفقــة الوالــد ألوالده ومــا ذكــره‬\n‫الفقهــاء مــن انــه اذا لــم ينفــق وانفــق غيــره بنيــة الرجــوع فــان لــه الرجــوع‬\n‫ينظــر شــرح املنتهى‪680/5‬طبعــة الرســالة وكشــاف القنــاع‪161/13‬‬\n\n\n                                                                                          ‫‪56‬‬\n\f     ‫طبعــة وزارة العدل‪292/‬وقــال يف دليــل الطالــب ص ‪ 292‬طبعــة طيبــه‬\n     ‫(وحيــث امتنــع منهــا زوج أو قريــب وانفــق اجنبــي بنيــة الرجــوع رجــع‪)..‬‬\n     ‫أ‪.‬ه ـ وغيرهــا مــن املراجــع واملدعيــة لــم تطالــب بكامــل النفقــة املاضيــة‬\n     ‫واملدعــي لــم يدعــي انــه انفــق فضــا عــن ان يثبــت ذلــك وعليــه فانــي علــى‬\n     ‫مــا حكمــت بــه واجريتــه مــع االمــر ببعــث املعاملة حملكمــة اخلرج إلحلاق‬\n     ‫مــا جــد يف الصــك علــى الضبــط وصورتــه وســجل الصــك ومــن ثــم بعــث‬\n     ‫املعاملــة حملكمــة االســتئناف إلكمــال الــازم حســب التوجيــه وبــاهلل‬\n     ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/7/17‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n     ‫لتمييــز قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n     ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫باخلــرج برقــم ‪ 34/1986697‬وتاريــخ ‪1434/8/16‬ه ـ املرفــق بهــا الصــك‬\n     ‫الصــادر مــن فضيلتــه مســاعد رئيــس احملكمة ســابق ًا الشــيخ‪ ...‬املســجل‬\n     ‫برقــم ‪ 32191315‬وتاريــخ ‪1432/8/4‬ه ـ اخلــاص بدعــوى ‪ ...‬بالوكالــة‬\n     ‫عــن ‪ ...‬ضــد ‪ ...‬يف قضيــة نفقــة ‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه‬\n     ‫مبــا هــو مــدون ومفصــل فيــه ‪ .‬وحيــث ســبقت دراســة الصــك وصــورة‬\n     ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا‬\n     ‫أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك بتاريــخ ‪1434/7/17‬ه ـ بنــاء‬\n     ‫علــى قرارنــا رقــم ‪ 3431170‬وتاريــخ ‪1434/2/5‬ه ـ لــم يظهــر مــا يوجــب‬\n     ‫االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                               ‫وســلم ‪.‬‬\n\n\n\n\n‫‪57‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":45,"source_page_end":57,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9f0b94384c19f4951e6bde56452ad96011428a66fa668e29a549723206e1a709","normalized_text_hash":"96410895d928c72c45bd7acba2a38a7a2e2e5de25bd409a798298303a39cc214","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p45-32191315"},{"id":"d6f89835-d98b-52d6-a008-de997b714e7e","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة -نفقة حمل -نفقة طفل -املطالبة بالنفقة املاضية واملستقبلية -دفع الزوج بعدم استحقاق الزوجة للنفقة لنشوزها -حتديد النفقة عن طريق قسم اخلبراء -النفقة مقابل التمكن من االستمتاع -احلكم بنفقة الولد دون أمه .","document_number":"33182259","case_number":"3223182","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/11","year":"1434","subject":"نفقة -نفقة زوجة -نفقة حمل -نفقة طفل -املطالبة بالنفقة املاضية واملستقبلية -دفع الزوج بعدم استحقاق الزوجة للنفقة لنشوزها -حتديد النفقة عن طريق قسم اخلبراء -النفقة مقابل التمكن من االستمتاع -احلكم بنفقة الولد دون أمه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/4/11 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33182259 :‬‬\n                    ‫َر ْق ُم الدعوى‪3223182 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 3444281‬تاريخه‪1434/2/23 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة زوجــة ‪ -‬نفقــة حمــل ‪ -‬نفقــة طفــل ‪ -‬املطالبــة بالنفقــة‬\n‫املاضيــة واملســتقبلية ‪ -‬دفــع الــزوج بعــدم اســتحقاق الزوجــة للنفقــة‬\n‫لنشــوزها ‪ -‬حتديــد النفقــة عــن طريــق قســم اخلبــراء ‪ -‬النفقــة مقابــل‬\n             ‫التمكــن مــن االســتمتاع ‪ -‬احلكــم بنفقــة الولــد دون أمــه ‪.‬‬\n\n\n\n\n ‫‪ -1‬ما قرره أهل العلم ‪ :‬من أن النفقة مقابل التمكني من االستمتاع‪.‬‬\n              ‫‪ -2‬ما قرره أهل العلم ‪ :‬من لزوم نفقة األب على ولده ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة علــى املدعــى عليــه بأنــه حصــل بينهمــا خــاف وقــام‬\n‫بطردهــا مــن املنــزل وهــى حامــل‪ ،‬طلبــت املدعيــة نفقتهــا عــن املــدة‬\n‫املاضيــة ونفقــة احلمــل والــوالدة ونفقــة مســتقبلية لهــا ولولدهــا‪ ،‬أقــر‬\n‫املدعــى عليــه بالدعــوى ودفــع بــأن املدعيــة خرجــت بغيــر رضــاه وأنــه‬\n‫طلبهــا مــرار ًا للرجــوع إلــى بيــت الزوجيــة فرفضــت‪ ،‬ذكــر املدعــى عليــه‬\n‫أنــه دفــع نفقــة الــوالدة وكان يرســل بعــض األغراض لولــده بعد الوالدة‪،‬‬\n‫جــرى تقديــر نفقــة املدعيــة وولدهــا عــن املــدة املاضيــة وحتديــد نفقــة‬\n‫مســتقبلية مــن قبــل قســم اخلبــراء باحملكمــة‪ ،‬جــرى ســؤال املدعيــة عما‬\n‫ذكــره املدعــى عليــه مــن أنــه طلبهــا لبيــت الطاعــة فرفضــت فصادقــت‬\n                                                                                  ‫‪58‬‬\n\f     ‫املدعيــة علــى ذلــك وذكــرت بــأن ســبب رفضهــا الرجــوع ألن املدعــى‬\n     ‫عليــه طردهــا‪ ،‬ملــا قــرره أهــل العلــم مــن أن النفقــة مقابــل التمكــن مــن‬\n     ‫االســتمتاع ولــزوم نفقــة األب علــى ولــده لــذا صــدر احلكم بإلــزام املدعى‬\n     ‫عليــه بدفــع نفقــة ابنــه املاضيــة واملســتقبلية‪ ،‬صــرف النظــر عــن مطالبــة‬\n     ‫املدعيــة بنفقتهــا‪ ،‬اعتــرض الطرفــان علــى احلكــم‪ ،‬صــدق احلكــم مــن‬\n                                                          ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض برقــم‪ 3223182‬وتاريــخ ‪1432/01/27‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم‪ 3270292‬وتاريــخ ‪1432/1/27‬ه ـ ففــي يــوم الســبت‬\n     ‫املوافــق ‪1432/04/28‬ه ـ افتتحــت اجللســة الســاعة ‪ 8 : 00‬وفيهــا‬\n     ‫حضــرت ‪ ...‬بالســجل املدنــي رقــم ‪ ...‬واملعــرف بهــا مــن قبــل والدهــا ‪...‬‬\n     ‫بالســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى عليــه ‪ ...‬وال مــن ينــوب عنــه‬\n     ‫وباالطــاع علــى أوراق املعاملــة وجدنــا خطــاب محضــري اخلصــوم بهــذه‬\n     ‫احملكمة برقم ‪ 32/237028‬يف ‪1432/3/16‬هـ واملتضمن (مت التوجه‬\n     ‫للموقــع املذكــور وأفــادوا أنــه ال يوجــد لديهــم موظــف بهــذا االســم‪... ،‬‬\n     ‫التوقيــع) ا‪.‬ه ـ ويف جلســة أخــرى حضــرت املدعيــة وبرفقهــا معرفهــا يف‬\n     ‫اجللســة الســابقة ‪ ،‬وحضــر حلضورهمــا ‪ ...‬بالســجل املدنــي رقــم ‪، ...‬‬\n     ‫فا ّدعــت املــرأة قائلــة ‪ :‬إن املدعــى عليــه هــو زوجــي بالعقــد الصحيــح منــذ‬\n     ‫عــام ‪1428‬ه ـ وأجنبــت لــه علــى فــراش الزوجيــة ولــد ًا اســمه ‪ ...‬وعمــره‬\n     ‫ســنتان وثمانيــة أشــهر ‪ ،‬ويف ‪1429/7/16‬ه ـ حصــل خــاف بيننــا وقــام‬\n‫‪59‬‬\n\f‫بطــردي مــن املنــزل وأنــا حامــل ‪ ،‬ومنــذ ذلــك التاريــخ وحتــى اآلن وأنــا‬\n‫عنــد أهلــي ‪ ،‬ولــم ينفــق علــي خاللهــا وال علــى احلمــل وال علــى الولــد ‪،‬‬\n‫أطلــب إلزامــه بالنفقــة املاضيــة وتقديــر نفقتــي املســتقبلية هــذه دعــواي‬\n‫ا ‪ :‬مــا‬\n       ‫أطالبــه بذلــك وأســأله اجلــواب ‪ ،‬وبســؤال املدعــى عليــه أجــاب قائـ ً‬\n‫ذكرتــه املدعيــة مــن الــزواج واإلجنــاب فهــذا صحيــح‪ ،‬ومــا ذكرتــه مــن‬\n‫أننــي قمــت بطردهــا فهــذا غيــر صحيــح ‪ ،‬والصحيــح أنــه وقــع خــاف‬\n‫بينــي وبينهــا وقلــت لهــا وأن يف حالــة غضــب ‪ :‬ال أجــي إلــى البيــت وأنــت‬\n‫موجــودة ‪ ،‬ثــم اتصلــت بأهلهــا وشــرحت لهــم ما حصــل وطلبت منهم عدم‬\n‫احلضــور وأنهــا مشــكلة ممكــن تداركهــا ‪ ،‬ثــم ذهبــت للعمــل وعنــد‬\n‫رجوعــي تفاجــأت بأنهــا غيــر موجــودة وأن أهلهــا قــد أتــوا ألخذهــا‪ ،‬وقــد‬\n‫ذهبــت لبيــت أهلهــا أكثــر مــن عشــرين مــرة ألجــل إرجاعهــا إلــى بيتــي‬\n‫ولكــن دون جــدوى‪ ،‬و أنــا غيــر مســتعد بدفــع نفقتهــا املاضيــة ألنهــا‬\n‫خرجــت مــن بيتــي بإرادتهــا ولــم ترجــع لبيــت الزوجيــة هــذا جوابــي ‪،‬‬\n‫فســألت املدعــى عليــه هــل أنفقــت علــى املدعيــة أو علــى الولــد أو احلمــل ‪،‬‬\n‫فأجــاب ‪ :‬لــم أنفــق عليهــا وال علــى حملهــا ‪ ،‬ولكنــي أنفقــت علــى الوالدة‬\n‫‪ ،‬وكنــت أرســل احتياجــات ولــدي مــن حفائــظ ومالبــس ونحوهــا‬\n‫بشــكل مســتمر هكــذا ذكــر ‪ ،‬فســألت املــرأة عمــا ذكــره املدعــي‬\n‫مــن إحضــار مســتلزمات الولــد فأجابــت ‪ :‬أحضــر كســوة عيديــن‪،‬‬\n‫أمــا املســتلزمات األخــرى كاحلفائــظ واحلليــب فــكان يحضرهــا علــى‬\n‫فتــرات متفاوتــة فمــرة كل شــهرين ومــرة كل ثالثــة أشــهر عندمــا‬\n‫كان الطفــل صغيــر ًا ‪ ،‬فلمــا بلــغ الطفــل ســنتني لــم يحضــر لــه حفائــظ‬\n‫أو حليــب هكــذا ذكــرت ‪ ،‬وقــد جــرت الكتابــة إلــى قســم اخلبــراء‬\n‫بهــذه احملكمــة بخطابــي رقــم ‪ 32/1023491‬وتاريــخ ‪1432/8/10‬ه ـ‬\n\n\n                                                                                     ‫‪60‬‬\n\f     ‫بخصــوص حتديــد النفقــة‪ ،‬فوردنــي القــرار الصــادر مــن مكتــب الصلــح‬\n     ‫بهــذه احملكمــة رقــم ‪ 306‬وتاريــخ ‪1432/9/16‬ه ـ املتضمــن ‪ ..( :‬نفيــد‬\n     ‫فضيلتــه أنــه مت االجتمــاع بالطرفــن وقــد تعــذر الصلــح بينهمــا حيــث‬\n     ‫أن املدعيــة تطالــب املدعــى عليــه بالنفقــة عليهــا وعلــى ابنهــا وذلــك‬\n     ‫مــن تاريــخ خروجهــا مــن املنــزل بطلبــه يف ‪1429/7/17‬ه ـ وأنهــا بذلــك‬\n     ‫التاريــخ كانــت حامــل بابنهــا ‪ ...‬البالــغ مــن العمــر ســنتني وخمســة أشــهر‬\n     ‫أمــا املدعــى عليــه فأفــاد بأنــه ليــس لديــه مانــع مــن النفقــة وأنــه يف حالــة‬\n     ‫إلزامــه بالنفقــة فــإن قدرتــه الشــهرية هــي ســتمائة ريــال شــهري ًا للمدعيــة‬\n     ‫وســتمائة ريــال البنــه وجتــدون إقــرار كل منهمــا بطــي املعاملــة ‪ ،‬والــذي‬\n     ‫نــراه أن تكــون النفقــة املاضيــة للمدعيــة خمســمائة ريــال شــهري ًا‬\n     ‫والنفقــة املســتقبلية لهــا والبنهــا ســتمائة ريــال شــهري ًا ‪ )..‬ا‪.‬ه ـ ‪ ،‬وبعــرض‬\n     ‫مــا جــاء يف قــرار مكتــب الصلــح بهــذه احملكمــة علــى املدعيــة ‪ ،‬قــررت‬\n     ‫عــدم موافقتهــا علــى النفقــة املاضيــة وقدرهــا خمســمائة ريــال شــهري ًا ‪،‬‬\n     ‫وموافقتهــا علــى النفقــة املســتقبلية وقدرهــا ســتمائة ريــال شــهري ًا لهــا‬\n     ‫وســتمائة ريــال شــهري ًا البنهــا ‪ ،‬وبعــرض مــا جــاء يف قــرار مكتب الصلح‬\n     ‫ا ‪ :‬إننــي غيــر موافــق علــى دفــع النفقــة‬  ‫علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫املاضيــة ألنهــا خرجــت مــن بيــت الزوجيــة وال مانــع لــدي مــن دفــع النفقــة‬\n     ‫املســتقبلية البنهــا وقدرهــا ســتمائة ريــال شــهري ًا أمــا نفقتهــا املســتقبلية‬\n     ‫وقدرهــا ســتمائة ريــال شــهري ًا فــا مانــع لــدي مــن دفعهــا بشــرط أن‬\n     ‫ترجــع إلــى بيــت الطاعــة هكــذا ذكــر‪ ،‬وبعــرض الصلــح علــى الطرفــن‬\n     ‫لــم يصطلحــا علــى شــيء ‪ ،‬وقــد وردنــي مــن قســم اخلبــراء القــرار رقــم‬\n     ‫‪ 306‬يف ‪1432/09/16‬ه ـ احملــال لــي بشــرح رئيــس احملكمــة العامــة‬\n     ‫بالريــاض رقــم ‪ 32/1023491‬يف ‪1432/9/20‬ه ـ املتضمــن (عليــه نفيــد‬\n\n\n‫‪61‬‬\n\f‫فضيلتــه أنــه مت االجتمــاع بالطرفــن وقــد تعــذر الصلــح بينهمــا حيــث‬\n‫أن املدعيــة تطالــب املدعــى عليــه بالنفقــة عليهــا وعلــى ابنهــا وذلــك‬\n‫مــن تاريــخ خروجهــا مــن املنــزل بطلبــه يف ‪1429/7/17‬ه ـ وأنهــا بذلــك‬\n‫التاريــخ كانــت حامــل بابنهــا ‪ ...‬البالــغ مــن العمــر ســنتني وخمســة أشــهر‬\n‫أمــا املدعــى عليــه أفــاد بأنــه ليــس لديــه مانــع مــن النفقــة وأنــه يف حالــة‬\n‫إلزامــه بالنفقــة فــإن قدرتــه هــي ‪ 600‬ريــال شــهريا للمدعيــة و ‪600‬‬\n‫ريــال البنــه وجتــدون إقــرار كال منهمــا بطــي املعاملــة والــذي نــراه أن‬\n‫تكــون النفقــة املاضيــة للمدعيــة ‪ 500‬ريــال شــهريا والنفقــة املســتقبلية‬\n‫لهــا والبنهــا ‪ 600‬ريــال شــهريا هــذا مــا لدينــا ‪ ،‬أعضــاء مكتــب الصلــح‬\n‫‪ ...‬توقيعــه ‪ ... ،‬توقيعــه ‪ ،‬مديــر مكتــب الصلــح ‪ ...‬توقيعــه ) وبعــرض‬\n‫هــذا القــرار علــى املدعيــة قالــت‪ :‬إننــي موافقــة عليــه وأطلــب أن يضــاف‬\n‫حتديــد نفقــة االبــن املاضيــة أمــا املدعــى عليــه فقــرر عــدم موافقتــه علــى‬\n‫القــرار وأنــه ال مانــع لديــه مــن النفقــة املســتقبلية وقدرهــا ســبعمائة ريــال‬\n‫شــهريا فقــط هكــذا ذكــر ‪ ،‬وألن قــرار قســم اخلبــراء لــم يتضمــن نفقــة‬\n‫االبــن املاضيــة قــررت الكتابــة لهــم لتحديــد النفقــة لــذا رفعــت اجللســة‬\n‫حلــن ورود اإلجابــة ويف جلســة أخــرى حضــرت املدعيــة وبرفقهــا والدهــا‬\n‫واملدعــى عليــه وقــد وردنــي قــرار قســم اخلبــراء يف هــذه احملكمــة رقــم‬\n‫‪122‬يف ‪1433/2/14‬ه ـ املتضمــن ( نفيــد فضيلتــه أنــه مت االجتمــاع‬\n‫بالطرفــن وقــد تعــذر الصلــح بينهمــا بخصــوص تقديــر نفقــة االبــن‬\n‫الســابقة وبنــاء علــى ذلــك فإننــا نــرى أن تكــون نفقــة االبــن الســابقة‬\n‫‪600‬ريــال شــهري ًا أمــا نفقتــه املســتقبلية وكذلــك نفقــة املدعيــة الســابقة‬\n‫واملســتقبلية فقــد ســبق وأن مت تقديــر ذلــك مبوجــب قرارنــا املرفــق‬\n‫برقــم ‪ 32/306‬تاريــخ ‪1432/9/16‬ه ـ املتضمــن نفقــة االبــن املســتقبلية‬\n\n\n                                                                                         ‫‪62‬‬\n\f     ‫‪600‬ريــاال شــهري ًا ونفقــة املدعيــة املاضيــة ‪500‬ريــاال شــهري ًا واملســتقبلية‬\n     ‫‪600‬ريــاال شــهري ًا لــكل واحــد منهمــا تــودع يف حســاب املدعيــة هــذا مــا‬\n     ‫لدينــا واهلل يحفظكــم) ا‪.‬ه ـ ثــم ســألت املدعيــة هــل طلبهــا املدعــى عليــه‬\n     ‫بعــد خروجهــا مــن بيــت زوجها فقالت‪ :‬نعــم طلبني لبيت الطاعة ورفضت‬\n     ‫الرجــوع ألنــه طردنــي مــن البيــت هكــذا ذكــرت ثــم حصلــت مداولــة‬\n     ‫بــن الطرفــن مــن أجــل اإلصــاح بينهمــا ‪ ،‬ويف جلســة أخــرى حضــرت‬\n     ‫املدعيــة وبرفقهــا والدهــا واملدعــى عليــه وطلبــت املدعيــة إلــزام املدعــى‬\n     ‫عليــه بدفــع نفقــة االبــن املاضيــة منــذ والدتــه واملســتقبلية كنفقــة شــهرية‬\n     ‫وإلــزام املدعــى عليــه بدفــع نفقتهــا املاضيــة ثــم ســألت املدعيــة واملدعــى‬\n     ‫عليــه عــن تاريــخ والدة ولدهمــا فأجابــا هــو مولــود بتاريــخ ‪1430/4/2‬ه ـ‬\n     ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعيــة بــأن زوجهــا‬\n     ‫طلبهــا لبيــت الطاعــة‪ ،‬وأنهــا رفضــت ذلــك‪ ،‬ألنــه طردهــا ـ وملــا قــرره أهــل‬\n     ‫العلــم مــن أن النفقــة مقابــل التمكــن مــن االســتمتاع وللــزوم نفقــة األب‬\n     ‫علــى ابنــه ولقــرار قســم اخلبــراء املرصــود أعــاه بخصــوص نفقــة االبــن‬\n     ‫لــذا قــررت مايلــي‪ :‬أوال‪ /‬صرفــت النظــر عــن مطالبــة املدعيــة بنفقتهــا‬\n     ‫ثانيــا‪ /‬ألزمــت املدعــى عليــه بدفــع نفقــة ابنــه املســتقبلية وقدرهــا ســتمائة‬\n     ‫ريــال شــهريا اعتبــارا مــن شــهر ربيــع اآلخــر مــن هــذا العــام ‪1433‬ه ـ ودفع‬\n     ‫نفقــة االبــن املاضيــة وقدرهــا ســتمائة ريــال شــهريا اعتبــارا مــن تاريــخ‬\n     ‫والدتــه ‪1430/4/2‬ه ـ ومجموعهــا حتــى شــهر ربيــع األول لعــام ‪1433‬ه ـ‬\n     ‫واحــد وعشــرون ألــف ريــال ومبــا تقــدم حكمــت وبعرضــه عليهمــا قررت‬\n     ‫املدعيــة القناعــة فيمــا يتعلــق بنفقــة ابنهــا املاضيــة واملســتقبلية وقــررت‬\n     ‫عــدم القناعــة فيمــا يتعلــق بنفقتهــا وقــرر املدعــى عليــه عــدم القناعــة‬\n     ‫فيمــا يتعلــق بالنفقــة املاضيــة‪ ،‬وأغلقــت اجللســة الســاعة ‪ 08.45‬وبــاهلل‬\n\n\n‫‪63‬‬\n\f‫التوفيــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبه وســلم‪.‬‬\n                                                       ‫حــرر يف ‪1433/4/6‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت إلينــا املعاملــة مــن محكمــة‬\n‫االســتئناف برقــم ‪ 34326795‬يف ‪1434/03/02‬ه ـ محالــة إلينــا‬\n‫بالقيــد رقــم ‪ 34/590732‬وتاريــخ ‪1434/03/08‬ه ـ مــزودة بالقــرار‬\n‫رقــم ‪ 3444281‬يف ‪1434/02/23‬ه ـ بخصــوص دعــوى ‪ ...‬ضــد ‪...‬‬\n‫واملتضمــن ( حيــث ســبقت دراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة بنــاء علــى قــرار الدائــرة رقــم ‪33327814‬‬\n‫وتاريــخ ‪1433/07/05‬ه ـ وباالطــاع علــى مــا أجــاب بــه فضيلتــه لــم‬\n‫يظهــر باألكثريــة مــا يوجــب االعتــراض‪ ،‬قاضــي اســتئناف ‪ ...‬ختمــه‬\n‫وتوقيعــه‪ ،‬قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه ‪ ،‬رئيــس الدائــرة د‪ ... .‬لــه‬\n‫وجهــة نظــر مرفقــة ختمــه وتوقيعــه )ا‪.‬ه ـ ‪ ،‬لــذا أمــرت بالتهميــش علــى‬\n‫الضبــط والســجل بذلــك‪ ،‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/03/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫املختصــة بتمييــز قضايــا األحــوال الشــخصية واالنهــاءات مبحكمــة‬\n‫االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 33/1394051‬وتاريــخ ‪1434/1/27‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...‬املســجل‬\n‫برقــم ‪ ...‬وتاريــخ ‪1433/4/11‬ه ـ اخلــاص بدعــوى ‪ ...‬ضــد ‪ ...‬بشــأن طلــب‬\n‫املدعيــة إلــزام املدعــى عليــه بدفــع النفقــة املوضحــة بالصــك املتضمــن أن‬\n‫فضيلتــه قــرر مــا يلــي ‪ /‬أوال ‪ :‬صــرف النظــر عن مطالبــة املدعية بنفقتها‪.‬‬\n‫ثانيــا ‪ :‬الــزم املدعــى عليــه بدفــع نفقــة ابنــه ‪ ...‬إلــخ وبــه حكــم ‪ .‬حيــث‬\n\n\n                                                                                      ‫‪64‬‬\n\f     ‫ســبقت دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n     ‫املعاملــة بنــاء علــى قــرار الدائــرة رقــم ‪ 33327814‬وتاريــخ ‪1433/7/5‬ه ـ‬\n     ‫وباالطــاع علــى مــا أجــاب بــه فضيلتــه لــم يظهــر باألكثريــة مــا يوجــب‬\n     ‫االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                           ‫وســلم ‪.‬‬\n\n\n\n\n‫‪65‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":58,"source_page_end":65,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0320291b415877de95efe623b5658b0592cf599133f62c3074771fd2d71756a7","normalized_text_hash":"f8d6f06ed49fd92d1c226e6b0ec9a5e56a996ca731a80ac1108b8486ddb8797c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p58-33182259"},{"id":"78c4431a-269d-5c92-8706-d8281398858b","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة الزوجة بنفقتها املاضية واملستقبلية -مطالبة األم بنفقة ابنها املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء - -احلكم بتسليم النفقة املاضية واملستقبلية للزوجة","document_number":"34180121","case_number":"33248699","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/6","year":"1434","subject":"نفقة -مطالبة الزوجة بنفقتها املاضية واملستقبلية -مطالبة األم بنفقة ابنها املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء - -احلكم بتسليم النفقة املاضية واملستقبلية للزوجة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34180121 :‬‬\n                   ‫َر ْق ُم الدعوى‪33248699 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34258270‬تاريخه‪1434/7/3 :‬هـ‬\n\n\n‫نفقــة ‪ -‬مطالبــة الزوجــة بنفقتهــا املاضيــة واملســتقبلية ‪ -‬مطالبــة األم‬\n‫بنفقــة ابنهــا املاضيــة واملســتقبلية ‪ -‬تقديــر النفقــة عــن طريــق قســم‬\n‫اخلبــراء ‪ - -‬احلكــم بتســليم النفقــة املاضيــة واملســتقبلية للزوجــة‬\n                                                                    ‫وابنهــا‪.‬‬\n\n\n\n                                         ‫قوله تعالى {ل ُِي ْنفِ ْق ُذو َس َع ٍة مِ ْن َس َع ِتهِ}‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه زوجهــا دخــل بهــا وأجنبــت منــه ابن ًا‬\n‫واحــد ًا مولــود ًا يف ‪1431/7/16‬ه ـ وأنــه أخرجهــا مــن بيــت الزوجيــة إلــى‬\n‫ال ألنــه‬‫بيــت أهلهــا يف ‪1432/6/28‬ه ـ ألنهــا طلبــت منــه ســكن ًا مســتق ً‬\n‫ال حســب ما شــرط‬     ‫اســكنها يف بيــت أهلــه ولــم يجعــل لها ســكن ًا مســتق ً‬\n‫عليــه يف العقــد وطلبــت إلــزام املدعــى عليــه بنفقتهــا املاضيــة و القادمــة‬\n‫ونفقــة ابنهــا املاضيــة والقادمــة حيــث أنهــا تنفــق علــى ابنهــا بنيــة الرجــوع‬\n‫علــى املدعــى عليــه‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر‬\n‫أنهــا غــادرت إلــى بيــت أهلهــا بســبب رفــض اســتمرار الســكن مــع أهلــه‬\n‫وأنــه ال مانــع لديــه مــن تســليمها النفقــة لهــا والبنهــا بعــد تقديرهــا علمـ ًا‬\n‫أن ظروفــه املاديــة ال تســمح لــه بتأمــن ســكن مســتقل‪ ،‬مت تقديــر‬\n\n                                                                                                    ‫‪66‬‬\n\f     ‫النفقــة للمدعيــة وابنهــا مــن قبــل مكتــب الصلــح لــكل واحــد منهمــا‬\n     ‫مبلــغ أربعمائــة ريــال‪ ،‬قــرر ناظــر القضيــة لألســباب التــي ذكرهــا يف‬\n     ‫نــص القضيــة ولقولــه تعالــى {ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة مِ ــنْ َسـ َـع ِتهِ} إلــزام املدعــى‬\n     ‫عليــه بنفقــة االبــن ووالدتــه املاضيــة لــكل واحــد منهمــا مبلغ ـ ًا قــدره‬\n     ‫ثمانيــة آالف وأربعمائــة ريــال‪ ،‬وإلزامــه بنفقــة االبــن أربعمائــة ريــال‬\n     ‫شــهري ًا مــادام مــع والدتــه يف حضانتهــا ونفقــة شــهرية للمدعيــة أربعمائــة‬\n     ‫ال أو ينقطــع عقــد الزوجــة‬          ‫ال لهــا مســتقب ً‬         ‫ريــال حتــى يهيــئ بيت ـ ًا مســتق ً‬\n     ‫بطــاق و نحــوه‪ ،‬قــررت املدعيــة املعارضــة وقــرر املدعــى عليــه القناعــة‪،‬‬\n                    ‫صــدر قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض برقــم ‪ 33248699‬وتاريــخ ‪1433/04/10‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 33666540‬وتاريــخ ‪1433/04/10‬ه ـ ففــي يــوم‬\n     ‫الثالثــاء املوافق‪1433/06/24‬ه ـ افتتحــت اجللســة وفيهــا حضــرت‬\n     ‫ســعودية مبوجــب ســجل مدنــي رقــم (‪ ).....‬املعــرف بهــا مــن قبــل والدهــا‬\n     ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬وادعــت علــى احلاضــر معهــا‬\n     ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ).....‬قائلــة يف دعواهــا ‪ :‬إن املدعــى‬\n     ‫عليــه هــذا احلاضــر معــي زوجــي مبوجــب عقــد النــكاح لــدى مــأذون‬\n     ‫االنكحــة برقــم ‪........‬وتاريــخ ‪ 1430/6/6‬علــى مهــر وقــدره خمســون‬\n     ‫الــف ريــال مقبوضــة ودخــل بــي الدخــول الشــرعي وأجنبــت منــه (‪).....‬‬\n     ‫املولــود يف ‪1431/7/16‬ه ـ وأخرجنــي مــن بيتــي الــى بيــت أهلــي يف‬\n\n‫‪67‬‬\n\f‫‪1432/6/28‬ه ـ حيــث قــال لــي روحــي ألهلــك إلننــي طلبــت منــه ســكنا‬\n‫مســتقال لــي ألنــه أســكنني يف بيــت أهلــه املســتأجر فاتصلــت علــى‬\n‫اهلــي وأخذونــي ثــم بعــد اســبوعني احضــر عفشــي الــى بيــت اهلــي والــى‬\n‫ال حســب شــرط العقــد لــذا اطلــب الزامــه‬     ‫االن لــم يجعــل لــي بيتـ ًا مســتق ً‬\n‫بنفقتــي املاضيــة والقادمــة ونفقــة ابنــي ‪........‬املاضيــة والقادمــة بعــد‬\n‫تقديرهــا وقــد كنــت انفــق عليــه بنيــة الرجــوع يف النفقــة ولــم يســلم لــي‬\n‫مــن نفقــة ســوى ســتمائة ريــال فقــط هــذه دعــواى وبعرضها علــى املدعى‬\n‫عليــه اجــاب قائــا ‪ :‬مــا ذكرتــه املدعيــة مــن زواجــي بهــا والدخــول واملهر‬\n‫واجنابهــا منــي ‪........‬وســلمت لهــا مــن النفقــة ســتمائة ريــال فقــط فهــذا‬\n‫كلــه صحيــح ومــا ذكرتــه اننــي طلبــت منهــا الذهــاب الــى اهلهــا فغيــر‬\n‫صحيــح بــل خرجــت مــن نفســها النهــا ترفــض اســتمرار الســكن مــع‬\n‫اهلــي وانــا الاســتطيع ان اضــع لهــا ســكنا مســتقال لعــدم مقدرتــي‬\n‫املاديــة وال مانــع لــدي مــن تقديــر نفقتهــا ونفقــة ابنــي املاضيــة والقادمــة‬\n‫وتســليمها لهــا متــى مــا كانــت تناســب قدرتــي املاديــة هكــذا أجــاب‬\n‫لــذا أمــرت بالكتابــة لقســم اخلبــراء لتقديــر النفقــة املدعــى بهــا‪ .‬ويف يــوم‬\n‫الســبت املوافق‪1434/04/06‬هـ افتتحت اجللســة وفيها حضرت املدعية‬\n‫املعــرف بهــا مــن قبــل أخيهــا ‪ .....‬ســعودي مبوجــب ســجل مدنــي رقــم (‪).....‬‬\n‫وحضــر املدعــى عليــه ووردنــا خطــاب مديــر مكتــب الصلــح برقــم ‪........‬‬\n‫وتاريــخ ‪1434/3/25‬ه ـ املتضمــن أنــه مت االجتمــاع بالطرفــن وقــد تعــذر‬\n‫الصلــح بينهمــا بخصــوص النفقــة حيــث ذكــرت املدعيــة أنهــا تطالــب‬\n‫بنفقتهــا ونفقــة ابنهــا املاضيــة واملســتقبلية وأنــه لــم ينفــق عليهــم مــن مــا‬\n‫يقــارب ســنة وثمانيــة أشــهر وأن النفقــة تكلفهــا ‪ 800‬ريــال وابنهــا ‪800‬‬\n‫ريــال أمــا بالنســبة للمدعــى عليــه فقــد ذكــر بأنــه ليــس لديــه مانــع مــن‬\n\n\n                                                                                          ‫‪68‬‬\n\f     ‫النفقــة للمدعيــة وابنهــا بواقــع ‪ 600‬ريــال شــهريا وذلــك حســب ظروفــه‬\n     ‫يف الوقــت احلاضــر وأن مرتبــه ‪ 3500‬ريــال ويوجــد عليــه قســط شــهري‬\n     ‫‪ 1771‬ريــال وجتــدون إقــرار كال منهمــا بطــي املعاملــة وبنــاء علــى ذلــك‬\n     ‫واحلــال كمــا ذكــر وبعــد االطــاع علــى مقــدار مرتــب املدعــى عليــه‬\n     ‫حيــث اتضــح أنــه يتقاضــى مرتــب ‪ 3500‬ريــال وذلــك حســب اخلطــاب‬\n     ‫املرفــق رقــم بــدون وتاريــخ ‪1434/2/3‬ه ـ الصــادر مــن إدارة املجاهديــن‬\n     ‫وكذلــك كشــف احلســاب املرفــق واألقســاط املســتحقة عليــه وبعــد‬\n     ‫التأمــل يف الوضــع املــادي للمدعــى عليــه فإننــا نــرى أن تكــون النفقــة‬\n     ‫الســابقة واملســتقبلية للمدعيــة وابنهــا ‪ 400‬ريــال شــهريا لــكل واحــد‬\n     ‫منهمــا هــذا مــا لدينــا‪ .‬أ‪.‬ه ـ وبعــرض ذلــك علــى املدعيــة أجابــت قائلــة‪:‬‬\n     ‫أعــارض مــا جــاء يف قــرار مكتــب الصلــح هكــذا أجابــت‪ .‬وبعرضــه‬\n     ‫علــى املدعــى عليــه أجــاب قائــا‪ :‬أوافــق علــى مــا جــاء يف قــرار مكتــب‬\n     ‫الصلــح هكــذا أجــاب‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n     ‫وقــرار مكتــب الصلــح ولقولــه تعالــى‪( :‬لينفــق ذو ســعة مــن ســعته)‬\n     ‫لــذا ألزمــت املدعــى عليــه أن يدفــع للمدعيــة مــا يلــي‪ :‬أوال‪ :‬نفقــة ابنهــا‬\n     ‫املاضيــة اعتبــارا مــن تاريــخ ‪1432/6/28‬ه ـ حتــى تاريــخ ‪1434/3/28‬ه ـ‬\n     ‫وقدرهــا ثمانيــة األلــف وأربعمائــة ريــال‪ .‬ثاني ـاً‪ :‬نفقتهــا املاضيــة اعتبــارا‬\n     ‫مــن تاريــخ ‪1432/6/28‬ه ـ حتــى تاريــخ ‪1434/3/28‬ه ـ وقدرهــا‬\n     ‫ثمانيــة األلــف وأربعمائــة ريــال‪ .‬ثالثــا‪ :‬نفقــة شــهرية البنهــا اعتبــارا مــن‬\n     ‫‪1434/4/28‬ه ـ وقدرهــا أربعمائــة ريــال مــا دام االبــن معهــا يف بيــت‬\n     ‫والدهــا‪ .‬رابعــا‪ :‬نفقــة شــهرية لهــا اعتبــارا مــن ‪1434/4/28‬ه ـ وقدرهــا‬\n     ‫أربعمائــة ريــال حتــى يهيــئ لهــا املدعــى عليــه ســكنا مســتقال أو ينقطــع‬\n     ‫عقــد الزوجيــة بطــاق ونحــوه‪ .‬وبــه حكمــت وبإعــان احلكــم قــررت‬\n\n\n‫‪69‬‬\n\f‫املدعيــة املعارضــة فســلمتها صــورة احلكــم لتقــدمي اعتراضهــا عليــه‬\n‫خــال ثالثــن يومــا فــإن مضــت املــدة ولــم تقــدم الئحــة اعتراضهــا‬\n‫ســقط حقهــا يف االعتــراض واكتســب احلكــم القطعيــة وأمــا املدعــى‬\n‫عليــه فقــرر الق ـن ــاعـ ــة باحلـك ـ ــم وبــاهلل التوفيــق وصلــى اهلل علـ ــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وسل ــم‪ .‬حـ ــرر يف ‪1434/04/06‬ه ـ ويف يــوم‬\n‫األربع ــاء ‪1434/09/ 16‬ه ـ حســب تقــومي أم القــرى و ‪1434/09/15‬ه ـ‬\n‫حســب الرؤيــة افتتحــت اجللســة الســاعة ‪10.15‬بنــاء علــى ورود املعاملــة‬\n‫أثنــاء إجازتنــا االعتياديــة بشــرح رئيــس احملكمــة علــى القيــد رقــم‬\n‫‪ 341463073‬وتاريــخ ‪1434/07/22‬ه ـ وبرفقــه خطاب رئيس محكمة‬\n‫االســتئناف بالريــاض برقــم ‪ 341463073‬وتاريــخ ‪1434/07/17‬ه ـ‬\n‫وبرفقــه قــرار دائــرة األحــوال الشــخصية الثانيــة برقــم ‪34258270‬‬\n‫وتاريــخ ‪1434/07/03‬ه ـ املتضمــن املصادقــة علــى احلكــم‪ .‬ورفعــت‬\n‫اجللســة يف متــام الســاعة ‪ 10.25‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫الريــاض برقــم‪ 33666540‬وتاريــخ ‪1434/6/12‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ .....‬املســجل برقــم‬\n‫‪ 34180121‬وتاريخ ‪1434/4/6‬هـ اخلاص بدعوى‪ .....‬ضد‪ .....‬يف قضية‬\n‫نفقــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫تقــرر الدائــرة املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى‬\n                                    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                                                             ‫‪70‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":66,"source_page_end":70,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8a6f333e83a6b3492e4885888297d1bc48675d88f8aa7539aaba8542dad6e72f","normalized_text_hash":"b1f86cabca87b7c256e3e76cfae899cf2edf04b7894f6c9c7bab3d492348d42e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p66-34180121"},{"id":"995eb543-d317-51e1-84a3-8bbfeab94e59","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة -طلب الزوجة إعداد مسكن لها -طلب الزوجة نفقتها املاضية -طلب الزوجة إعادة الذهب الذي أخذه الزوج- طلب الزوجة فسخ عقد النكاح يف حال امتناع الزوج عن النفقة- إقامة دعوى النفقة يف بلد الزوجة -إعام املدعى عليه عن طريق اإلعان يف اجلريدة -شهادة الشهود العدول -فسخ عقد النكاح لتضرر الزوجة من التغيب وعدم النفقة -األخذ بشهادة الشهود قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)","document_number":"33268658","case_number":"32242789","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/26","year":"1434","subject":"نفقة -نفقة زوجة -طلب الزوجة إعداد مسكن لها -طلب الزوجة نفقتها املاضية -طلب الزوجة إعادة الذهب الذي أخذه الزوج- طلب الزوجة فسخ عقد النكاح يف حال امتناع الزوج عن النفقة- إقامة دعوى النفقة يف بلد الزوجة -إعام املدعى عليه عن طريق اإلعان يف اجلريدة -شهادة الشهود العدول -فسخ عقد النكاح لتضرر الزوجة من التغيب وعدم النفقة -األخذ بشهادة الشهود قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/5/26 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33268658 :‬‬\n                        ‫َر ْق ُم الدعوى‪32242789 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34193848‬تاريخه‪1434/4/21 :‬هـ‬\n\n\n\n     ‫نفقــة ‪ -‬نفقــة زوجــة‪ -‬طلــب الزوجــة إعــداد مســكن لهــا‪ -‬طلــب الزوجــة‬\n     ‫نفقتهــا املاضيــة‪ -‬طلــب الزوجــة إعــادة الذهــب الــذي أخــذه الــزوج‪-‬‬\n     ‫طلــب الزوجــة فســخ عقــد النــكاح يف حــال امتنــاع الــزوج عــن النفقــة‪-‬‬\n     ‫إقامــة دعــوى النفقــة يف بلــد الزوجــة‪ -‬إعــام املدعــى عليــه عــن طريــق‬\n     ‫اإلعــان يف اجلريــدة‪ -‬شــهادة الشــهود العــدول ‪ -‬فســخ عقــد النــكاح‬\n     ‫لتضــرر الزوجــة مــن التغيــب وعــدم النفقــة‪ -‬األخــذ بشــهادة الشــهود‬\n\n\n\n\n                                     ‫قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)‬\n\n\n\n\n     ‫حضــرت املدعيــة ولــم يحضــر املدعــى عليــه‪ -‬ادعــت املدعيــة بــأن املدعــى‬\n     ‫عليــه تزوجهــا بواليــة والدهــا بتاريــخ ‪1429/6/1‬ه ـ علــى مهــر مســمى‬\n     ‫مســلم ودخــل بهــا الدخــول الشــرعي وبقيــت معــه مــا يقــارب العــام يف‬\n     ‫شــقق مفروشــة ولــدى أســرته ثــم بعــد ذلــك قــام بوضعهــا لــدى أســرتها‬\n     ‫وامتنــع مــن اإلنفــاق عليهــا وإعــداد مســكن لهــا‪ ،‬طلبــت املدعيــة احلكم‬\n     ‫علــى املدعــى عليــه بإعــداد مســكن لهــا ودفــع نفقتهــا املاضيــة وإعــادة‬\n     ‫الذهــب الــذي أخــذه منهــا فــإن امتنــع مــن ذلــك فإنهــا تطلــب فســخ عقــد‬\n     ‫النــكاح منــه‪ -‬جــرت الكتابــة حملكمــة خميــس مشــيط محــل إقامــة‬\n‫‪71‬‬\n\f‫املدعــى عليــه يف ســماع اإلجابــة‪ ،‬ورد اجلــواب بعــدم العثــور علــى املدعــى‬\n‫عليــه‪ -‬جــرى اإلعــان يف اجلريــدة لتبليــغ املدعــى عليــه‪ ،‬يف جلســة أخــرى‬\n‫حضــرت املدعيــة وقــررت أنهــا تطلــب فســخ نكاحهــا مــن املدعــى عليــه‬\n‫لتضررهــا بتغيبــه وعــدم النفقــة‪ ،‬أحضــرت شــاهدين وشــهدا بصحــة مــا‬\n‫ذكرتــه املدعيــة وأن املدعــى عليــه غائــب عــن املدعيــة مــن مــدة تزيــد‬\n‫علــى الســنتني وال ينفــق عليهــا‪ ،‬جــرى تعديــل الشــاهدين‪ ،‬ملــا جــاء يف‬\n‫دعــوى املدعيــة والبينــة املعدلــة وقولــه صلــى اهلل عليــة وســلم (ال ضــرر‬\n‫وال ضــرار) لــذا فقــد فســخ فضيلــة القاضــي نــكاح املدعيــة مــن زوجهــا‬\n‫املدعــى عليــه الغائــب بحضــور وشــهادة الشــاهدين املعرفــن بهــا وبذلــك‬\n‫حكــم‪ ،‬جــرى إفهــام املدعيــة بــأن عليهــا العــدة الشــرعية ثالثــة قــروء‬\n‫مــن تاريــخ صــدور احلكــم وأال تتــزوج إال بعــد اكتســاب احلكــم‬\n‫القطعيــة‪ ،‬لوحــظ علــى احلكــم مــن محكمــة االســتئناف بأنــه لــم يتــم‬\n‫إبــاغ املدعــى عليــه بالدعــوى عــن طريــق اجلهــات الرســمية وأن ينــص يف‬\n‫احلكــم أن الغائــب علــى حجتــه فيمــا يخــص املــال فقــط‪ ،‬جــرى الكتابة‬\n‫لوكيــل إمــارة منطقــة الريــاض للبحــث عــن املدعــى عليــه يف الســجون‬\n‫واملستشــفيات وإفــادة اجلــوازات هــل هــو داخــل أم خــارج اململكــة‪ ،‬ورد‬\n‫اجلــواب مبــا يفيــد بــأن املدعــى عليــه متغيــب ولــم يعثــر عليــه‪ ،‬جــرى‬\n‫التنويــه بــأن املدعــى عليــه الغائــب علــى حجتــه متــى حضــر فيمــا يخــص‬\n                   ‫املــال فقــط‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                   ‫‪72‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بالريــاض برقــم ‪ 32242789‬وتاريــخ ‪ 1432/06/22‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 32741131‬وتاريــخ ‪ 1432/06/19‬ه ـ ففــي يــوم‬\n     ‫األربعــاء املوافــق‪ 1432/12/27‬ه ـ حضرت ‪ ...‬ســعودية اجلنســية مبوجب‬\n     ‫الســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى عليــه وال مــن يقــوم مقامــه‬\n     ‫بوكالــة شــرعية وادعــت علــى الغائــب عــن مجلــس احلكــم ‪ ...‬قائلــة ان‬\n     ‫املدعــى عليــه هــو زوجــي تزوجنــي بعقــد صحيــح بواليــة والــدي بتاريــخ‬\n     ‫‪1429/6/1‬ه ـ علــى مهــر وقــدره خمســة عشــر الــف ريــال مقبوضــة‬\n     ‫ودخــل بــي الدخــول الشــرعي وبقيــت معــه مــا يقــارب العــام يف شــقق‬\n     ‫مفروشــة ولــدى اســرته ثــم بعــد ذلــك قــام بوضعــي لــدى اســرتي وامتنــع‬\n     ‫مــن االنفــاق علــي واعــداد مســكن لــي وهــو حاليــا يقيــم يف محافظــة‬\n     ‫خميــس مشــيط واطلــب احلكــم علــى املدعــى عليــه بإعــداد مســكن‬\n     ‫لــي ودفــع نفقتــي املاضيــة واعــادة الذهــب الــذي اخــذه منــي وان امتنــع‬\n     ‫مــن ذلــك فإننــي اطلــب فســخ نكاحــي منــه هــذه دعــواي ونظــرا لكــون‬\n     ‫املدعــى عليــه يقيــم يف محافظــة خميــس مشــيط فقــد قــررت الكتابــة‬\n     ‫للمحكمــة العامــة بخميــس مشــيط الســتخالف رئيســها او مــن ينيبــه‬\n     ‫مــن قضــاة احملكمــة يف احضــار املدعــى عليــه وســماع اجابتــه علــى‬\n     ‫دعــوى املدعيــة ورفعــت اجللســة حتــى ورود اجلــواب ويف جلســة أخــرى‬\n     ‫لــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة بالريــاض ففــي يــوم اإلثنــن‬\n     ‫املوافق‪1433/05/24‬ه ـ حضــرت املدعيــة واملعــرف بهــا مــن قبــل كل‬\n\n‫‪73‬‬\n\f‫مــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬و ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى عليــه‬\n‫وبتــاوة مــا مت ضبطــه عليهــم صادقــت عليــه كمــا وردنــا خطــاب فضيلــة‬\n‫رئيــس احملكمــة العامــة يف محافظــة خميــس مشــيط رقــم ‪331462‬‬\n‫وتاريــخ ‪1433/3/15‬ه ـ املرفــق بــه خطــاب فضيلــة القاضــي باحملكمــة‬\n‫‪ ...‬املتضمــن أنــه حــددت جلســة للمدعــى عليــه ومت طلبــه ووردت اإلفــادة‬\n‫مــن احملضريــن بعــدم العثــور عليــه واالســتدالل علــى عنوانــه وقــد جــرى‬\n‫اإلعــان عــن طلــب حضــور املدعــى عليــه يف صحيفــة االقتصاديــة‬\n‫بعددهــا رقــم ‪ 6720‬وتاريــخ ‪1433/3/12‬ه ـ وحتديــد هــذا اليــوم موعــدا‬\n‫لنظــر دعــوى املدعيــة ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه‬\n‫وقــررت املدعيــة قائلــة إننــي قــد تضــررت مــن غيــاب زوجــي املدعــى عليــه‬\n‫وعــدم انفاقــه علــي وال أعــرف لــه مــكان إقامــة لــذا فإننــي أطلــب فســخ‬\n‫نكاحــي منــه هــذه دعــواي وبطلــب البينــة منهــا استشــهدت مبــن عــرف‬\n‫بهــا وبســؤالهما شــهدا كل واحــد منهمــا مبفــرده قائــا إن املدعيــة جــارة‬\n‫لــي يف الســكن وأشــهد أن زوجهــا املدعــى عليــه ‪ ...‬غائــب عنهــا منــذ‬\n‫مــدة تزيــد عــن ســنتني وأنــا أعــرف املدعيــة معرفــة تامــة وال ينفــق عليهــا‬\n‫وال يحضــر إليهــا إطالقــا وقــد تضــررت مــن غيابــه فــا يوجــد مــن ينفــق‬\n‫عليهــا وال مــن يقــوم بشــؤونها هكــذا شــهدا وبطلــب معدلــن للشــاهدين‬\n‫أحضــرت كال مــن ‪ ...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ ...‬و‪...‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وشــهدا مبعرفتهمــا‬\n‫للشــاهدين وبثقتهمــا وعدالتهمــا وأنهمــا مقبــوال الشــهادة فبنــاء علــى مــا‬\n‫تقــدم مــن دعــوى املدعيــة وشــهادة الشــاهدين املعدلــن التعديــل الشــرعي‬\n‫واللــذان شــهدا بغيبــة املدعــى عليــه وعــدم إنفاقــه علــى املدعيــة وأنهــا‬\n\n\n                                                                                      ‫‪74‬‬\n\f     ‫تضــررت مــن ذلــك وألنــه ســبق وأن أعلــن يف الصحيفــة املذكــورة عــن‬\n     ‫طلــب املدعــى عليــه ولــم يحضــر ولــم تردنــا أي إفــادة عنــه ولقولــه صلــى‬\n     ‫اهلل عليــه وســلم (ال ضــرر وال ضــرار) وألن املدعيــة قــد تضــررت مــن‬\n     ‫غيــاب املدعــى عليــه وعــدم نفقتــه عليهــا مــدة طويلــة لــذا فســخت نــكاح‬\n     ‫املدعيــة ‪ ...‬مــن زوجهــا املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪...‬‬\n     ‫بحضــور وشــهادة الشــاهدين املعرفــن بهــا وبذلــك حكمــت وأفهمتهــا‬\n     ‫بــأن عليهــا العــدة الشــرعية ثالثــة قــروء مــن تاريــخ اليــوم وأال تتــزوج إال‬\n     ‫بعــد اكتســاب احلكــم الصفــة القطعيــة وأمــرت بتنظيــم الصــك الــازم‬\n     ‫وبعثــه مــع كامــل أوراق املعاملــة إلــى محكمــة االســتئناف وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                         ‫حــرر يف ‪ 1433/05/24‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/4/1‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة الثانيــة والنصــف ظهــرا وقــد وردنــا خطــاب فضيلــة‬\n     ‫رئيــس احملكمــة املســاعد رقــم ‪ 33/1394920‬وتاريــخ ‪1433/7/23‬ه ـ‬\n     ‫شــرح ًا علــى خطــاب فضيلــة رئيــس محكمــة االســتئناف املســاعد رقــم‬\n     ‫‪ 331065922‬وتاريــخ ‪1433/7/15‬ه ـ املرفــق بــه قــرار دائــرة األحــوال‬\n     ‫الشــخصية األولــى رقــم ‪ 33320840‬وتاريــخ ‪1433/6/30‬ه ـ املتضمــن‬\n     ‫(وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لوحــظ مــا يلــي‪:‬‬\n     ‫أوالً‪ /‬لــم يتــم إبــاغ املدعــى عليــه بالدعــوى عــن طريــق اجلهــات الرســمية‬\n     ‫حســبما نصــت عليــه التعليمــات والبــد مــن ذلــك‪ .‬ثاني ـ ًا ‪ /‬علــى فضيلتــه‬\n     ‫أن ينــص أن الغائــب علــى حجتــه فيمــا يخــص املــال فقــط ‪ .‬واهلل املوفــق)‬\n     ‫وعليــه أجيــب أصحــاب الفضيلــة بأنــه قــد جــرى مخاطبــة وكيــل أمــارة‬\n     ‫منطقــة الريــاض باخلطــاب رقــم ‪ 33/1461867‬يف ‪1433/8/4‬ه ـ‬\n\n\n‫‪75‬‬\n\f‫للبحــث عــن املدعــى عليــه يف الســجون واملستشــفيات وإفــادة اجلــوازات‬\n‫وهــل هــو داخــل أم خــارج اململكــة فوردنــا خطــاب مديــر مركــز شــرطة‬\n‫الفيصليــة واخلالديــة رقــم ‪ 12/6/1545/2‬يف ‪1434/3/7‬ه ـ املتضمــن‬\n‫أنــه مت مكاتبــة ســجون منطقــة الريــاض فــورد جوابهــم أنــه ليس مســجل‬\n‫باحلاســب اآللــي لديهــم وكذلــك مخاطبــة جــوازات منطقــة الريــاض ولــم‬\n‫تــرد اإلفــادة مــن قبلهــم أ‪.‬ه ـ وكمــا يتضــح ألصحــاب الفضيلــة أن املدعى‬\n‫عليــه متغيــب ولــم يعثــر عليــه ‪ .‬وأمــا مــا يتعلــق باملالحظــة الثانيــة فــإن‬\n‫املدعــى عليــه الغائــب علــى حجتــه متــى مــا حضــر فيمــا يخــص املــال‬\n‫فقــط وأمــرت باحلــاق ذلــك بالصــك وســجله وإعادتــه مــع كامــل أوراق‬\n‫املعاملــة إلــى محكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة بالريــاض‬\n‫ويف يــوم األربعــاء املوافــق ‪1434/5/1‬ه ـ افتتحــت اجللســة بنــاء علــى مــا‬\n‫وردنــا مــن فضيلــة الرئيــس برقــم ‪ 34/941091‬يف ‪1434/4/29‬ه ـ‬\n‫شــرحا علــى خطــاب رئيــس محكمــة االســتئناف برقــم ‪34941091‬‬\n‫يف ‪1434/4/29‬ه ـ وبرفقــه قــرار الدائــرة احلقوقيــة اخلامســة رقــم‬\n‫‪ 34193848‬يف ‪1434/4/21‬ه ـ واملتضمــن مــا نصــه ( وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه علــى الصــك وصــورة الضبــط‬\n‫بتاريــخ ‪1434/4/1‬ه ـ بنــاء علــى قرارنــا رقــم ‪ 33320840‬وتاريــخ‬\n‫‪1433/6/30‬هـ لم يظهر ما يوجب االعتراض ) ا‪.‬هـ قاضي االستئناف‬\n‫‪ ...‬ختمــه وتوقيعــه وقاضــي االســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫د‪ ... .‬ختمــه وتوقيعــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                               ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/1‬ه ـ‬\n\n\n                                                                                       ‫‪76‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n     ‫لتمييــز قضايــا األحــوال الشــخصية واالنهــاءات مبحكمــة االســتئناف‬\n     ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫بالريــاض املســاعد برقــم ‪ 331394920‬وتاريــخ ‪1434/4/8‬ه ـ املرفــق‬\n     ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...‬املســجل‬\n     ‫برقــم ‪ 33268658‬وتاريــخ ‪1433/5/26‬ه ـ اخلــاص بدعــوى ‪ ......‬ضــد‬\n     ‫‪ ...‬بشــأن طلــب املدعيــة فســخ نكاحهــا مــن املدعــى عليــه ‪ ،‬وقــد‬\n     ‫تضمــن الصــك أن فضيلتــه فســخ نــكاح املدعيــة مــن املدعــى عليــه وبــه‬\n     ‫حكــم ‪ ...‬إلــخ ‪ .‬وحيــث ســبقت دراســة الصــك وصــورة ضبطــه وأوراق‬\n     ‫املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه علــى‬\n     ‫الصــك وصــورة الضبــط بتاريــخ ‪1434/4/1‬ه ـ بنــاء علــى قرارنــا رقــم‬\n     ‫‪ 33320840‬وتاريــخ ‪1433/6/30‬ه ـ لــم يظهــر مــا يوجــب االعتــراض مــع‬\n     ‫تنبيــه فضيلتــه إلــى التهميــش علــى عقــد النــكاح مبــا تقــرر لديــه ‪ .‬واهلل‬\n                  ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪77‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":71,"source_page_end":77,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ab5aa293a82c9a440182a86060e7b58eed80f53c63eeec29ae735c10ae437745","normalized_text_hash":"7c53c02a50d090639694bc68983e135882c7b76166388cde8c48427fad36fc1b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p71-33268658"},{"id":"38187a51-3b32-514b-90d8-896216524c92","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة الزوجة املاضية و املستقبلية -سماع دعوى الزوجة يف بلدها -استخالف المحكمة التي يقيم فيها الزوج لسماع جوابه -ما ورد من إقرار بحكم سابق له حجيته القاطعة -رفض الزوج النفقة بحجة نشوز الزوجة -تقدير النفقة من قبل قسم اخلبراء -رفض الزوجة الرجوع لعدم توفير الزوج للبيت الشرعي ال يسقط حقها يف النفقة -نفقة الزوجة ال تسقط بالتقادم -املطالبة بنفقة","document_number":"33345548","case_number":"3315262","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/16","year":"1434","subject":"نفقة -نفقة الزوجة املاضية و املستقبلية -سماع دعوى الزوجة يف بلدها -استخالف المحكمة التي يقيم فيها الزوج لسماع جوابه -ما ورد من إقرار بحكم سابق له حجيته القاطعة -رفض الزوج النفقة بحجة نشوز الزوجة -تقدير النفقة من قبل قسم اخلبراء -رفض الزوجة الرجوع لعدم توفير الزوج للبيت الشرعي ال يسقط حقها يف النفقة -نفقة الزوجة ال تسقط بالتقادم -املطالبة بنفقة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/7/16 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33345548 :‬‬\n                    ‫َر ْق ُم الدعوى‪3315262 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34166991‬تاريخه‪1434/3/21 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة الزوجــة املاضيــة و املســتقبلية ‪ -‬ســماع دعــوى الزوجــة‬\n‫يف بلدهــا ‪ -‬اســتخالف احملكمــة التــي يقيــم فيهــا الــزوج لســماع جوابــه‬\n‫‪ -‬مــا ورد مــن إقــرار بحكــم ســابق لــه حجيتــه القاطعــة ‪ -‬رفــض الــزوج‬\n‫النفقــة بحجــة نشــوز الزوجــة ‪ -‬تقديــر النفقــة مــن قبــل قســم اخلبــراء‬\n‫‪ -‬رفــض الزوجــة الرجــوع لعــدم توفيــر الــزوج للبيت الشــرعي ال يســقط‬\n‫حقهــا يف النفقــة ‪ -‬نفقــة الزوجــة ال تســقط بالتقــادم ‪ -‬املطالبــة بنفقــة‬\n                                                                      ‫العــدة ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعالــى ‪ ( :‬الرجــال قوامــون علــى النســاء مبــا فضــل اهلل بعضهم‬\n                                    ‫علــى بعــض ومبــا انفقــوا مــن أموالهم )‪.‬‬\n‫‪ -2‬قولــه تعالــي ‪ ( :‬لينفــق ذو ســعة مــن ســعته ومــن قــدر عليــه رزقــه‬\n                                                   ‫فلينفــق ممــا آتــاه اهلل )‪.‬‬\n‫‪ -3‬مــا أخرجــه مســلم يف صحيحــه مــن قولــه النبــي صلــى اهلل عليــه‬\n‫وســلم المــرأة أبــي ســفيان رضــي اهلل عنــه ‪ ( :‬خــذي مــن مالــه باملعــروف‬\n                                                      ‫مــا يكفيــك وولــدك)‪.‬‬\n‫‪ -4‬إجمــاع العلمــاء علــى أن الــزوج يجــب عليــه أن ينفــق علــى زوجتــه‬\n                                                               ‫باملعــروف ‪.‬‬\n‫‪ -5‬مــا ترجــح مــن أقــوال العلمــاء أن نفقــة الزوجــة ال تســقط مبضــي‬\n\n                                                                                   ‫‪78‬‬\n\f     ‫الزمــان بــل تعــد دينـ ًا علــى الــزوج ألنــه مــال يجــب علــى ســبيل البــدل يف‬\n              ‫عقــد معاوضــة جــزاء االحتبــاس فــا تســقط مبضــي الزمــان ‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيــة علــى املدعــى عليــه بإنهــا مكثــت عنــده بعــد الــزواج‬\n     ‫شــهرين ونصــف تقريبــا وبعــد إن طالبتــه بســكن شــرعي ومواصلــة‬\n     ‫الدراســة كمــا هــو مشــروط يف عقــد النــكاح قــام بالذهــاب بهــا‬\n     ‫إلــى بيــت أهلهــا بتاريــخ ‪1431/10/15‬ه ـ بحجــة أنــه مســافر ولــم يقــم‬\n     ‫بإرجاعهــا وال النفقــة عليهــا‪ ،‬ذكــرت املدعيــة بــأن املدعــى عليــه أقــام‬\n     ‫عليهــا دعــوى باالنقيــاد لبيــت الزوجيــة وصــدر احلكــم املكتســب‬\n     ‫للقطعيــة بعــدم اســتحقاقه لالنقيــاد لعــدم وفائــه بشــرط املســكن‬\n     ‫املســتقل‪ ،‬طلبــت املدعيــة إلــزام املدعــى عليــه بدفــع النفقــة املاضيــة‬\n     ‫والنفقــة املســتقبلية‪ ،‬أقــر املدعــى عليــه بالــزواج واملهــر والدخــول وذكــر‬\n     ‫إنهــا بقيــت عنــد أهلهــا ملــدة أربعــة أشــهر وذكــر بأنــه حــاول إرجــاع‬\n     ‫زوجتــه فرفضــت‪ ،‬رفــض املدعــى عليــه دفــع النفقــة املاضيــة واملســتقبلية‬\n     ‫لرفــض املدعيــة الرجــوع‪ ،‬ذكــرت املدعيــة بــأن ســبب رفضهــا الرجــوع‬\n     ‫هــو عــدم توفيــر املدعــى عليــه للبيــت الشــرعي‪ ،‬جــرى الرجــوع إلــى‬\n     ‫صــورة احلكــم املذكــور وقــد تضمــن إن وقــت خــروج املدعيــة هــو كمــا‬\n     ‫جــاء يف دعواهــا كمــا تضمــن احلكــم صــرف النظــر عــن طلــب الــزوج‬\n     ‫إلــزام زوجتــه بالرجــوع لعــدم وفائــه بشــرط املســكن‪ ،‬حلفــت املدعيــة‬\n     ‫إن املدعــى عليــه لــم ينفــق عليهــا خــال املــدة املاضيــة مــدة بقائهــا عنــد‬\n     ‫أهلهــا‪ ،‬جــرى تقديــر النفقــة مــن قبــل قســم اخلبــراء باحملكمــة‪ ،‬قــررت‬\n     ‫املدعيــة ان املدعــى عليــه طلقهــا الحق ـاً‪ ،‬حصــرت املدعيــة دعواهــا يف‬\n‫‪79‬‬\n\f‫املطالبــة بنفقتهــا مــدة بقائهــا عنــد أهلهــا حلــن انتهــاء عدتهــا‪ ،‬حيــث إن‬\n‫النفقــة واجبــة علــى الــزوج باإلجمــاع وحيــث إن نفقــة الزوجــة ال تســقط‬\n‫بالتقــادم لــذا صــدر احلكــم بإلــزام املدعــى عليــه بدفــع نفقــة املدعيــة عــن‬\n          ‫املــدة املدعــى بهــا‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 3315262‬وتاريــخ ‪ 1433/01/05‬ه ـ املقيــدة‬\n‫باحملكمة برقم ‪ 3337873‬وتاريخ ‪ 1433/01/05‬هـ ففي يوم االثنني‬\n‫املوافق‪ 1433/01/24‬هـ أفتتحت اجللسة الساعة ‪ 12 : 19‬وفيها حضر‬\n‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬واملعــرف بهــا مــن‬\n‫قبــل والدهــا‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وادعــت‬\n‫قائلــة أدعــي علــى زوجــي ‪ ...‬حيــث تزوجنــي بواليــة والــدي بصــداق قــدره‬\n‫أربعــون ألــف ريــال مســتلم ودخــل بــي بتاريــخ ‪1431/7/29‬ه ـ وبقيــت‬\n‫عنــده مــدة شــهرين ونصــف تقريبــا وبعــد أن طالبتــه بســكن شــرعي‬\n‫ومواصلــة الدراســة كمــا هــو مشــروط يف عقــد النــكاح قــام بالذهــاب‬\n‫بــي إلــى بيــت أهلــي يف تاريــخ ‪1431/10/15‬ه ـ بحجــة أنــه مســافر ولــم‬\n‫يقــم بإرجاعــي حتــى اآلن وال النفقــة علــي وقــد أقــام ضــدي دعــوى انقيــاد‬\n‫وصــدر احلكــم رقــم ‪ 32356169‬يف ‪1432/12/19‬ه ـ املكتســب‬\n‫للقطعيــة بعــدم اســتحقاقه لالنقيــاد لعــدم وفائــه بشــرط املســكن‬\n‫املســتقل أطلــب إلزامــه بالنفقــة املاضيــة واملســتقبلية هكــذا ادعــت‬\n‫وبســؤالها عــن مــكان إقامــة املدعــى عليــه أجابــت بقولهــا إن املدعــى‬\n\n                                                                                       ‫‪80‬‬\n\f     ‫عليــه يســكن يف املنطقــة الشــرقية باجلبيــل ويعمــل يف القــوات البحريــة‬\n     ‫ورقــم جوالــه ‪ ...‬هكــذا أجابــت لذلــك جــرى إفهــام املدعيــة باملــادة‬\n     ‫رقــم ‪/10/34‬ه ـ مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وبناء‬\n     ‫علــى هــذه املــادة فقــد اســتخلفت رئيــس محكمــة اجلبيــل أو مــن ينيبــه‬\n     ‫مــن القضــاة يف ســماع جــواب املدعــى عليــه وإبالغــه باحلضــور يف املوعــد‬\n     ‫القــادم للجلســة يف يــوم األحــد املوافــق ‪1433/5/2‬ه ـ الســاعة العاشــرة‬\n     ‫والنصــف وبــاهلل التوفيــق ثــم يف يــوم ا ألحــد ‪1433/5/2‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 11.10‬وقــد حضــرت املدعيــة ووالدهــا مــن بدايــة املوعد‬\n     ‫احملــدد وحتــى اآلن لــم يحضــر املدعــى عليــه وقــد وردنــا مــن محكمــة‬\n     ‫اجلبيــل بخطــاب فضيلــة رئيســها رقــم ‪ 33339961‬يف ‪1433/3/16‬هـ ـ‬\n     ‫صــوره مصدقــه مبــا مت ضبطــه لــدى فضيلــة املــازم القضائــي باملكتــب‬\n     ‫القضائــي الثانــي لديهــم الشــيخ ‪ ...‬بعــدد ‪ 33339961‬وفيــه إثبــات‬\n     ‫حضــور املدعــى عليــه أصالــه ‪ ...‬الســعودي اجلنســية بالســجل املدنــي‬\n     ‫رقــم ‪ ...‬ثــم بعــد إفهامــه بالدعــوى جوابــه عنهــا ونصــه ( أجــاب قائــا‬\n     ‫مــا ذكرتــه املدعيــة مــن دعواهــا مــن الــزواج واملهــر والدخــول فكلــه‬\n     ‫صحيــح ومــا ذكرتــه مــن بقائهــا عنــدي بعــد دخولــي بهــا مــدة شــهرين‬\n     ‫ونصــف فغيــر صحيــح والصحيــح أنهــا بقيــت عنــدي مــدة أربعــة اشــهر‬\n     ‫وقــد ذهبــت الــى بيــت أهلهــا بشــهر ذي القعــدة مــن عــام ‪1431‬ه ـ وليــس‬\n     ‫كمــا ذكــرت املدعيــة مــن أنــي ذهبــت بهــا إلــى بيــت أهلهــا بتاريــخ‬\n     ‫‪1431/10/15‬هـ ـ ومــا ذكرتــه مــن أننــي لــم أقــم بإرجاعهــا فغيــر‬\n     ‫صحيــح بــل قمــت بعــدة محــاوالت إلرجاعهــا ولكــن والدهــا ذكــر لــي‬\n     ‫مــرة أنهــا رفضــت الرجــوع إلــي ومــرة أخــرى بقولــه ال مانــع لديــه مــن‬\n     ‫إرجاعهــا ولكــن بشــرط أن ادفــع لهــا مصــروف نفقتهــا املــدة املاضيــة‬\n\n\n‫‪81‬‬\n\f‫ومــا ذكرتــه املدعيــة مــن عــدم النفقــة عليهــا مــن حــن ذهبــت إلــى بيــت‬\n‫أهلهــا حتــى اليــوم فصحيــح فهــي تركــت بيتــي ورفضــت الرجــوع إلــي‬\n‫وأمــا عــن طلــب املدعــى عليهــا بــان ادفــع لهــا نفقتهــا املاضيــة واملســتقبلية‬\n‫فلــن ادفــع لهــا فوالدهــا قــد منعهــا عنــي وكونهــا رفضــت الرجــوع‬\n‫إلــي) ثــم رصــد إبالغــه مبوعــد هــذه اجللســة ولعــدم حضــوره أو تقدميــه‬\n‫لعــذر لغيابــه لــذا قررنــا اســتكمال نظــر القضيــة غيابي ـ ًا ضــد املدعــى‬\n‫عليــه وعليــه أمــرت ببعــث املعاملــة لقســم اخلبــراء لتقديــر نفقــة املدعيــة‬\n‫الشــهرية ولــو بــدون حضــور املدعــى عليــه وبطلــب الصــك الصــادر‬\n‫ســابق ًا بخصــوص االنقيــاد ابرزتــه لنــا وعليــه رفعــت اجللســة الــى الســاعة‬\n‫احلاديــة عشــرة والنصــف مــن يــوم الثالثــاء املوافــق ‪1433/7/15‬ه ـ‬\n‫كمــا امــرت بالكتابــة حملكمــة اجلبيــل إلبــاغ املدعــى عليــه مبوعــد‬\n‫اجللســة القادمــة ابــراء للذمــة وبــاهلل التوفيــق ثــم يف جلســة أخــرى لــدي‬\n‫أنــا ‪ ...‬املــازم القضائــي لــدى فضيلــة الشــيخ ‪ ...‬القاضــي يف احملكمــة‬\n‫العامــة بالريــاض واملكلــف مــن فضيلتــه بنظــر هــذه الدعــوى ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1433/07/15‬ه ـ افتتحــت اجللســة الســاعة وفيهــا‬\n‫حضــرت املدعيــة ووالدهــا ولــم يحضــر املدعــى عليــه وقــد وردنــا مــن‬\n‫مكتــب الصلــح قرارهــم وفيــه تقديرهــم النفقــة بثمامنائــة ريــال شــهريا‬\n‫موقعــا عليــه مــن قبــل مديــر مكتــب الصلــح ‪ ...‬وعضــوي املكتــب ‪ ...‬و‪...‬‬\n‫فســألت املدعيــة هــل أنــت مســتعدة باحللــف علــى أنــك لــم تســتلمي مــن‬\n‫املدعــى عليــه أي نفقــة مــن تاريــخ إخراجــك مــن املنــزل فقالــت نعــم ثــم‬\n‫أذنــت لهــا فتلفظــت قائلــة واهلل العظيــم إن املدعــى عليــه لــم ينفــق علــي‬\n‫ولــم أســتلم منــه شــيئا مــن تاريــخ إخراجــي مــن املنــزل ‪1431/10/15‬ه ـ‬\n‫واهلل العظيــم هكــذا حلفــت ورفعــت اجللســة ثــم يف يــوم األربعــاء املوافــق‬\n\n\n                                                                                         ‫‪82‬‬\n\f     ‫‪ 1433/07/16‬هـ افتتحت اجللســة الســاعة احلادية عشــرة وفيها حضرت‬\n     ‫املدعيــة ووالدهــا ولــم يحضــر املدعــى عليــه وقــررت املدعيــة بقولهــا إن‬\n     ‫املدعــى عليــه طلقنــي يف تاريــخ ‪1433/05/23‬ه ـ لــذا فإننــي أطلــب إلــزام‬\n     ‫املدعــى عليــه بنفقتــي املاضيــة واملســتقبلية إلــى انتهــاء عدتــي والتــي‬\n     ‫تنتهــي يف آخــر شــهر شــعبان واحتياطــا أجعلهــا يف ‪1433/08/23‬ه ـ‬\n     ‫وأطلــب النفقــة املســتقبلية إلــى ‪1433/08/15‬ه ـ وأن تكون يف حســابي‬\n     ‫يف بنــك ‪ ...‬ورقمــه ‪ ...‬ثــم أبــرزت الصــك الصــادر مــن احملكمــة اجلزئيــة‬\n     ‫للضمــان واألنكحــة بالريــاض رقم ‪ 2/99/19‬وتاريــخ ‪1433/05/23‬هـ‬\n     ‫وباالطــاع عليــه وجــد كمــا تقــول املدعيــة وبعــرض جــواب املدعــى عليــه‬\n     ‫الــوارد يف االســتخالف علــى املدعيــة قالــت غيــر صحيــح أنــه أخرجني يف‬\n     ‫شــهر ذي القعــدة بــل الصحيــح أنــه يف شــهر شــوال مــن عــام ‪1431‬ه ـ ومــا‬\n     ‫ذكــره مــن أننــي رفضــت االنقيــاد لــه فصحيــح ألنــه لــم يوفــر الشــروط‬\n     ‫التــي اشــترطتها يف عقــد النــكاح هكــذا قــررت فســألتها البينــة علــى‬\n     ‫وقــت إخراجهــا مــن املنــزل وعلــى أن املدعــى عليــه لــم يلتــزم بالشــروط‬\n     ‫فأبــرزت الصــك الصــادر مــن هــذا املكتــب برقــم ‪ 32356169‬وتاريــخ‬\n     ‫‪1433/12/19‬ه ـ وقالــت فيــه هــذا اإلقــرار مــن املدعــى عليــه يف اجللســة‬\n     ‫التــي بتاريــخ ‪1432/06/05‬ه ـ ونصــه ‪ ( :‬وذهبــت بهــا إلــى أهلهــا يف‬\n     ‫شــهر شــوال املاضــي ) كمــا أن فيــه احلكــم بصــرف النظــر عــن دعــوى‬\n     ‫املدعــى عليــه لعــدم التزامــه بشــروط عقــد النــكاح هكــذا قــررت‬\n     ‫وباالطــاع علــى الصــك وجــد كمــا تقــول املدعيــة فبنــاء علــى مــا تقــدم‬\n     ‫مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه الــوارد يف الصــك الصــادر‬\n     ‫مــن هــذا املكتــب رقــم ‪ 32356169‬وتاريــخ ‪1433/12/19‬ه ـ بأنــه‬\n     ‫ذهــب باملدعيــة إلــى أهلهــا بســبب مشــاكل بينهمــا يف شــهر شــوال مــن‬\n\n\n‫‪83‬‬\n\f‫عــام ‪1431‬ه ـ وإلقــراره الــوارد يف جــواب االســتخالف املرســل حملكمــة‬\n‫اجلبيــل بأنــه لــم يدفــع للمدعيــة شــيئا إلــى تاريــخ إقــراره ‪1433/03/13‬هـ‬\n‫وحللــف املدعيــة علــى أنهــا لــم تســتلم مــن املدعــى عليــه شــيئا مــن تاريــخ‬\n‫إخراجهــا إلــى اليــوم وبنــاء علــى الصــك الســابق احملكــوم فيــه بصــرف‬\n‫النظــر عــن دعــوى املدعــى عليــه وهــي دعــوى طلــب انقيــاد زوجتــه املدعية‬\n‫لعــدم التزامــه بشــروط عقــد النــكاح وملــا أشــار بــه مكتــب الصلــح يف‬\n‫هــذا احملكمــة مــن تقديــر نفقــة املدعيــة بثمامنائــة ريــال شــهريا ولقولــه‬\n‫تعالــى ‪ ( :‬الرجــال قوامــون علــى النســاء مبــا فضــل اهلل بعضهــم علــى‬\n‫بعــض ومبــا أنفقــوا مــن أموالهــم ) وقولــه ‪ ( :‬لينفــق ذو ســعة مــن ســعته‬\n‫ومــن قــدر عليــه رزقــه فلينفــق ممــا آتــاه اهلل ) وملــا أخرجــه مســلم مــن‬\n‫قــول الرســول صلــى اهلل عليــه وســلم المــرأة أبــي ســفيان رضــي اهلل عنــه‬\n‫‪ (( :‬خــذي مــن مالــه باملعــروف مــا يكفيــك ويكفــى بنيــك )) وإلجمــاع‬\n‫العلمــاء علــى أن الــزوج يجــب عليــه أن ينفــق علــى زوجتــه باملعــروف وملــا‬\n‫ترجــح مــن أقــوال العلمــاء أن نفقــة الزوجــة ال تســقط مبضــي الزمــان‬\n‫بــل تعــد دينــا علــى الــزوج ألنــه مــال يجــب علــى ســبيل البــدل يف عقــد‬\n‫معاوضــة جــزاء االحتبــاس فــا تســقط مبضــي الزمــان فبنــاء علــى‬\n‫جميــع مــا تقــدم فقــد حكمــت علــى املدعــى عليــه ‪ ...‬يف حــال غيابــه‬\n‫حكمــا حضوريــا بنــاء علــى املادتــن ‪ 1/55‬و ‪ 4/56‬مــن نظــام املرافعــات‬\n‫الشــرعية لتبلــغ لشــخصه بدفــع النفقــة املاضيــة للمدعيــة ‪ ...‬مــن تاريــخ‬\n‫إخراجهــا مــن املنــزل منتصــف شــهر شــوال عــام ‪1431‬ه ـ إلــى تاريــخ‬\n‫اليــوم وقدرهــا ســتة عشــر ألفــا وثمامنائــة ريــال كمــا حكمــت بإلزامــه‬\n‫بدفــع نفقتهــا املســتقبلية إلــى تاريــخ ‪1433/08/15‬ه ـ وقدرهــا ثمامنائــة‬\n‫ريــال وأن يــودع املبلــغ يف حســاب املدعيــة يف بنــك ‪ ...‬رقــم ‪ ...‬وبعــرض‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫احلكــم علــى املدعيــة قنعــت بــه وأمــرت بإنفــاذ املادتــن ‪ 4/176‬و ‪178‬‬\n     ‫مــن نظــام املرافعــات الشــرعية بخصــوص تبليــغ املدعــى عليــه باحلكــم‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                         ‫حــرر يف ‪ 1433/07/16‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد أطلعــت علــى الالئحــة االعتراضيــة‬\n     ‫املقدمــة مــن املدعــى عليــه أصالــة املقيــدة برقــم ‪ 33/1410568‬يف‬\n     ‫‪1433/07/27‬ه ـ ولــم أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪1433/10/18‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬املــازم القضائــي املكلــف بعمــل‬\n     ‫املكتــب القضائــي احلــادي والثالثــن باحملكمــة العامــة بالريــاض بنــاء‬\n     ‫علــى تكليــف فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد رقــم‬\n     ‫‪ 332183178‬يف ‪1433/12/19‬ه ـ ثــم لقــد عــادت املعاملــة مــن محكمة‬\n     ‫االســتئناف وبرفقهــا قرارهــم رقم ‪ 33476307‬وتاريــخ ‪1433/12/22‬هـ‬\n     ‫وفيــه مــا نصــه ( وبدارســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫واوراق املعاملــة لوحــظ اآلتــي ‪ :‬أو ًال ‪ /‬أن فضيلتــه لــم يــدون يف الصــك‬\n     ‫وصــورة ضبطــه رقــم وتاريــخ قــرار مكتــب الصلــح حيــث ورد يف الصــك‬\n     ‫وصــورة ضبطــه قولــه ( وقــد وردنــا مــن مكتــب الصلــح قرارهــم وفيــه ‪...‬‬\n     ‫الــخ ) ثانيـ ًا ‪ /‬يوجــد ســقط يف الصــك يف نهايــة الصفحــة األولــى وبدايــة‬\n     ‫الصفحــة الثانيــة ممــا ســبب انقطــاع يف الــكالم وال بــد مــن إحلاقــه فعلــى‬\n     ‫فضيلتــه مالحظــة مــا ذكــر وإكمــال مــا يلــزم ) عليــه أجيــب أصحــاب‬\n     ‫الفضيلــة أنــه بخصــوص قــرار مكتــب الصلــح فإنــه ليــس مرقم ـ ًا وال‬\n     ‫مؤرخـ ًا أمــا الســقط الــذي يف الصــك فقــد أمــرت بإعــادة طباعــة الصــك‬\n\n\n‫‪85‬‬\n\f‫ثــم رفــع املعاملــة حملكمــة االســتئناف هــذا مــا يلــزم اإلجابــة عنــه وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                     ‫حــرر يف ‪ 1434/02/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد وردنــا خطــاب رئيــس محكمــة االســتئناف‬\n‫بالريــاض املســاعد رقــم ‪ 34541196‬يف ‪1434/4/1‬ه ـ مرفــق بــه قــرار‬\n‫دائــرة األحــوال الشــخصية ا ألولــى مبحكمــة االســتئناف بالريــاض‬\n‫رقــم ‪ 34166991‬يف ‪1434/3/21‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n‫بعــد اإلجــراء األخيــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/04/17‬ه ـ وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪ 1434/04/16‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي لــدى فضيلــة‬\n‫الشــيخ‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم‬\n‫‪ 3315262‬وتاريــخ ‪ 1433/01/05‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 3337873‬وتاريــخ ‪ 1433/01/05‬ه ـ واملكلــف مــن قبلــه بنظــر هــذه‬\n‫الدعــوى ففــي يــوم اخلميــس املوافــق‪ 1434/09/03‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬حــال‬\n‫كونــه وكيــا عــن ابنتــه ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ...‬مبوجــب الوكالــة رقــم ‪ 34607431‬وتاريــخ ‪1434/5/13‬ه ـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض والتــي تخولــه حــق‬\n‫املرافعــة واملدافعــة واإلقــرار واإلنــكار واســتالم املبالــغ بشــيك أو نقــد‬\n‫وقــرر قائــا لقــد اســتلمت كامــل املبلــغ احملكــوم بــه يف هــذه القضيــة‬\n\n\n                                                                                        ‫‪86‬‬\n\f     ‫بالصــك رقــم ‪ 33345548‬يف ‪1433/7/16‬ه ـ ومقــداره ســتة عشــر ألفـ ًا‬\n     ‫وثمامنائــة ريــال ‪ 16800‬ريــال مبوجــب الشــيك رقــم ‪ 381891‬وتاريــخ‬\n     ‫‪1434/8/28‬ه ـ املســحوب علــى مصــرف ‪ ...‬وبهــذا تكــون هــذه القضيــة‬\n     ‫منتهيــة ولإلثبــات جــرى حتريــره وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/09/03‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتمييــز‬\n     ‫قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف بالرياض‬\n     ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n     ‫املســاعد برقــم ‪ 34/56620‬وتاريــخ ‪1434/2/27‬ه ـ املرفــق بهــا الصــك‬\n     ‫الصــادر مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ‪ ........‬املســجل‬\n     ‫برقــم ‪ ...‬وتاريــخ ‪1433/7/16‬ه ـ اخلــاص بدعــوى ‪ ...‬ضــد ‪ ...‬بشــأن نفقــة‪،‬‬\n     ‫وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n     ‫وحيــث ســبقت دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n     ‫علــى الصــك وصــورة ضبطــه بتاريــخ ‪1434/2/17‬ه ـ بنــاء علــى قــرار‬\n     ‫الدائــرة رقــم ‪ 33476307‬وتاريــخ ‪1433/12/22‬ه ـ لــم يظهــر مــا يوجــب‬\n     ‫االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                                ‫وســلم ‪.‬‬\n\n\n\n\n‫‪87‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":78,"source_page_end":87,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3fb9b13c4b98f41362056b370abbb47273f98931158b9d44e7b3efd116900ccd","normalized_text_hash":"3723bfc8356152bf2a31a1c93ba428970536448622f201a138e07dd2ba7eeaba","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p78-33345548"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
